div.script:
//
document.addEventListener("DOMContentLoaded", function () {
    var guide = document.getElementById("portalFormGuide");
    var step = document.getElementById("portalGuideStep");
    var text = document.getElementById("portalGuideText");
    var status = document.getElementById("portalGuideStatus");
    var missing = document.getElementById("portalGuideMissing");
    var hint = document.getElementById("portalGuideHint");
    var helpBtn = document.getElementById("portalGuideHelpBtn");
    var helpText = document.getElementById("portalGuideHelpText");
    if (!guide || !step || !text || !status || !missing || !hint || !helpBtn || !helpText) {
        return;
    }
    var lastAutoPending = null;
    var autoScrollTimer = null;
    var helpOpen = false;

    function cleanTitle(value) {
        return (value || "").replace(/\s+/g, " ").trim();
    }

    function isVisible(element) {
        if (!element) {
            return false;
        }
        var rect = element.getBoundingClientRect();
        return !!(rect.width || rect.height) && window.getComputedStyle(element).visibility !== "hidden";
    }

    function isFormControl(element) {
        if (!element || !element.tagName) {
            return false;
        }
        var tag = element.tagName.toLowerCase();
        if (tag !== "input" && tag !== "select" && tag !== "textarea") {
            return false;
        }
        var type = (element.type || "").toLowerCase();
        return !(tag === "input" && (type === "hidden" || type === "button" || type === "submit"));
    }

    function labelFor(element) {
        if (!isFormControl(element)) {
            return "";
        }
        var id = element.getAttribute("id");
        var label = id ? document.querySelector('label[for="' + id + '"]') : null;
        if (!label) {
            var row = element.closest(".row, div");
            label = row ? row.querySelector("label, div") : null;
        }
        return cleanTitle(label ? label.textContent : element.getAttribute("name"));
    }

    function isEmptyRequired(element) {
        if (!isFormControl(element) || !isVisible(element) || element.disabled) {
            return false;
        }
        if (!element.required && element.getAttribute("required") === null) {
            return false;
        }
        if (element.type === "file") {
            var msg = document.getElementById("msg_" + element.name);
            var hasMessage = msg && cleanTitle(msg.textContent) && cleanTitle(msg.textContent).toLowerCase().indexOf("error") === -1;
            return !element.files.length && !hasMessage;
        }
        return !cleanTitle(element.value);
    }

    function fieldFromRequiredLabel(label) {
        if (!label || !isVisible(label) || cleanTitle(label.textContent).indexOf("*") === -1) {
            return null;
        }
        var id = label.getAttribute("for");
        if (id) {
            var matches = Array.prototype.slice.call(document.querySelectorAll('[id="' + id.replace(/"/g, '\\"') + '"]'));
            for (var i = 0; i < matches.length; i++) {
                if (isFormControl(matches[i]) && isVisible(matches[i]) && !matches[i].disabled) {
                    return matches[i];
                }
            }
            var byName = document.querySelector('input[name="' + id.replace(/"/g, '\\"') + '"], select[name="' + id.replace(/"/g, '\\"') + '"], textarea[name="' + id.replace(/"/g, '\\"') + '"]');
            if (isFormControl(byName) && isVisible(byName) && !byName.disabled) {
                return byName;
            }
        }
        var row = label.closest(".row, div");
        var candidate = row ? row.querySelector("input:not([type='hidden']):not([type='button']):not([type='submit']), select, textarea") : null;
        return isFormControl(candidate) && isVisible(candidate) && !candidate.disabled ? candidate : null;
    }

    function isEmptyField(element) {
        if (!isFormControl(element) || !isVisible(element) || element.disabled) {
            return false;
        }
        if (element.type === "file") {
            var msg = document.getElementById("msg_" + element.name);
            var hasMessage = msg && cleanTitle(msg.textContent) && cleanTitle(msg.textContent).toLowerCase().indexOf("error") === -1;
            return !element.files.length && !hasMessage;
        }
        return !cleanTitle(element.value);
    }

    function fieldOrderTop(element) {
        if (!element) {
            return 0;
        }
        var row = element.closest(".row, div") || element;
        return row.getBoundingClientRect().top + window.pageYOffset;
    }

    function firstPendingRequired() {
        var pendingFields = [];
        var fields = Array.prototype.slice.call(
            document.querySelectorAll('input[required], select[required], textarea[required], input[required="1"], select[required="1"], textarea[required="1"]')
        );
        for (var i = 0; i < fields.length; i++) {
            if (isEmptyRequired(fields[i])) {
                pendingFields.push(fields[i]);
            }
        }
        var labels = Array.prototype.slice.call(document.querySelectorAll("label"));
        for (var j = 0; j < labels.length; j++) {
            var field = fieldFromRequiredLabel(labels[j]);
            if (isEmptyField(field) && pendingFields.indexOf(field) === -1) {
                pendingFields.push(field);
            }
        }
        pendingFields.sort(function (a, b) {
            return fieldOrderTop(a) - fieldOrderTop(b);
        });
        return pendingFields.length ? pendingFields[0] : null;
    }

    function sectionTitleFor(element) {
        var section = element ? element.closest(".seccion-contenedor, .container-fluid") : null;
        var heading = section ? section.querySelector(".seccion-titulo, h5") : null;
        return cleanTitle(heading ? heading.textContent : "");
    }

    function explanationFor(element) {
        if (!element) {
            return "No hay un campo obligatorio pendiente en este momento. Revisa la información y presiona Enviar cuando todo esté completo.";
        }
        var label = labelFor(element) || "este campo";
        var section = sectionTitleFor(element);
        if (element.type === "file") {
            return "Haz clic en <strong>Seleccionar archivo</strong> y carga: <strong>" + label + "</strong>.";
        }
        if (element.tagName && element.tagName.toLowerCase() === "select") {
            return "Selecciona una opción en: <strong>" + label + "</strong>.";
        }
        if (element.type === "date") {
            return "Ingresa la fecha en: <strong>" + label + "</strong>.";
        }
        if (element.tagName && element.tagName.toLowerCase() === "textarea") {
            return "Escribe la información en: <strong>" + label + "</strong>.";
        }
        return "Llena este campo: <strong>" + label + "</strong>" + (section ? " (<strong>" + section + "</strong>)" : "") + ".";
    }

    function refreshHelpText(element) {
        helpText.innerHTML = explanationFor(element);
        if (helpOpen) {
            helpText.classList.add("show");
        }
    }

    function markAndGo(element) {
        if (!element) {
            status.textContent = "Listo";
            missing.textContent = "No hay campos obligatorios pendientes";
            hint.textContent = "Puedes continuar revisando y enviar cuando todo esté correcto.";
            return;
        }
        document.querySelectorAll(".portal-guide-highlight").forEach(function (item) {
            item.classList.remove("portal-guide-highlight");
        });
        element.classList.add("portal-guide-highlight");
        element.scrollIntoView({ behavior: "smooth", block: "center" });
        setTimeout(function () {
            try { element.focus({ preventScroll: true }); } catch (error) {}
        }, 450);
        setTimeout(function () {
            element.classList.remove("portal-guide-highlight");
        }, 4200);
    }

    function markOnly(element) {
        document.querySelectorAll(".portal-guide-highlight").forEach(function (item) {
            item.classList.remove("portal-guide-highlight");
        });
        if (element) {
            element.classList.add("portal-guide-highlight");
        }
    }

    function autoGoToPending(element) {
        var key = element ? (element.id || element.name || "") : "";
        if (!element || !key || key === lastAutoPending) {
            return;
        }
        lastAutoPending = key;
        clearTimeout(autoScrollTimer);
        autoScrollTimer = setTimeout(function () {
            element.scrollIntoView({ behavior: "smooth", block: "center" });
            setTimeout(function () {
                try { element.focus({ preventScroll: true }); } catch (error) {}
            }, 450);
        }, 250);
    }

    function currentHeading() {
        var headings = Array.prototype.slice.call(
            document.querySelectorAll(".seccion-titulo, .seccion-contenedor h5")
        ).filter(function (item) {
            return item.offsetParent !== null && cleanTitle(item.textContent);
        });

        var active = headings[0];
        headings.forEach(function (item) {
            if (item.getBoundingClientRect().top <= 190) {
                active = item;
            }
        });
        return active ? cleanTitle(active.textContent) : "";
    }

    function updateGuide() {
        var title = currentHeading();
        var upper = title.toUpperCase();
        var pending = firstPendingRequired();
        var pendingLabel = labelFor(pending);
        var pendingSection = sectionTitleFor(pending);
        markOnly(pending);
        autoGoToPending(pending);
        refreshHelpText(pending);

        if (upper.indexOf("DOCUMENTACIÓN") !== -1) {
            step.textContent = "Paso: carga los documentos obligatorios.";
            text.innerHTML = "Carga los archivos marcados con <strong>*</strong>. El formulario muestra automáticamente los documentos que corresponden a tu tipo de persona.";
            status.textContent = pending ? "Pendiente" : "Listo";
            missing.textContent = pendingLabel || (title.indexOf("JURÍDICA") !== -1 ? "Dale a enviar si todo está completo" : "Dale a enviar si todo está completo");
            hint.textContent = pending ? "Pulsa “Mostrar qué hacer” y te llevo al primer pendiente." : "No se detectan documentos obligatorios pendientes.";
            return;
        }

        if (title) {
            step.textContent = "Paso: completa esta sección.";
            text.innerHTML = "Completa primero los datos marcados con <strong>*</strong>. Apenas termines este bloque, continúa bajando y la guía cambiará al siguiente punto.";
            status.textContent = pending ? "Pendiente" : "Listo";
            missing.textContent = pendingLabel || "Dale a enviar si todo está completo";
            hint.textContent = pending ? "Primer pendiente detectado en: " + (pendingSection || "este formulario") + "." : "No se detectan campos obligatorios pendientes.";
            return;
        }

        step.textContent = "Completa los campos obligatorios";
        text.innerHTML = "Apenas completes este punto, el sistema seguirá guiándote con el siguiente dato o documento pendiente.";
        status.textContent = pending ? "Pendiente" : "Listo";
        missing.textContent = pendingLabel || "Campos con *";
        hint.textContent = pending ? "Pulsa el botón de ayuda para ir al campo que falta." : "Todo lo obligatorio parece completo.";
    }

    helpBtn.addEventListener("click", function () {
        var pending = firstPendingRequired();
        updateGuide();
        helpOpen = !helpOpen;
        refreshHelpText(pending);
        helpText.classList.toggle("show", helpOpen);
    });
    updateGuide();
    window.addEventListener("scroll", updateGuide, { passive: true });
    document.addEventListener("change", updateGuide, true);
    document.addEventListener("input", updateGuide, true);
});
//

form.script:
//
    document.addEventListener("DOMContentLoaded", function() {

        const recordIdInput = document.querySelector('input[name="record_id"]');
        const accessTokenInput = document.querySelector('input[name="access_token"]');

        if (!recordIdInput || !accessTokenInput) {
            console.error("Faltan campos ocultos.");
            return;
        }

        const recordId = recordIdInput.value;
        const accessToken = accessTokenInput.value;

        // Función para el Toast
        function showToast(message, type = 'success') {
            let toast = document.getElementById('auto-save-toast');
            if (!toast) {
                toast = document.createElement('div');
                toast.id = 'auto-save-toast';
                Object.assign(toast.style, {
                    position: 'fixed', bottom: '20px', right: '20px',
                    padding: '10px 20px', borderRadius: '5px', color: 'white',
                    fontWeight: 'bold', zIndex: '9999', transition: 'opacity 0.5s'
                });
                document.body.appendChild(toast);
            }
            toast.style.backgroundColor = type === 'success' ? '#28a745' : '#dc3545';
            toast.innerText = message;
            toast.style.opacity = '1';
            setTimeout(() => { toast.style.opacity = '0'; }, 3000);
        }

        const formElements = document.querySelectorAll('input:not([type="file"]):not([type="hidden"]), select, textarea');

        formElements.forEach(element => {
            element.addEventListener('change', function() {
                let fieldName = this.name;
                let value = this.value;
                if (!fieldName) return;

                showToast("Guardando...", "success");

                fetch('/contratista/update_field_ajax', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        params: {
                            record_id: recordId,
                            access_token: accessToken,
                            field_name: fieldName,
                            value: value
                        }
                    })
                })
                .then(response => response.json())
                .then(data => {
                    // AQUÍ ESTABA EL ERROR: El CDATA permite usar && sin problemas
                    if (data.result && data.result.status === 'success') {
                        showToast("✔ Guardado", "success");
                        element.style.borderColor = "#28a745";
                        setTimeout(() => element.style.borderColor = "", 1000);
                    } else {
                        let msg = data.result ? data.result.message : "Error desconocido";
                        showToast("❌ Error: " + msg, "error");
                    }
                })
                .catch(error => showToast("❌ Error de conexión", "error"));
            });
        });
    });
//

div.script:
function toggleFields() {
    var clasePersona = document.querySelector('select[name="clase_persona"]').value;

    if (document.getElementById("documento_identidad")) document.getElementById("documento_identidad").style.display = (clasePersona === "persona_natural") ? "block" : "none";
    if (document.getElementById("ciudad_exp_natural")) document.getElementById("ciudad_exp_natural").style.display = (clasePersona === "persona_natural") ? "block" : "none";
    if (document.getElementById("representante")) document.getElementById("representante").style.display = (clasePersona === "persona_juridica") ? "block" : "none";
    if (document.getElementById("cedula_representante")) document.getElementById("cedula_representante").style.display = (clasePersona === "persona_juridica") ? "block" : "none";
    if (document.getElementById("nit")) document.getElementById("nit").style.display = (clasePersona === "persona_juridica") ? "block" : "none";
    if (document.getElementById("expedicion_contra_j")) document.getElementById("expedicion_contra_j").style.display = (clasePersona === "persona_juridica") ? "block" : "none";
    if (document.getElementById("ciudad_exp_representante")) document.getElementById("ciudad_exp_representante").style.display = (clasePersona === "persona_juridica") ? "block" : "none";
    if (document.getElementById("ciudad_oficina_principal")) document.getElementById("ciudad_oficina_principal").style.display = (clasePersona === "persona_juridica") ? "block" : "none";
    if (document.getElementById("ciudad_natural")) document.getElementById("ciudad_natural").style.display = (clasePersona === "persona_natural") ? "block" : "none";

    if (clasePersona === "persona_natural") {
        if(document.querySelector('input[name="cedula"]')) document.querySelector('input[name="cedula"]').setAttribute("required", "1");
        if(document.querySelector('input[name="ciudad_exp_natural"]')) document.querySelector('input[name="ciudad_exp_natural"]').setAttribute("required", "1");
        if(document.querySelector('input[name="nombre_r_legal"]')) document.querySelector('input[name="nombre_r_legal"]').removeAttribute("required");

        if(document.querySelector('input[name="cedula_representante"]')) document.querySelector('input[name="cedula_representante"]').removeAttribute("required");
        if(document.querySelector('input[name="nit"]')) document.querySelector('input[name="nit"]').removeAttribute("required");
        if(document.querySelector('input[name="ciudad_exp_representante"]')) document.querySelector('input[name="ciudad_exp_representante"]').removeAttribute("required");
        if(document.querySelector('input[name="ciudad_oficina_principal"]')) document.querySelector('input[name="ciudad_oficina_principal"]').removeAttribute("required");
        if(document.querySelector('input[name="municipios2"]')) document.querySelector('input[name="municipios2"]').setAttribute("required", "1");
    } else if (clasePersona === "persona_juridica") {
        if(document.querySelector('input[name="cedula_representante"]')) document.querySelector('input[name="cedula_representante"]').setAttribute("required", "1");
        if(document.querySelector('input[name="nit"]')) document.querySelector('input[name="nit"]').setAttribute("required", "1");
        if(document.querySelector('input[name="ciudad_exp_representante"]')) document.querySelector('input[name="ciudad_exp_representante"]').setAttribute("required", "1");
        if(document.querySelector('input[name="nombre_r_legal"]')) document.querySelector('input[name="nombre_r_legal"]').setAttribute("required", "1");
        if(document.querySelector('input[name="ciudad_oficina_principal"]')) document.querySelector('input[name="ciudad_oficina_principal"]').setAttribute("required", "1");
        if(document.querySelector('input[name="municipios2"]')) document.querySelector('input[name="municipios2"]').removeAttribute("required");
        if(document.querySelector('input[name="expedicion_contra_j"]')) document.querySelector('input[name="expedicion_contra_j"]').removeAttribute("required");
        if(document.querySelector('input[name="cedula"]')) document.querySelector('input[name="cedula"]').removeAttribute("required");
        if(document.querySelector('input[name="ciudad_exp_natural"]')) document.querySelector('input[name="ciudad_exp_natural"]').removeAttribute("required");
    }
}

document.addEventListener("DOMContentLoaded", function() {
    toggleFields();
});

document.addEventListener('DOMContentLoaded', function () {
    // 1. Identificamos los elementos del DOM
    var countrySelect = document.getElementById('country_selector');
    var flagImg = document.getElementById('flag_img');
    var codeDisplay = document.getElementById('phone_code_display');

    // 2. Función que actualiza la vista
    function updatePhoneData() {
        // SEGURIDAD: Si no hay selector o no hay opciones, no hacemos nada
        if (!countrySelect || countrySelect.selectedIndex === -1) return;

        // Obtener la opción seleccionada actualmente
        var selectedOption = countrySelect.options[countrySelect.selectedIndex];

        // SEGURIDAD EXTRA: Verificar que realmente hay una opción
        if (!selectedOption) return;

        // Leer los datos guardados en los atributos data-
        var phoneCode = selectedOption.getAttribute('data-code');       // Ej: 57
        var countryCode = selectedOption.getAttribute('data-code_alpha'); // Ej: co

        // A. Actualizar el texto del Indicativo (+57)
        if (phoneCode) {
            codeDisplay.textContent = "+" + phoneCode;
        } else {
            codeDisplay.textContent = "";
        }

        // B. Actualizar la imagen de la Bandera
        if (countryCode) {
            // Odoo guarda las banderas en esta ruta estándar
            flagImg.src = "/base/static/img/country_flags/" + countryCode.toLowerCase() + ".png";
            flagImg.style.display = "block";
        } else {
            flagImg.style.display = "none";
        }
    }

    // 3. Escuchar cuando el usuario cambia la selección
    if (countrySelect) {
        countrySelect.addEventListener('change', updatePhoneData);

        // 4. Ejecutar una vez al cargar la página
        updatePhoneData();
    }
});

document.addEventListener('DOMContentLoaded', function() {
    const inputWeb = document.getElementById("pagina_web");
    const errorMsg = document.getElementById("error-msg");
    const form = document.querySelector('form');

    // 1. Función de validación de la URL
    function validarPaginaWeb() {
        const value = inputWeb.value.trim();
        const regex = /^(https?:\/\/|www\.)/i;

        if (value !== "") {
            if (!regex.test(value)) {
                // Esto hace que form.checkValidity() sea FALSE
                inputWeb.setCustomValidity("La URL debe iniciar con http, https, www o puedes dejarla en blanco");
                inputWeb.style.borderColor = "red";
                errorMsg.style.display = "block";
            } else {
                inputWeb.setCustomValidity("");
                inputWeb.style.borderColor = "#ccc";
                errorMsg.style.display = "none";
            }
        } else {
            inputWeb.setCustomValidity("");
            inputWeb.style.borderColor = "#ccc";
            errorMsg.style.display = "none";
        }
    }

    // 2. Función para mostrar el indicador de carga
    function showLoadingOverlay() {
        const overlay = document.getElementById('loading-overlay');
        if (overlay) {
            overlay.style.display = 'flex';
            document.body.style.overflow = 'hidden';
        }
    }

    // Escuchar cambios en el input
    inputWeb.addEventListener("input", validarPaginaWeb);

    // 3. Manejo del Submit
    if (form) {
        form.addEventListener('submit', function(event) {
            // Forzamos la validación antes de chequear el formulario
            validarPaginaWeb();

            // Si el formulario tiene errores (incluyendo la URL mal escrita)
            if (!form.checkValidity()) {
                // El navegador mostrará el mensaje de error automáticamente
                return;
            }

            // Si todo está correcto, se muestra el bloqueo de pantalla
            showLoadingOverlay();
        });
    }

    // Validar al cargar por si viene info previa
    validarPaginaWeb();
});

document.addEventListener('DOMContentLoaded', function () {
    // 1. Identificamos los elementos con los NUEVOS IDs COMERCIALES
    var countrySelect = document.getElementById('country_selector_comercial');
    var flagImg = document.getElementById('flag_img_comercial');
    var codeDisplay = document.getElementById('phone_code_display_comercial');

    // 2. Función de actualización
    function updatePhoneDataComercial() {
        if (!countrySelect || countrySelect.selectedIndex === -1) return;

        var selectedOption = countrySelect.options[countrySelect.selectedIndex];
        if (!selectedOption) return;

        var phoneCode = selectedOption.getAttribute('data-code');
        var countryCode = selectedOption.getAttribute('data-code_alpha');

        // Actualizar indicativo
        if (phoneCode) {
            codeDisplay.textContent = "+" + phoneCode;
        } else {
            codeDisplay.textContent = "";
        }

        // Actualizar bandera
        if (countryCode) {
            flagImg.src = "/base/static/img/country_flags/" + countryCode.toLowerCase() + ".png";
            flagImg.style.display = "block";
        } else {
            flagImg.style.display = "none";
        }
    }

    // 3. Escuchar cambios
    if (countrySelect) {
        countrySelect.addEventListener('change', updatePhoneDataComercial);
        updatePhoneDataComercial(); // Ejecutar al inicio
    }
});

