div.script:
document.addEventListener("DOMContentLoaded", function() {
    const clasePersonaSelect = document.querySelector('select[name="clase_persona"]');
    const wrapperImpuestos = document.getElementById('seccion_impuestos_wrapper');

    function toggleImpuestos() {
        if (!clasePersonaSelect || !wrapperImpuestos) return;
        // Si es 'persona_natural', ocultamos toda la sección. Si no, mostramos.
        if (clasePersonaSelect.value === 'persona_natural') {
            wrapperImpuestos.style.display = 'none';
        } else {
            wrapperImpuestos.style.display = 'block';
        }
    }
    if (clasePersonaSelect) {
        clasePersonaSelect.addEventListener('change', toggleImpuestos);
        toggleImpuestos();
    }
});

