div.script:
function updateAcademicRow(select) {
    var row = select.closest('tr');
    var type = select.value;
    var index = row.id.replace('academic_row_', '');
    var title = row.querySelector('.academic-title');
    var year = row.querySelector('.academic-year');
    var fieldNames = {
        pregrado: ['profesion', 'anio_profesion'],
        postgrado: ['postgrado', 'anio_postgrado'],
        otro: ['otro_estudio', 'anio_otro_estudio']
    };
    title.name = `info_ids[${index}][${fieldNames[type][0]}]`;
    year.name = `info_ids[${index}][${fieldNames[type][1]}]`;
    title.placeholder = type === 'pregrado' ? 'Profesión' : 'Título';
    row.querySelectorAll('.academic-professional-card').forEach(function (cell) {
        cell.querySelectorAll('input').forEach(function (input) {
            input.disabled = type !== 'pregrado';
            input.style.display = type === 'pregrado' ? '' : 'none';
        });
    });
    refreshAcademicProfessionalColumns();
}

function refreshAcademicProfessionalColumns() {
    var hasPregrado = Array.from(document.querySelectorAll('#info-body .academic-type')).some(function (select) {
        return select.value === 'pregrado';
    });
    document.querySelectorAll('#info-table .academic-professional-card-header').forEach(function (header) {
        header.style.display = hasPregrado ? '' : 'none';
    });
    document.querySelectorAll('#info-table .academic-professional-card').forEach(function (cell) {
        cell.style.display = hasPregrado ? '' : 'none';
    });
}

