});

div.script:
let rowCount = 1;

function removeRow(el) {
    const tr = el.closest("tr");
    if (tr) {
        tr.remove();
    }
}

function addRow() {
    const tbody = document.getElementById("info-body");

    const tr = document.createElement("tr");

    const fields = [
        { name: "profesion", type: "text" },
        { name: "anio_profesion", type: "date" },
        { name: "postgrado", type: "text" },
        { name: "anio_postgrado", type: "date" },
        { name: "tarjeta_profesional", type: "text" },
        { name: "anio_tarjeta", type: "date" }
    ];

    // Generar inputs para las 6 columnas
    fields.forEach(field => {
        const td = document.createElement("td");
        const input = document.createElement("input");
        input.className = "form-control";
        input.name = `info_ids[${rowCount}][${field.name}]`;
        input.type = field.type;
        td.appendChild(input);
        tr.appendChild(td);
    });

    // Última columna: botón Eliminar
    const tdRemove = document.createElement("td");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "btn btn-danger btn-sm";
    btn.innerText = "Eliminar";
    btn.onclick = function () {
        tr.remove();
    };
    tdRemove.appendChild(btn);
    tr.appendChild(tdRemove);

    tbody.appendChild(tr);
    rowCount++;
}

