t.script:
document.addEventListener("DOMContentLoaded", function() {
    AOS.init({
        duration: 800,
        once: true
    });

    /* --- LÓGICA DE BÚSQUEDA, ORDENAMIENTO Y PAGINACIÓN --- */
    const rowsPerPage = 10;
    let currentPage = 1;
    const searchInput = document.getElementById('search_input');
    const sortSelect = document.getElementById('sort_select'); // Nuevo Selector
    const tableBody = document.querySelector('.modern-table tbody');
    let tableRows = Array.from(tableBody.querySelectorAll('tr'));
    const paginationContainer = document.getElementById('pagination_container');

    function displayRows() {
        const term = searchInput.value.toLowerCase();
        const sortOrder = sortSelect.value;

        // 1. Filtrar por búsqueda
        let filteredRows = tableRows.filter(row => row.textContent.toLowerCase().includes(term));

        // 2. Ordenar
        filteredRows.sort((a, b) => {
            if (sortOrder === 'newest') {
                return b.getAttribute('data-id') - a.getAttribute('data-id');
            } else if (sortOrder === 'oldest') {
                return a.getAttribute('data-id') - b.getAttribute('data-id');
            } else if (sortOrder === 'pago_desc') {
                return parseInt(b.getAttribute('data-pago')) - parseInt(a.getAttribute('data-pago'));
            }
            return 0;
        });

        // 3. Paginación
        const start = (currentPage - 1) * rowsPerPage;
        const end = start + rowsPerPage;

        // Limpiar y reinsertar en el orden correcto
        tableRows.forEach(row => row.style.display = 'none');

        filteredRows.slice(start, end).forEach(row => {
            row.style.display = '';
            tableBody.appendChild(row); // Reinserta para mantener orden visual
        });

        updatePagination(filteredRows.length);
    }

    function updatePagination(totalRows) {
        const pageCount = Math.ceil(totalRows / rowsPerPage);
        paginationContainer.innerHTML = '';
        if (pageCount <= 1) return;

        for (let i = 1; i <= pageCount; i++) {
            const btn = document.createElement('button');
            btn.innerText = i;
            btn.className = 'btn-pagination ' + (i === currentPage ? 'active' : '');
            btn.addEventListener('click', () => {
                currentPage = i;
                displayRows();
                window.scrollTo({top: 0, behavior: 'smooth'});
            });
            paginationContainer.appendChild(btn);
        }
    }

    // Eventos
    if (searchInput) {
        searchInput.addEventListener('keyup', () => {
            currentPage = 1;
            displayRows();
        });
    }
    if (sortSelect) {
        sortSelect.addEventListener('change', () => {
            currentPage = 1;
            displayRows();
        });
    }

    displayRows(); // Carga inicial
});

