div.script:

document.addEventListener('DOMContentLoaded', function () {
    var form = document.querySelector('form[action*="/public/cuentas_de_cobros/save/"]');
    if (!form) return;

    var guide = form.querySelector('[data-sgo-portal-guide="1"]');
    if (!guide) return;

    var title = guide.querySelector('[data-sgo-guide-title="1"]');
    var detail = guide.querySelector('[data-sgo-guide-detail="1"]');
    var status = guide.querySelector('[data-sgo-guide-status="1"]');
    var missing = guide.querySelector('[data-sgo-guide-missing="1"]');
    var beginnerMode = guide.querySelector('[data-sgo-beginner-mode="1"]');
    var explainButton = guide.querySelector('[data-sgo-explain-step="1"]');
    var lastGuidePending = null;
    var autoCorrectionTarget = null;
    var autoActionTarget = null;
    var autoFinalSubmitTarget = null;

    function normalize(text) {
        return (text || '').toString().toLowerCase()
            .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    }

    function isVisible(el) {
        return !!(el && (el.offsetWidth || el.offsetHeight || el.getClientRects().length));
    }

    function labelFor(el) {
        var scope = el.closest('.doc-cell-container, .doc-table-row, tr, .col-md-12, .col-md-6, .col-md-4, .mb-3') || el.parentElement;
        var label = scope ? scope.querySelector('label') : null;
        return label ? label.textContent.replace(/[✔✘]/g, '').replace(/\s+/g, ' ').trim() : (el.name || 'este campo');
    }

    function isFactura(el) {
        return normalize([el.name, el.id, labelFor(el)].join(' ')).indexOf('factura') !== -1;
    }

    function facturaSwitchActive() {
        var switchFactura = form.querySelector('#factura_si_o_no, #factura_si_o_no_view');
        return !!(switchFactura && switchFactura.checked);
    }

    function isFilled(el) {
        if (!isVisible(el) || el.disabled) return true;
        if (isFactura(el) && labelFor(el).indexOf('*') === -1 && !facturaSwitchActive()) return true;
        if (el.type === 'file') return !!(el.files && el.files.length);
        if (el.type === 'checkbox' || el.type === 'radio') return el.checked;
        return !!(el.value && el.value.toString().trim());
    }

    function relationSelector() {
        var names = [
            'relacion_fuv_id',
            'relacion_orden_compra_servicios_fuv_id',
            'relacion_orden_compra_bienes_fuv_id',
            'relacion_otrosi_fuv_id'
        ];
        for (var i = 0; i < names.length; i++) {
            var el = form.querySelector('[name="' + names[i] + '"]');
            if (isVisible(el)) return el;
        }
        return null;
    }

    function requiredDocumentInputs() {
        var inputs = Array.prototype.slice.call(form.querySelectorAll('input[type="file"]'));
        var requiredDocumentNames = [
            'planilla_de_aportes_a_seguridad_social_doc',
            'planilla_de_seguridad_social_ju_doc',
            'rut_actualizado_doc',
            'rut_actualizado_juridica_documento',
            'camara_comercio_juridica_documento',
            'certificado_pago_parafiscales_juridica_documento'
        ];
        return inputs.filter(function (input) {
            if (!isVisible(input)) return false;
            var label = normalize(labelFor(input));
            if (isFactura(input) && label.indexOf('*') === -1 && !facturaSwitchActive()) return false;
            if (input.name && input.name.indexOf('_replace_file') !== -1) {
                var cell = input.closest('.doc-cell-container');
                var correctionMark = cell ? cell.querySelector('label .text-danger') : null;
                if (correctionMark && isVisible(correctionMark)) return true;
                return false;
            }
            if (requiredDocumentNames.indexOf(input.name || input.id || '') !== -1) return true;
            return label.indexOf('*') !== -1 && label.indexOf('opcional') === -1 && label.indexOf('si aplica') === -1;
        });
    }

    function pendingActionButtons() {
        return Array.prototype.slice.call(form.querySelectorAll('a[href*="/public/declaracion_juramentada/"], a[href*="/public/informe_actividades/"]'))
            .filter(function (el) {
                return isVisible(el) && el.getAttribute('data-sgo-required') !== '0' && el.getAttribute('href') !== '#' && !el.classList.contains('disabled') && el.style.pointerEvents !== 'none';
            });
    }

    function correctionActionFor(label) {
        var normalizedLabel = normalize(label);
        return pendingActionButtons().find(function (link) {
            var text = normalize(link.textContent);
            if (normalizedLabel.indexOf('documento equivalente') !== -1 || normalizedLabel.indexOf('declaracion') !== -1) {
                return text.indexOf('corregir') !== -1 && (text.indexOf('doc') !== -1 || text.indexOf('declaracion') !== -1);
            }
            if (normalizedLabel.indexOf('informe de actividades') !== -1) {
                return text.indexOf('corregir') !== -1 && text.indexOf('informe') !== -1;
            }
            return false;
        });
    }

    function correctionSteps() {
        var cells = Array.prototype.slice.call(form.querySelectorAll('.doc-cell-container'));
        var steps = [];

        cells.forEach(function (cell) {
            var danger = cell.querySelector('label .text-danger');
            if (!danger || !isVisible(danger)) return;

            var label = labelFor(cell);
            var fileInput = cell.querySelector('input[type="file"][name$="_replace_file"]');
            if (fileInput && isVisible(fileInput)) {
                if (!isFilled(fileInput)) {
                    steps.push({el: fileInput, label: 'Corregir ' + label});
                }
                return;
            }

            var action = correctionActionFor(label);
            if (action) {
                steps.push({el: action, label: action.textContent.replace(/\s+/g, ' ').trim()});
            } else {
                steps.push({el: cell, label: 'Corregir ' + label});
            }
        });

        return steps.filter(function (step, index, arr) {
            return step.el && arr.findIndex(function (other) { return other.el === step.el; }) === index;
        });
    }

    function orderedSteps() {
        var steps = [];
        var esRegalias = form.dataset.origenCuenta === 'regalias';
        var camposIniciales = [
            '[name="fecha_solicitud"]',
            '[name="nombre_entrega"]',
            '[name="valor_cuenta"]',
            '[name="pago"]',
            '[name="inicio_actividad"]',
            '[name="finalizacion_actividad"]'
        ];
        if (!esRegalias) camposIniciales.unshift('[name="selecionar"]');
        camposIniciales.forEach(function (selector) {
            var el = form.querySelector(selector);
            if (el) steps.push({el: el, label: labelFor(el)});
        });

        var relation = relationSelector();
        if (relation) steps.splice(1, 0, {el: relation, label: labelFor(relation)});

        if (facturaSwitchActive()) {
            var numeroFactura = form.querySelector('[name="numero_factura"]');
            var archivoFactura = form.querySelector('[name="factura_doc"]');
            if (numeroFactura) {
                steps.push({el: numeroFactura, label: 'Número de factura', facturaNumero: true});
            }
            if (archivoFactura) {
                steps.push({el: archivoFactura, label: 'Documento de factura', facturaArchivo: true});
            }
        }

        requiredDocumentInputs().forEach(function (input) {
            steps.push({el: input, label: labelFor(input)});
        });

        pendingActionButtons().forEach(function (link) {
            steps.push({el: link, label: link.textContent.replace(/\s+/g, ' ').trim(), action: true});
        });

        return steps.filter(function (step, index, arr) {
            return step.el && arr.findIndex(function (other) { return other.el === step.el; }) === index;
        });
    }

    function firstPending() {
        var corrections = correctionSteps();
        if (corrections.length) {
            return {step: corrections[0], index: 1, total: corrections.length, correction: true};
        }

        var steps = orderedSteps();
        for (var i = 0; i < steps.length; i++) {
            if (!isFilled(steps[i].el)) return {step: steps[i], index: i + 1, total: steps.length - i};
        }
        return null;
    }

    function clearHighlights() {
        form.querySelectorAll('.sgo-pending-highlight').forEach(function (el) {
            el.classList.remove('sgo-pending-highlight');
        });
    }

    function focusPending(pending) {
        clearHighlights();
        if (!pending) return;
        var el = pending.step.el;
        var target = el.closest('.doc-cell-container, .modern-card, .col-md-12, .col-md-6, .col-md-4') || el;
        el.classList.add('sgo-pending-highlight');
        if (target !== el) target.classList.add('sgo-pending-highlight');
        target.scrollIntoView({behavior: 'smooth', block: 'center'});
        setTimeout(function () {
            try { el.focus({preventScroll: true}); } catch (err) {}
        }, 450);
    }

    function finalSubmitButton() {
        var button = form.querySelector('#btn_guardar_cuenta');
        return isVisible(button) && !button.disabled ? button : null;
    }

    function focusFinalSubmit() {
        var button = finalSubmitButton();
        if (!button) return;
        clearHighlights();
        button.classList.add('sgo-pending-highlight');
        button.scrollIntoView({behavior: 'smooth', block: 'center'});
        setTimeout(function () {
            try { button.focus({preventScroll: true}); } catch (err) {}
        }, 450);
    }

    function setGuideShortcut(pending) {
        if (pending && pending.correction) {
            guide.style.cursor = '';
            guide.removeAttribute('title');
            if (explainButton) {
                explainButton.innerHTML = '<i class="fa fa-question-circle mr-1"></i> Mostrar qué hacer';
            }
        } else {
            guide.style.cursor = '';
            guide.removeAttribute('title');
            if (explainButton) {
                explainButton.innerHTML = '<i class="fa fa-question-circle mr-1"></i> Mostrar qué hacer';
            }
        }
    }

    function autoFocusCorrection(pending) {
        if (pending && pending.correction) {
            if (autoCorrectionTarget !== pending.step.el) {
                autoCorrectionTarget = pending.step.el;
                setTimeout(function () {
                    focusPending(pending);
                }, 350);
            }
        } else {
            autoCorrectionTarget = null;
        }
    }

    function autoFocusAction(pending) {
        if (pending && pending.step && pending.step.action) {
            if (autoActionTarget !== pending.step.el) {
                autoActionTarget = pending.step.el;
                setTimeout(function () {
                    focusPending(pending);
                }, 350);
            }
        } else {
            autoActionTarget = null;
        }
    }

    function autoFocusFinalSubmit() {
        var button = finalSubmitButton();
        if (!button) {
            autoFinalSubmitTarget = null;
            return;
        }
        if (autoFinalSubmitTarget !== button) {
            autoFinalSubmitTarget = button;
            setTimeout(function () {
                focusFinalSubmit();
            }, 350);
        }
    }

    function updateGuide() {
        var pending = firstPending();
        lastGuidePending = pending;
        clearHighlights();
        if (pending) {
            if (pending.correction) {
                title.textContent = 'Corrección pendiente: ' + pending.step.label + '.';
                detail.textContent = 'El asistente solicitó corregir este documento. Actualízalo y luego usa Finalizar y enviar para reenviar la cuenta.';
                if (status) status.textContent = pending.total > 1 ? 'En corrección' : 'Última corrección';
                if (missing) missing.textContent = pending.step.label;
                setGuideShortcut(pending);
                autoFocusCorrection(pending);
                return pending;
            }

            title.textContent = 'Paso ' + pending.index + ': completa ' + pending.step.label + '.';
            if (pending.step.label === 'Crear informe de actividades' && pending.total === 1) {
                detail.textContent = 'Después de crear el informe de actividades, ya puedes usar el botón Finalizar y enviar.';
            } else if (pending.step.facturaNumero) {
                detail.textContent = 'Activaste factura. Primero escribe el número de la factura en este campo.';
            } else if (pending.step.facturaArchivo) {
                detail.textContent = 'Ahora sube el documento de la factura para dejar el soporte completo.';
            } else {
                detail.textContent = 'Apenas completes este punto, el sistema seguirá guiándote con el siguiente dato o documento pendiente.';
            }
            if (status) status.textContent = pending.total > 1 ? 'En proceso' : 'Último pendiente';
            if (missing) missing.textContent = pending.step.label;
            autoFocusAction(pending);
        } else {
            title.textContent = 'Todo listo: puedes finalizar y enviar.';
            detail.textContent = 'No quedan campos requeridos pendientes. Presiona el botón Finalizar y enviar para completar el proceso.';
            if (status) status.textContent = 'Listo para enviar';
            if (missing) missing.textContent = 'Finalizar y enviar';
            var submitButton = finalSubmitButton();
            if (submitButton) submitButton.classList.add('sgo-pending-highlight');
            autoFocusFinalSubmit();
        }
        setGuideShortcut(pending);
        autoFocusCorrection(pending);
        autoFocusAction(pending);
        if (pending) autoFinalSubmitTarget = null;
        return pending;
    }

    function advanceToNextPending() {
        var pending = updateGuide();
        if (pending) {
            focusPending(pending);
        } else {
            focusFinalSubmit();
        }
    }

    function updateAndMaybeMove() {
        updateGuide();
        if (beginnerMode && beginnerMode.checked) {
            advanceToNextPending();
        }
    }

    form.addEventListener('change', function () {
        setTimeout(updateAndMaybeMove, 120);
    });
    form.addEventListener('input', updateGuide);
    form.addEventListener('blur', function (event) {
        if (event.target && isFilled(event.target) && beginnerMode && beginnerMode.checked) {
            setTimeout(advanceToNextPending, 120);
        }
    }, true);
    if (beginnerMode) {
        beginnerMode.addEventListener('change', function () {
            if (this.checked) {
                advanceToNextPending();
            } else {
                updateGuide();
            }
        });
    }
    if (explainButton) {
        explainButton.addEventListener('click', function (event) {
            event.preventDefault();
            setTimeout(advanceToNextPending, 0);
        });
    }
    setTimeout(updateGuide, 250);
});

// 
document.addEventListener('DOMContentLoaded', function () {
    var inputCuenta = document.getElementById('valor_cuenta_web');
    var inputTotal = document.getElementById('valor_total_web');
    var selectPrincipal = document.getElementById('seleccionar');
    var inputPorcentaje = document.getElementById('porcentaje_pago_web');
    var inputPorcentajeAcumulado = document.getElementById('porcentaje_acumulado_web');
    var inputNumeroPago = document.querySelector('input[name="pago"]');
    var inputDesembolsoOrigen = document.getElementById('pago_forma_pago_edit');
    var pagosContractuales = [];
    var esperandoPagosContractuales = false;
    var pagoCargadoDesdeTabla = false;
    var formularioCuenta = inputCuenta ? inputCuenta.closest('form') : null;
    var esCuentaRegalias = Boolean(
        formularioCuenta
        && formularioCuenta.dataset.origenCuenta === 'regalias'
    );

    function tipoActualSeleccionado() {
        return selectPrincipal ? selectPrincipal.value : '';
    }

    function bloquearValorCuenta(mensaje) {
        if (!inputCuenta) return;
        inputCuenta.setAttribute('readonly', 'readonly');
        inputCuenta.placeholder = mensaje || 'Primero selecciona el desembolso';
        pagoCargadoDesdeTabla = false;
    }

    function habilitarValorCuenta() {
        if (!inputCuenta) return;
        inputCuenta.removeAttribute('readonly');
        inputCuenta.placeholder = '0,00';
    }

    function esOtroSiPagoManual() {
        if (tipoActualSeleccionado() !== 'otrosi' || !inputCuenta) return false;
        if (inputDesembolsoOrigen && inputDesembolsoOrigen.value) return false;
        if (inputCuenta.dataset.formaPagoManual === '1') return true;
        if (esperandoPagosContractuales || !inputNumeroPago) return false;
        var numeroPago = parseInt(inputNumeroPago.value, 10);
        if (!numeroPago || numeroPago < 1) return false;
        return !pagosContractuales.some(function(item) {
            return parseInt(item.numero_de_pagos, 10) === numeroPago;
        });
    }

    function actualizarBloqueoValorCuenta() {
        if (!inputCuenta) return;
        if (esCuentaRegalias) {
            habilitarValorCuenta();
        } else if (esOtroSiPagoManual()) {
            habilitarValorCuenta();
            inputCuenta.placeholder = 'Escribe el valor manualmente';
        } else if (['contrato', 'otrosi'].indexOf(tipoActualSeleccionado()) !== -1 && !pagoCargadoDesdeTabla) {
            bloquearValorCuenta('Primero selecciona el desembolso');
        } else if (['contrato', 'otrosi'].indexOf(tipoActualSeleccionado()) === -1) {
            habilitarValorCuenta();
        }
    }

    // Selectores de relaciones
    var selectContrato = document.querySelector('select[name="relacion_fuv_id"]');
    var selectOtrosi = document.querySelector('select[name="relacion_otrosi_fuv_id"]');
    var selectBienes = document.querySelector('select[name="relacion_orden_compra_bienes_fuv_id"]');
    var selectServicios = document.querySelector('select[name="relacion_orden_compra_servicios_fuv_id"]');

    // Contenedores
    var contenedorTablaPagos = document.getElementById('contenedor_tabla_pagos');

    // ==========================================
    // UTILIDADES DE FORMATO
    // ==========================================
    function aplicarFormato(numero) {
        if (isNaN(numero) || numero === null || numero === '') return "0,00";
        return new Intl.NumberFormat('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(numero);
    }

    function limpiar(texto) {
        if (!texto) return 0;
        let s = texto.toString().trim();
        return s.includes(',') ? (parseFloat(s.replace(/\./g, '').replace(',', '.')) || 0) : (parseFloat(s) || 0);
    }

    function actualizarPorcentajePago() {
        if (!inputPorcentaje || !inputCuenta || !inputTotal) return;
        var numeroPago = inputNumeroPago ? parseInt(inputNumeroPago.value, 10) : 0;
        var cuota = pagosContractuales.find(item => parseInt(item.numero_de_pagos, 10) === numeroPago);
        var valorCuenta = limpiar(inputCuenta.value);
        if (cuota) {
            var valorCuota = Number(cuota.cantidad_de_dinero || 0);
            if (Math.abs(valorCuenta - valorCuota) < 0.01) {
                inputPorcentaje.value = Number(cuota.porcentaje_pago || 0).toFixed(2);
                if (inputPorcentajeAcumulado) inputPorcentajeAcumulado.value = Number(cuota.porcentaje_acumulado || 0).toFixed(2);
                return;
            }
        }
        var tipoActual = selectPrincipal ? selectPrincipal.value : '';
        if (esperandoPagosContractuales) {
            inputPorcentaje.value = '';
            if (inputPorcentajeAcumulado) inputPorcentajeAcumulado.value = '';
            return;
        }
        var valorTotal = limpiar(inputTotal.value);
        if (valorCuenta > 0 && valorTotal > 0) {
            inputPorcentaje.value = ((valorCuenta / valorTotal) * 100).toFixed(2);
            if (inputPorcentajeAcumulado) inputPorcentajeAcumulado.value = inputPorcentaje.value;
        } else {
            inputPorcentaje.value = '';
            if (inputPorcentajeAcumulado) inputPorcentajeAcumulado.value = '';
        }
    }

    function cuotaSeleccionada() {
        var numeroPago = inputDesembolsoOrigen
            ? parseInt(inputDesembolsoOrigen.value, 10)
            : (inputNumeroPago ? parseInt(inputNumeroPago.value, 10) : 0);
        return pagosContractuales.find(item => parseInt(item.numero_de_pagos, 10) === numeroPago);
    }

    function seleccionarDesembolso(item, fila) {
        if (!inputNumeroPago || !inputCuenta) return;
        if (item.bloqueado || Number(item.valor_disponible || 0) <= 0) {
            return;
        }
        pagoCargadoDesdeTabla = true;
        habilitarValorCuenta();
        inputNumeroPago.value = item.numero_de_pagos || '';
        if (inputDesembolsoOrigen) inputDesembolsoOrigen.value = item.numero_de_pagos || '';
        inputCuenta.value = aplicarFormato(Number(item.valor_disponible || item.cantidad_de_dinero || 0));
        var tbody = document.getElementById('tbody_pagos');
        if (tbody) {
            tbody.querySelectorAll('tr').forEach(function(row) {
                row.classList.remove('table-primary');
                row.setAttribute('aria-selected', 'false');
            });
        }
        fila.classList.add('table-primary');
        fila.setAttribute('aria-selected', 'true');
        actualizarPorcentajePago();
        var modalFormaPago = document.getElementById('modalFormaPago');
        if (modalFormaPago) {
            var cerrarModal = modalFormaPago.querySelector('[data-bs-dismiss="modal"]');
            if (cerrarModal) cerrarModal.click();
        }
    }

    function seleccionarLineaOrden(valor, fila, tbody, modalId) {
        if (!inputCuenta) return;
        habilitarValorCuenta();
        inputCuenta.value = aplicarFormato(Number(valor || 0));
        if (tbody) {
            tbody.querySelectorAll('tr').forEach(function(row) {
                row.classList.remove('table-primary');
                row.setAttribute('aria-selected', 'false');
            });
        }
        fila.classList.add('table-primary');
        fila.setAttribute('aria-selected', 'true');
        actualizarPorcentajePago();
        inputCuenta.dispatchEvent(new Event('change', { bubbles: true }));

        var modal = document.getElementById(modalId);
        if (modal) {
            var cerrar = modal.querySelector('[data-bs-dismiss="modal"]');
            if (cerrar) cerrar.click();
        }
    }

    function validarDesembolso() {
        var tipoActual = selectPrincipal ? selectPrincipal.value : '';
        if (['contrato', 'otrosi'].indexOf(tipoActual) === -1) return true;
        if (esOtroSiPagoManual()) return true;
        var cuota = cuotaSeleccionada();
        if (!cuota || !pagoCargadoDesdeTabla) return false;
        return limpiar(inputCuenta.value) <= Number(cuota.valor_disponible || cuota.cantidad_de_dinero || 0);
    }

    // ==========================================
    // CARGA DE TABLAS (AJAX)
    // ==========================================

    // 1. Historial de Pagos
    function cargarTablaPagos(id, tipoRelacion) {
        if (!id) return;
        esperandoPagosContractuales = true;
        pagosContractuales = [];
        pagoCargadoDesdeTabla = false;
        if (inputCuenta) delete inputCuenta.dataset.formaPagoManual;
        if(inputPorcentaje) inputPorcentaje.value = '';
        var tbody = document.getElementById('tbody_pagos');
            if(tbody) tbody.innerHTML = '<tr><td colspan="4" class="text-center py-2"><i class="fa fa-spinner fa-spin"></i></td></tr>';
        if(contenedorTablaPagos) contenedorTablaPagos.style.display = 'block';

        var url = '/public/cuentas_de_cobros/obtener_pagos' + (tipoRelacion === 'contrato' ? '?contrato_id=' : '?otrosi_id=') + id + '&_=' + Date.now();
        var documentoInput = document.querySelector('[name="documento_de_identificacion"]');
        var nombreInput = document.querySelector('[name="nombre_contratista"], [name="name"]');
        if (documentoInput && documentoInput.value) {
            url += '&identificacion=' + encodeURIComponent(documentoInput.value);
        }
        if (nombreInput && nombreInput.value) {
            url += '&nombre=' + encodeURIComponent(nombreInput.value);
        }
        url += '&cuenta_id=' + encodeURIComponent('<t t-esc="record.id"/>');

        fetch(url, {cache: 'no-store'})
            .then(r => r.json())
            .then(data => {
                tbody.innerHTML = '';
                pagosContractuales = data.pagos || [];
                if (data.pagos && data.pagos.length > 0) {
                    data.pagos.forEach(item => {
                        var fila = document.createElement('tr');
                        var disponible = Number(item.valor_disponible || 0);
                        var fisico = Number(item.valor_cobrado_fisico || 0);
                        var sgo = Number(item.valor_cobrado_sgo || 0);
                        if (item.bloqueado || disponible <= 0) {
                            fila.classList.add('table-danger');
                        } else if (fisico > 0 || sgo > 0) {
                            fila.classList.add('table-warning');
                        }
                        fila.setAttribute('role', 'button');
                        fila.setAttribute('tabindex', '0');
                        fila.style.cursor = (item.bloqueado || disponible <= 0) ? 'not-allowed' : 'pointer';
                        fila.title = (item.bloqueado || disponible <= 0)
                            ? 'Este desembolso ya no tiene saldo disponible.'
                            : 'Disponible para cobrar: $' + aplicarFormato(disponible || item.cantidad_de_dinero || 0);
                        fila.innerHTML = `
                            <td class="text-center">${item.numero_de_pagos || ''}</td>
                            <td class="text-end">$${aplicarFormato(item.cantidad_de_dinero)}</td>
                            <td class="text-center">${aplicarFormato(item.porcentaje_pago)}%</td>
                            <td class="text-center">${aplicarFormato(item.porcentaje_acumulado)}%</td>
                        `;
                        if (parseInt(item.numero_de_pagos, 10) === parseInt(inputDesembolsoOrigen && inputDesembolsoOrigen.value, 10)) {
                            fila.classList.add('table-primary');
                            fila.setAttribute('aria-selected', 'true');
                            if (!item.bloqueado && disponible > 0) {
                                pagoCargadoDesdeTabla = true;
                                habilitarValorCuenta();
                            }
                        } else {
                            fila.setAttribute('aria-selected', 'false');
                        }
                        fila.addEventListener('click', function() { seleccionarDesembolso(item, fila); });
                        fila.addEventListener('keydown', function(event) {
                            if (event.key === 'Enter' || event.key === ' ') {
                                event.preventDefault();
                                seleccionarDesembolso(item, fila);
                            }
                        });
                        tbody.appendChild(fila);
                    });
                } else if (tipoRelacion === 'otrosi' && inputCuenta) {
                    inputCuenta.dataset.formaPagoManual = '1';
                    if (tbody) {
                        tbody.innerHTML = '<tr><td colspan="4" class="text-center text-muted py-3">Este otrosí no tiene registros en la tabla de Forma de pago. Puede ingresar el valor manualmente.</td></tr>';
                    }
                }
                esperandoPagosContractuales = false;
                actualizarBloqueoValorCuenta();
                actualizarPorcentajePago();
            })
            .catch(() => {
                esperandoPagosContractuales = false;
            });
    }

    // 2. Líneas de Bienes
    function cargarLineasBienes(ordenId) {
        if (!ordenId) return;
        var tbody = document.getElementById('tbody_lineas_bienes');
        if (!tbody) return;
        tbody.innerHTML = '<tr><td colspan="4" class="text-center py-3"><i class="fa fa-spinner fa-spin"></i></td></tr>';

        fetch('/public/obtener_lineas_bienes', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ params: { orden_id: ordenId } })
        }).then(r => r.json()).then(data => {
            var res = data.result;
            tbody.innerHTML = '';
            if (res.lineas && res.lineas.length > 0) {
                res.lineas.forEach(l => {
                    var fila = document.createElement('tr');
                    fila.setAttribute('role', 'button');
                    fila.setAttribute('tabindex', '0');
                    fila.setAttribute('aria-selected', 'false');
                    fila.style.cursor = 'pointer';
                    fila.title = 'Seleccionar este valor para la cuenta';
                    fila.innerHTML = `<td>${l.descripcion}</td><td class="text-center">${l.cantidad}</td><td class="text-end">$${aplicarFormato(l.valor_unitario)}</td><td class="text-end">$${aplicarFormato(l.valor_total)}</td>`;
                    fila.addEventListener('click', function() {
                        seleccionarLineaOrden(l.valor_total, fila, tbody, 'modalFormaBienes');
                    });
                    fila.addEventListener('keydown', function(event) {
                        if (event.key === 'Enter' || event.key === ' ') {
                            event.preventDefault();
                            seleccionarLineaOrden(l.valor_total, fila, tbody, 'modalFormaBienes');
                        }
                    });
                    tbody.appendChild(fila);
                });
            } else {
                tbody.innerHTML = '<tr><td colspan="4" class="text-center text-muted py-3">Esta orden no tiene líneas de bienes.</td></tr>';
            }
        });
    }

    // 3. Líneas de Servicios
    function cargarLineasServicios(ordenId) {
        if (!ordenId) return;
        var tbody = document.getElementById('tbody_lineas_servicios');
        if (!tbody) return;
        tbody.innerHTML = '<tr><td colspan="2" class="text-center py-3"><i class="fa fa-spinner fa-spin"></i></td></tr>';

        fetch('/public/obtener_lineas_servicios', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ params: { orden_id: ordenId } })
        }).then(r => r.json()).then(data => {
            var res = data.result;
            tbody.innerHTML = '';
            if (res.lineas && res.lineas.length > 0) {
                res.lineas.forEach(l => {
                    var fila = document.createElement('tr');
                    fila.setAttribute('role', 'button');
                    fila.setAttribute('tabindex', '0');
                    fila.setAttribute('aria-selected', 'false');
                    fila.style.cursor = 'pointer';
                    fila.title = 'Seleccionar este valor para la cuenta';
                    fila.innerHTML = `<td>${l.descripcion}</td><td class="text-end">$${aplicarFormato(l.valor_unitario)}</td>`;
                    fila.addEventListener('click', function() {
                        seleccionarLineaOrden(l.valor_unitario, fila, tbody, 'modalFormaServicios');
                    });
                    fila.addEventListener('keydown', function(event) {
                        if (event.key === 'Enter' || event.key === ' ') {
                            event.preventDefault();
                            seleccionarLineaOrden(l.valor_unitario, fila, tbody, 'modalFormaServicios');
                        }
                    });
                    tbody.appendChild(fila);
                });
            } else {
                tbody.innerHTML = '<tr><td colspan="2" class="text-center text-muted py-3">Esta orden no tiene líneas de servicios.</td></tr>';
            }
        });
    }

    // ==========================================
    // GESTIÓN DE VISIBILIDAD Y CARGA INICIAL
    // ==========================================
    function toggleFields() {
        var val = selectPrincipal ? selectPrincipal.value : '';
        // Ocultar todo primero
        ['contrato_field', 'servicios_field', 'bienes_field', 'otrosi_field'].forEach(id => {
            document.getElementById(id).style.display = 'none';
        });
        if(contenedorTablaPagos) contenedorTablaPagos.style.display = 'none';

        // Mostrar el campo y cargar su tabla
        if (val === 'contrato') {
            document.getElementById('contrato_field').style.display = 'block';
            if(inputCuenta && !pagoCargadoDesdeTabla) bloquearValorCuenta('Primero selecciona el desembolso');
            if(selectContrato.value) cargarTablaPagos(selectContrato.value, 'contrato');
        } else if (val === 'servicios') {
            habilitarValorCuenta();
            document.getElementById('servicios_field').style.display = 'block';
            if(selectServicios.value) cargarLineasServicios(selectServicios.value);
        } else if (val === 'bienes') {
            habilitarValorCuenta();
            document.getElementById('bienes_field').style.display = 'block';
            if(selectBienes.value) cargarLineasBienes(selectBienes.value);
        } else if (val === 'otrosi') {
            document.getElementById('otrosi_field').style.display = 'block';
            if(inputCuenta && !pagoCargadoDesdeTabla) bloquearValorCuenta('Primero selecciona el desembolso');
            if(selectOtrosi.value) cargarTablaPagos(selectOtrosi.value, 'otrosi');
        }
    }

    // Ejecutar al inicio
    toggleFields();

    // Eventos de cambio
    if(selectPrincipal) selectPrincipal.addEventListener('change', toggleFields);
    if(selectContrato) selectContrato.addEventListener('change', function() {
        bloquearValorCuenta('Primero selecciona el desembolso');
        cargarTablaPagos(this.value, 'contrato');
    });
    if(selectOtrosi) selectOtrosi.addEventListener('change', function() {
        bloquearValorCuenta('Primero selecciona el desembolso');
        cargarTablaPagos(this.value, 'otrosi');
    });
    if(selectBienes) selectBienes.addEventListener('change', function() { cargarLineasBienes(this.value); });
    if(selectServicios) selectServicios.addEventListener('change', function() { cargarLineasServicios(this.value); });

    // Formateo de moneda para inputs
    if (inputCuenta) {
        inputCuenta.addEventListener('input', actualizarPorcentajePago);
        inputCuenta.addEventListener('blur', function() {
            if (!validarDesembolso()) {
                var cuota = cuotaSeleccionada();
                window.alert(cuota
                    ? 'El valor a cobrar no puede superar el saldo disponible del desembolso seleccionado ($' + aplicarFormato(cuota.valor_disponible || cuota.cantidad_de_dinero) + ').'
                    : 'Selecciona el desembolso que vas a cobrar en Forma de pago.');
                inputCuenta.focus();
                return;
            }
            this.value = aplicarFormato(limpiar(this.value));
            actualizarPorcentajePago();
        });
        inputCuenta.addEventListener('focus', function() {
            let v = limpiar(this.value);
            if (v > 0) this.value = v.toString().replace('.', ',');
        });
    }
    if (inputNumeroPago) {
        function sincronizarPagoEditado() {
            if (esCuentaRegalias) {
                habilitarValorCuenta();
                actualizarPorcentajePago();
                return;
            }
            var cuota = cuotaSeleccionada();
            var disponible = cuota ? Number(cuota.valor_disponible || cuota.cantidad_de_dinero || 0) : 0;
            pagoCargadoDesdeTabla = Boolean(cuota && !cuota.bloqueado && disponible > 0);

            if (pagoCargadoDesdeTabla) {
                habilitarValorCuenta();
            } else if (!esOtroSiPagoManual()) {
                bloquearValorCuenta('Selecciona un Pago N° válido');
            }

            var tbodyPagoEditado = document.getElementById('tbody_pagos');
            if (tbodyPagoEditado) {
                Array.prototype.forEach.call(tbodyPagoEditado.querySelectorAll('tr'), function (fila, indice) {
                    var item = pagosContractuales[indice];
                    var seleccionada = Boolean(
                        item && parseInt(item.numero_de_pagos, 10) === parseInt(inputDesembolsoOrigen && inputDesembolsoOrigen.value, 10)
                    );
                    fila.classList.toggle('table-primary', seleccionada);
                    fila.setAttribute('aria-selected', seleccionada ? 'true' : 'false');
                });
            }
            actualizarPorcentajePago();
        }

        inputNumeroPago.addEventListener('input', sincronizarPagoEditado);
        inputNumeroPago.addEventListener('change', sincronizarPagoEditado);
    }
    if (selectContrato) selectContrato.addEventListener('change', actualizarPorcentajePago);
    if (selectOtrosi) selectOtrosi.addEventListener('change', actualizarPorcentajePago);
    if (selectBienes) selectBienes.addEventListener('change', actualizarPorcentajePago);
    if (selectServicios) selectServicios.addEventListener('change', actualizarPorcentajePago);
    if (form) {
        form.addEventListener('submit', function(event) {
            if (!validarDesembolso()) {
                event.preventDefault();
                window.alert('Selecciona un desembolso y verifica que el valor a cobrar no lo supere.');
            }
        });
    }
    actualizarPorcentajePago();
});
