document.addEventListener('DOMContentLoaded', function () {
    var switchFacturaCorreccion = document.getElementById('factura_si_o_no_view');
    var numeroFacturaCorreccion = document.getElementById('numero_factura_view');
    if (!switchFacturaCorreccion || !numeroFacturaCorreccion) return;

    var valorFacturaOriginal = numeroFacturaCorreccion.value || '';

    function actualizarFacturaCorreccion() {
        if (switchFacturaCorreccion.checked) {
            numeroFacturaCorreccion.removeAttribute('readonly');
            numeroFacturaCorreccion.setAttribute('required', 'required');
            if (!numeroFacturaCorreccion.value && valorFacturaOriginal) {
                numeroFacturaCorreccion.value = valorFacturaOriginal;
            }
            numeroFacturaCorreccion.style.backgroundColor = '#ffffff';
            numeroFacturaCorreccion.style.cursor = 'text';
        } else {
            numeroFacturaCorreccion.value = '';
            numeroFacturaCorreccion.setAttribute('readonly', 'readonly');
            numeroFacturaCorreccion.removeAttribute('required');
            numeroFacturaCorreccion.style.backgroundColor = '#f1f3f5';
            numeroFacturaCorreccion.style.cursor = 'not-allowed';
        }
    }

    switchFacturaCorreccion.addEventListener('change', actualizarFacturaCorreccion);
    actualizarFacturaCorreccion();
});
