document.addEventListener('DOMContentLoaded', function () {
    var form = document.querySelector('form[action*="/public/cuentas_de_cobros/save/"]');
    if (!form || form.dataset.sgoActivityDateValidator === '1') return;
    form.dataset.sgoActivityDateValidator = '1';
    var inicio = form.querySelector('[name="inicio_actividad"]');
    var fin = form.querySelector('[name="finalizacion_actividad"]');

    function clearError(input) {
        if (!input) return;
        input.classList.remove('is-invalid');
        input.setCustomValidity('');
        var feedback = input.parentElement.querySelector('.sgo-activity-date-error');
        if (feedback) feedback.textContent = '';
    }
    function showError(input, message, move) {
        input.classList.add('is-invalid');
        input.setCustomValidity(message);
        var feedback = input.parentElement.querySelector('.sgo-activity-date-error');
        if (feedback) {
            feedback.textContent = message;
            feedback.style.display = 'block';
        }
        if (move) {
            input.scrollIntoView({behavior: 'smooth', block: 'center'});
            setTimeout(function () {
                try {
                    input.focus({preventScroll: true});
                    if (!input.readOnly &amp;&amp; input.showPicker) input.showPicker();
                } catch (e) {
                    input.focus();
                }
            }, 350);
        }
    }
    function invalidYear(input) {
        if (!input || !input.value) return false;
        var match = input.value.match(/^(\d{4,})-(\d{2})-(\d{2})$/);
        return !match || Number(match[1]) < 1000 || Number(match[1]) > 9999;
    }
    function validateDates(move) {
        clearError(inicio);
        clearError(fin);
        if (invalidYear(inicio)) {
            inicio.value = '';
            showError(inicio, 'La fecha de inicio tenía un año inválido. Selecciónala nuevamente con el calendario.', move);
            return false;
        }
        if (invalidYear(fin)) {
            fin.value = '';
            showError(fin, 'La fecha de finalización tenía un año inválido. Selecciónala nuevamente con el calendario.', move);
            return false;
        }
        if (inicio && fin && inicio.value && fin.value && fin.value < inicio.value) {
            fin.value = '';
            showError(fin, 'La fecha de finalización no puede ser anterior a la fecha de inicio. Selecciónala nuevamente.', move);
            return false;
        }
        return true;
    }
    [inicio, fin].forEach(function (input) {
        if (!input) return;
        input.addEventListener('input', function () { clearError(input); });
        input.addEventListener('change', function () { validateDates(true); });
    });
    form.addEventListener('submit', function (event) {
        if (!validateDates(true)) {
            event.preventDefault();
            event.stopImmediatePropagation();
        }
    }, true);
    setTimeout(function () {
        var forcedField = new URLSearchParams(window.location.search).get('fecha_error');
        var forcedInput = forcedField === 'inicio_actividad' ? inicio :
            (forcedField === 'finalizacion_actividad' ? fin : null);
        if (forcedInput) {
            var forcedMessage = forcedField === 'inicio_actividad'
                ? 'La fecha de inicio tenía un año inválido. Selecciónala nuevamente con el calendario.'
                : 'La fecha de finalización tenía un año inválido. Selecciónala nuevamente con el calendario.';
            forcedInput.value = '';
            showError(forcedInput, forcedMessage, true);
        } else {
            validateDates(true);
        }
    }, 300);
});

document.addEventListener('DOMContentLoaded', function () {
    const switchBloqueo = document.getElementById('switch_bloqueo');
    const switchPeriodoActividad = document.getElementById('switch_periodo_actividad');
    const camposAfectados = document.querySelectorAll('.can-disable');

    function actualizarEstado(checked) {
        camposAfectados.forEach(el => {
            const esInformacionContractual = el.classList.contains('info-contractual');
            const esPeriodoActividad = el.classList.contains('periodo-actividad');
            const esSiempreSoloLectura = el.classList.contains('siempre-solo-lectura');
            const puedeEditarPeriodo = Boolean(
                switchPeriodoActividad && switchPeriodoActividad.checked
            );
            const puedeEditar = !esSiempreSoloLectura && (
                checked || (esPeriodoActividad && puedeEditarPeriodo)
            );

            if (puedeEditar) {
                // --- MODO EDICIÓN (HABILITAR) ---
                el.removeAttribute('readonly');
                el.removeAttribute('disabled');
                el.style.pointerEvents = 'auto';
                el.style.backgroundColor = '#f8faff'; // Color original de tu CSS
                el.style.opacity = '1';
                el.removeAttribute('tabindex');
            } else {
                // --- MODO LECTURA (BLOQUEAR) ---
                if (el.tagName === 'SELECT') {
                    if (esSiempreSoloLectura) {
                        el.setAttribute('disabled', 'disabled');
                    }
                    el.style.pointerEvents = 'none';
                    el.style.backgroundColor = '#e9ecef'; // Gris de bloqueado
                    el.style.opacity = '0.8';
                    el.setAttribute('tabindex', '-1'); // Evita que entren con la tecla TAB
                } else {
                    el.setAttribute('readonly', 'readonly');
                    el.style.backgroundColor = '#e9ecef';
                }
            }
        });
    }

    if (switchBloqueo) {
        // Ejecutar al cargar para que respete el estado inicial de la DB
        actualizarEstado(switchBloqueo.checked);

        switchBloqueo.addEventListener('change', function () {
            actualizarEstado(this.checked);
        });
    }
});

