document.addEventListener('DOMContentLoaded', function () {
    // --- Referencias para Documento Adicional ---
    var valBooleanOtro = document.getElementById('opcion_otro_documento_val');
    var switchOtroCorreccion = document.getElementById('opcion_otro_documento_correccion');
    var rowOtroDoc = document.getElementById('row_documento_adicional_view');

    function actualizarDocumentosAdicionales() {
        if (!rowOtroDoc) return;

        var modoCorreccion = rowOtroDoc.getAttribute('data-correction-mode') === '1';
        var marcadoParaCorregir = rowOtroDoc.getAttribute('data-correction-selected') === '1';

        // En una corrección, Documento adicional solo se muestra si
        // el asistente/coordinador lo marcó explícitamente para corregir.
        // Tener documentos cargados previamente no debe hacerlo visible.
        if (modoCorreccion) {
            rowOtroDoc.style.display = marcadoParaCorregir ? 'flex' : 'none';
            return;
        }

        var visibleOriginal = valBooleanOtro && (
            valBooleanOtro.value === 'True' || valBooleanOtro.value === '1'
        );
        rowOtroDoc.style.display = visibleOriginal ? 'flex' : 'none';
    }

    if (switchOtroCorreccion) {
        switchOtroCorreccion.addEventListener('change', actualizarDocumentosAdicionales);
    }
    actualizarDocumentosAdicionales();

    var inputAdicionalCorreccion = document.getElementById('otro_documentos_de_inf_doc_correccion');
    var dropzoneAdicionalCorreccion = document.getElementById('sgo_correction_additional_dropzone');
    var textoAdicionalCorreccion = document.getElementById('sgo_correction_additional_primary');
    var metaAdicionalCorreccion = document.getElementById('sgo_correction_additional_meta');

    function refrescarDropzoneAdicionalCorreccion() {
        if (!inputAdicionalCorreccion || !textoAdicionalCorreccion || !metaAdicionalCorreccion) return;
        var archivos = inputAdicionalCorreccion.files ? Array.prototype.slice.call(inputAdicionalCorreccion.files) : [];
        if (archivos.length) {
            textoAdicionalCorreccion.textContent = archivos.length === 1
                ? archivos[0].name
                : archivos[0].name + ' y ' + (archivos.length - 1) + ' más';
            metaAdicionalCorreccion.textContent = archivos.length === 1
                ? 'Archivo seleccionado'
                : archivos.length + ' archivos seleccionados';
            if (dropzoneAdicionalCorreccion) {
                dropzoneAdicionalCorreccion.style.background = '#f0fdf4';
                dropzoneAdicionalCorreccion.style.borderColor = '#86d3a8';
            }
        } else {
            textoAdicionalCorreccion.textContent = 'Arrastra tu archivo aquí o selecciona el archivo';
            metaAdicionalCorreccion.textContent = '';
            if (dropzoneAdicionalCorreccion) {
                dropzoneAdicionalCorreccion.style.background = '#f8fbff';
                dropzoneAdicionalCorreccion.style.borderColor = '#7fb4f4';
            }
        }
    }

    if (inputAdicionalCorreccion) {
        inputAdicionalCorreccion.addEventListener('change', refrescarDropzoneAdicionalCorreccion);
    }
    if (dropzoneAdicionalCorreccion && inputAdicionalCorreccion) {
        ['dragenter', 'dragover'].forEach(function (evento) {
            dropzoneAdicionalCorreccion.addEventListener(evento, function (e) {
                e.preventDefault();
                dropzoneAdicionalCorreccion.style.background = '#eef6ff';
                dropzoneAdicionalCorreccion.style.borderColor = '#043484';
            });
        });
        ['dragleave', 'dragend'].forEach(function (evento) {
            dropzoneAdicionalCorreccion.addEventListener(evento, function () {
                refrescarDropzoneAdicionalCorreccion();
            });
        });
        dropzoneAdicionalCorreccion.addEventListener('drop', function (e) {
            e.preventDefault();
            var archivos = e.dataTransfer && e.dataTransfer.files ? e.dataTransfer.files : null;
            if (!archivos || !archivos.length || typeof DataTransfer === 'undefined') return;
            var transferencia = new DataTransfer();
            Array.prototype.slice.call(archivos).forEach(function (archivo) {
                transferencia.items.add(archivo);
            });
            inputAdicionalCorreccion.files = transferencia.files;
            inputAdicionalCorreccion.dispatchEvent(new Event('change', {bubbles:true}));
        });
    }
    refrescarDropzoneAdicionalCorreccion();

    // --- Aquí puedes mantener tu lógica de la Factura que ya tenías ---
    var switchFacturaView = document.getElementById('factura_si_o_no_view');
    var rowFacturaView = document.getElementById('row_factura_doc_view');
    var linkDeclaracion = document.querySelector('[data-sgo-declaracion-link="1"]');
    var labelDeclaracion = document.querySelector('[data-sgo-declaracion-label="1"]');

    function actualizarBotonDeclaracion() {
        if (!switchFacturaView || !linkDeclaracion || !labelDeclaracion) return;
        if (linkDeclaracion.getAttribute('href') === '#') return;
        var hrefBase = linkDeclaracion.getAttribute('data-base-href');
        if (hrefBase) {
            linkDeclaracion.setAttribute('href', switchFacturaView.checked ? hrefBase + '?factura=1' : hrefBase + '?factura=0');
        }
        labelDeclaracion.textContent = switchFacturaView.checked
            ? 'Crear declaración juramentada'
            : 'Crear doc. equivalente y declaración';
    }

    if (switchFacturaView && rowFacturaView) {
        switchFacturaView.addEventListener('change', function () {
            rowFacturaView.style.display = this.checked ? 'flex' : 'none';
            actualizarBotonDeclaracion();
        });
        if (switchFacturaView.checked) rowFacturaView.style.display = 'flex';
    }
    actualizarBotonDeclaracion();
});
