document.addEventListener('DOMContentLoaded', function () {
    var fileTypeClasses = [
        'sgo-file-pdf', 'sgo-file-word', 'sgo-file-excel',
        'sgo-file-powerpoint', 'sgo-file-image',
        'sgo-file-archive', 'sgo-file-text'
    ];

    function fileType(filename) {
        var cleanName = String(filename || '').split('?')[0].toLowerCase();
        var extension = cleanName.indexOf('.') >= 0 ? cleanName.split('.').pop() : '';
        if (extension === 'pdf') return {css: 'sgo-file-pdf', label: 'PDF'};
        if (['doc', 'docx', 'odt'].indexOf(extension) >= 0) return {css: 'sgo-file-word', label: 'Word'};
        if (['xls', 'xlsx', 'csv', 'ods'].indexOf(extension) >= 0) return {css: 'sgo-file-excel', label: 'Excel'};
        if (['ppt', 'pptx', 'odp'].indexOf(extension) >= 0) return {css: 'sgo-file-powerpoint', label: 'PowerPoint'};
        if (['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'svg', 'tif', 'tiff'].indexOf(extension) >= 0) return {css: 'sgo-file-image', label: 'Imagen'};
        if (['zip', 'rar', '7z', 'tar', 'gz'].indexOf(extension) >= 0) return {css: 'sgo-file-archive', label: 'Archivo comprimido'};
        if (['txt', 'rtf', 'xml', 'json'].indexOf(extension) >= 0) return {css: 'sgo-file-text', label: 'Texto'};
        return {css: '', label: 'Documento'};
    }

    function selectedOrCurrentFilename(card) {
        var selectedInput = card.querySelector('input[type="file"]');
        if (selectedInput && selectedInput.files && selectedInput.files.length) {
            return selectedInput.files[0].name;
        }
        var currentInput = card.querySelector('.input-group-modern input[type="text"]');
        return currentInput ? String(currentInput.value || '').trim() : '';
    }

    function documentState(card) {
        var selectedInput = card.querySelector('input[type="file"]');
        if (selectedInput && selectedInput.files && selectedInput.files.length) return 'loaded';
        if (card.querySelector('.input-group-modern a.btn-ver-fix')) return 'loaded';

        var filename = selectedOrCurrentFilename(card);
        var normalized = filename.toLowerCase();
        var missingText = !normalized
            || normalized === 'n/a'
            || normalized.indexOf('sin ') === 0
            || normalized.indexOf('ningún archivo') === 0;
        return missingText ? 'missing' : 'loaded';
    }

    function updateDocumentIcon(card) {
        var group = card.querySelector('.input-group-modern');
        if (!group) return;
        var filename = selectedOrCurrentFilename(card);
        var type = fileType(filename);
        fileTypeClasses.forEach(function (className) {
            group.classList.remove(className);
        });
        if (type.css) group.classList.add(type.css);
        group.setAttribute('title', 'Tipo de archivo: ' + type.label);
    }

    function initializeDocumentBlock(block) {
        var cards = Array.prototype.slice.call(block.querySelectorAll('.doc-cell-container')).filter(function (card) {
            return card.style.display !== 'none';
        });
        var buttons = Array.prototype.slice.call(block.querySelectorAll('.sgo-doc-filter'));

        function setDocumentState(card) {
            var state = documentState(card);
            card.dataset.docState = state;
            card.classList.toggle('sgo-doc-missing', state === 'missing');
        }

        function updateCounts() {
            ['all', 'loaded', 'missing'].forEach(function (filter) {
                var count = filter === 'all'
                    ? cards.length
                    : cards.filter(function (card) { return card.dataset.docState === filter; }).length;
                var badge = block.querySelector('[data-filter-count="' + filter + '"]');
                if (badge) badge.textContent = count;
            });
        }

        function applyFilter(filter) {
            cards.forEach(function (card) {
                var visible = filter === 'all' || card.dataset.docState === filter;
                card.classList.toggle('sgo-filter-hidden', !visible);
            });
        }

        cards.forEach(function (card) {
            setDocumentState(card);
            updateDocumentIcon(card);
            Array.prototype.forEach.call(card.querySelectorAll('input[type="file"]'), function (input) {
                input.addEventListener('change', function () {
                    setDocumentState(card);
                    updateDocumentIcon(card);
                    updateCounts();
                    var activeButton = block.querySelector('.sgo-doc-filter.is-active');
                    applyFilter(activeButton ? activeButton.dataset.docFilter : 'all');
                });
            });
        });

        updateCounts();

        buttons.forEach(function (button) {
            button.addEventListener('click', function () {
                var filter = button.dataset.docFilter || 'all';
                buttons.forEach(function (item) {
                    var active = item === button;
                    item.classList.toggle('is-active', active);
                    item.setAttribute('aria-pressed', active ? 'true' : 'false');
                });
                applyFilter(filter);
            });
        });
    }

    Array.prototype.forEach.call(
        document.querySelectorAll('.sgo-loaded-documents'),
        initializeDocumentBlock
    );
});
