    document.addEventListener('DOMContentLoaded', function () {
        document.querySelectorAll('input[type="file"][name$="_replace_file"]').forEach(function (input) {
            if (input.parentElement && input.parentElement.classList.contains('correction-upload-box')) {
                return;
            }

            var wrapper = document.createElement('div');
            wrapper.className = 'correction-upload-box';
            input.parentNode.insertBefore(wrapper, input);
            wrapper.appendChild(input);

            var helper = document.createElement('div');
            helper.className = 'replace-upload-hint';
            wrapper.insertBefore(helper, input);

            function isRealCorrectionInput() {
                var cell = input.closest('.doc-cell-container');
                var danger = cell ? cell.querySelector('label .text-danger') : null;
                return !!(danger && (danger.offsetWidth || danger.offsetHeight || danger.getClientRects().length));
            }

            function isOptionalReviewInput() {
                return !isRealCorrectionInput();
            }

            function paintCorrectionUpload() {
                var hasFile = input.files && input.files.length > 0;
                var realCorrection = isRealCorrectionInput();
                var optionalReview = isOptionalReviewInput();
                wrapper.classList.toggle('has-file', hasFile);
                wrapper.classList.toggle('optional-review-file', optionalReview && !hasFile);
                wrapper.classList.toggle('requested-correction', realCorrection && !hasFile);
                input.classList.toggle('has-file', hasFile);
                input.classList.toggle('optional-review-file', optionalReview && !hasFile);
                helper.classList.toggle('requested-correction', realCorrection);
                helper.classList.toggle('has-file', hasFile);
                helper.style.display = (!hasFile && optionalReview) ? 'none' : 'block';
                if (hasFile) {
                    helper.textContent = realCorrection
                        ? 'Archivo corregido seleccionado; se guardará al finalizar.'
                        : 'Archivo de reemplazo seleccionado; se guardará al finalizar.';
                } else {
                    helper.textContent = realCorrection
                        ? 'Corrección solicitada: selecciona el archivo corregido.'
                        : '';
                }

                if (hasFile) {
                    input.style.setProperty('background-color', '#ecfdf5', 'important');
                    input.style.setProperty('border', '2px dashed #8fd6c7', 'important');
                    input.style.setProperty('box-shadow', '0 0 0 3px rgba(92, 198, 173, 0.12)', 'important');
                    input.style.setProperty('color', '#166534', 'important');
                } else if (optionalReview) {
                    input.style.setProperty('background-color', '#f8fafc', 'important');
                    input.style.setProperty('border', '2px dashed #cbd5e1', 'important');
                    input.style.setProperty('box-shadow', 'none', 'important');
                    input.style.setProperty('color', '#475569', 'important');
                } else {
                    input.style.setProperty('background-color', '#fffafa', 'important');
                    input.style.setProperty('border', '2px dashed #efb1b8', 'important');
                    input.style.setProperty('box-shadow', '0 0 0 3px rgba(239, 111, 122, 0.10)', 'important');
                    input.style.setProperty('color', '#5f2930', 'important');
                }
            }

            paintCorrectionUpload();
            input.addEventListener('change', paintCorrectionUpload);
        });
    });
