t.script:

document.addEventListener('DOMContentLoaded', function () {
    // --- Referencias de Elementos ---
    const selector = document.getElementById('clase_persona_selector');
    const naturalBlock = document.getElementById('bloque_persona_natural');
    const juridicaBlock = document.getElementById('bloque_persona_juridica');
    const contratoSelector = document.getElementById('seleccionar');
    const form = document.querySelector('form');

    // === Función para validar documentos antes de guardar ===
    function validarDocumentosObligatorios() {
        // Usamos una lógica simple: si el botón está disabled por QWeb, detenemos el JS
        const btnGuardar = document.getElementById('btn_guardar_cuenta');

        // ¡Eliminamos las variables que usaban 'record' aquí!

        if (btnGuardar && btnGuardar.hasAttribute('disabled')) {
            Swal.fire({
                icon: 'warning',
                title: 'Documentos Faltantes',
                text: 'Por favor complete el Formulario de Declaración y el Formulario de Informe antes de guardar.',
                confirmButtonColor: '#8d4b41'
            });
            return false;
        }
        return true;
    }

    // === Gestión de Visibilidad de Bloques (Tu código original) ===
    function toggleBlocks() {
        if (!selector) return;
        const value = selector.value;
        if(naturalBlock) naturalBlock.style.display = value === 'persona_natural' ? 'block' : 'none';
        if(juridicaBlock) juridicaBlock.style.display = value === 'persona_juridica' ? 'block' : 'none';
    }

    function toggleContratoFields() {
        if (!contratoSelector) return;
        const value = contratoSelector.value;
        const fields = ['contrato_field', 'servicios_field', 'bienes_field', 'otrosi_field'];
        fields.forEach(f => {
            const el = document.getElementById(f);
            if (el) el.style.display = 'none';
        });
        const target = document.getElementById(value + '_field');
        if (target) target.style.display = 'block';
    }

    // === Listeners ===
    if (selector) selector.addEventListener('change', toggleBlocks);
    if (contratoSelector) contratoSelector.addEventListener('change', toggleContratoFields);

    // === Validación Final al Enviar ===
    if (form) {
        form.addEventListener('submit', function (event) {
            if (!validarDocumentosObligatorios()) {
                event.preventDefault();
            }
        });
    }

    // Inicializar vistas
    toggleBlocks();
    toggleContratoFields();
});

