(function() {
    var _cfg = document.getElementById('chatCfg');
    var LOGIN_ID  = _cfg ? parseInt(_cfg.getAttribute('data-lid')) || 0 : 0;
    var TOKEN     = _cfg ? (_cfg.getAttribute('data-tok') || '') : '';
    var CUENTA_ID = _cfg ? parseInt(_cfg.getAttribute('data-cid')) || 0 : 0;
    var isOpen = false;
    var seenKey = 'portal_chat_seen_interno_' + LOGIN_ID + '_' + CUENTA_ID;
    var lastInternoCount = parseInt(localStorage.getItem(seenKey) || '0') || 0;
    var pollTimer = null;

    function esc(str) {
        var d = document.createElement('div');
        d.appendChild(document.createTextNode(str || ''));
        return d.innerHTML;
    }

    function rpc(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc:'2.0', method:'call', params: params || {}})
        }).then(function(r){ return r.json(); }).then(function(d){ return d.result; });
    }

    function renderMsgs(messages) {
        var box = document.getElementById('chatMsgs');
        if (!messages || !messages.length) {
            box.innerHTML = '<div class="chat-empty">¡Hola! ¿En qué podemos ayudarte?</div>';
            return;
        }
        var html = '';
        messages.forEach(function(m) {
            var cls = m.sender_type === 'interno' ? 'b-interno' : 'b-contratista';
            html += '<div class="chat-bubble ' + cls + '">';
            if (m.sender_type === 'interno') {
                html += '<div class="chat-sender">' + esc(m.sender_name) + '</div>';
            }
            html += '<div>' + esc(m.body) + '</div>';
            html += '<div class="chat-meta">' + m.date + '</div>';
            html += '</div>';
        });
        box.innerHTML = html;
        box.scrollTop = box.scrollHeight;
    }

    function fetchMsgs() {
        if (!LOGIN_ID || !TOKEN) return;
        rpc('/public/chat/messages/' + LOGIN_ID + '/' + TOKEN, {cuenta_id: CUENTA_ID}).then(function(res) {
            if (!res || !res.messages) return;
            var internoCount = res.messages.filter(function(m){ return m.sender_type === 'interno'; }).length;
            if (isOpen) {
                renderMsgs(res.messages);
                lastInternoCount = internoCount;
                localStorage.setItem(seenKey, String(lastInternoCount));
                document.getElementById('chatBadge').style.display = 'none';
            } else if (internoCount > lastInternoCount) {
                var badge = document.getElementById('chatBadge');
                badge.style.display = 'flex';
                badge.textContent = String(internoCount - lastInternoCount);
            } else {
                document.getElementById('chatBadge').style.display = 'none';
            }
        }).catch(function() {});
    }

    function startPoll() {
        if (pollTimer) clearInterval(pollTimer);
        pollTimer = setInterval(fetchMsgs, 5000);
    }

    function initChat() {
        var openBtn  = document.getElementById('chatOpenBtn');
        var closeBtn = document.getElementById('chatCloseBtn');
        var win      = document.getElementById('portalChatWindow');
        var input    = document.getElementById('chatInput');
        var sendBtn  = document.getElementById('chatSendBtn');

        if (!openBtn) return;

        openBtn.addEventListener('click', function() {
            isOpen = true;
            win.style.display = 'flex';
            document.getElementById('chatBadge').style.display = 'none';
            rpc('/public/notifications/read/' + LOGIN_ID + '/' + TOKEN, {}).catch(function() {});
            fetchMsgs();
            input.focus();
        });

        closeBtn.addEventListener('click', function() {
            isOpen = false;
            win.style.display = 'none';
        });

        function doSend() {
            var body = input.value.trim();
            if (!body) return;
            input.value = '';
            rpc('/public/chat/send/' + LOGIN_ID + '/' + TOKEN, {body: body, cuenta_id: CUENTA_ID}).then(function(res) {
                if (res && res.ok) fetchMsgs();
            }).catch(function() {});
        }

        sendBtn.addEventListener('click', doSend);
        input.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); doSend(); }
        });

        startPoll();
        fetchMsgs();
        if (window.location.hash === '#soporte') {
            openBtn.click();
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initChat);
    } else {
        initChat();
    }
})();
