div.script:
document.addEventListener('DOMContentLoaded', function() {
    // Buscamos el input por su ID
    var inputFecha = document.getElementById('fecha_solicitud');

    if (inputFecha) {
        // Obtenemos la fecha de hoy
        var hoy = new Date();

        // Extraemos el año, mes y día
        var anio = hoy.getFullYear();
        // getMonth() devuelve de 0 a 11, por eso sumamos 1. padStart asegura que tenga 2 dígitos (ej. '03')
        var mes = String(hoy.getMonth() + 1).padStart(2, '0');
        var dia = String(hoy.getDate()).padStart(2, '0');

        // Armamos la cadena en formato YYYY-MM-DD y se la asignamos al input
        inputFecha.value = anio + '-' + mes + '-' + dia;
    }
});

