document.addEventListener('DOMContentLoaded', function () {

    // --- REFERENCIAS ---
    var inputValorCuenta = document.getElementById('valor_cuenta');
    var inputTotalContrato = document.getElementById('valor_total_contrato');
    var labelTotalRelacion = document.getElementById('label_valor_total_relacion');
    var selectPrincipal = document.getElementById('selecionar');
    var form = inputValorCuenta ? inputValorCuenta.closest('form') : null;
    var inputPorcentajePago = document.getElementById('porcentaje_de_pago_create');
    var inputPorcentajeAcumulado = document.getElementById('porcentaje_acumulado_create');
    var inputNumeroPago = document.getElementById('pago_create');
    var inputDesembolsoOrigen = document.getElementById('pago_forma_pago_create');
    var pagosContractuales = [];
    var esperandoPagosContractuales = false;
    var pagoCargadoDesdeTabla = false;
    var alertaMontoActiva = false;
    var inputOrigenCuenta = document.getElementById('origen_cuenta');

    function esCuentaRegalias() {
        return Boolean(
            inputOrigenCuenta
            && inputOrigenCuenta.value === 'regalias'
        );
    }

    function tipoActualSeleccionado() {
        return selectPrincipal ? selectPrincipal.value : '';
    }

    function bloquearValorCuenta(mensaje) {
        if (!inputValorCuenta) return;
        inputValorCuenta.setAttribute('readonly', 'readonly');
        inputValorCuenta.value = '';
        inputValorCuenta.placeholder = mensaje || 'Primero selecciona el desembolso';
        pagoCargadoDesdeTabla = false;
        if (inputNumeroPago) {
            delete inputNumeroPago.dataset.desembolsoSeleccionado;
        }
    }

    function habilitarValorCuenta() {
        if (!inputValorCuenta) return;
        inputValorCuenta.removeAttribute('readonly');
        inputValorCuenta.placeholder = '0,00';
    }

    function esOtroSiPagoManual() {
        if (tipoActualSeleccionado() !== 'otrosi' || !inputValorCuenta) return false;
        if (inputDesembolsoOrigen && inputDesembolsoOrigen.value) return false;
        if (inputValorCuenta.dataset.formaPagoManual === '1') return true;
        if (esperandoPagosContractuales || !inputNumeroPago) return false;
        var numeroPago = parseInt(inputNumeroPago.value, 10);
        if (!numeroPago || numeroPago < 1) return false;
        return !pagosContractuales.some(function(item) {
            return parseInt(item.numero_de_pagos, 10) === numeroPago;
        });
    }

    function actualizarBloqueoValorCuenta() {
        if (esCuentaRegalias()) {
            habilitarValorCuenta();
        } else if (esOtroSiPagoManual()) {
            habilitarValorCuenta();
            inputValorCuenta.placeholder = 'Escribe el valor manualmente';
        } else if (['contrato', 'otrosi'].indexOf(tipoActualSeleccionado()) !== -1 && !pagoCargadoDesdeTabla) {
            bloquearValorCuenta('Primero selecciona el desembolso');
        } else if (['contrato', 'otrosi'].indexOf(tipoActualSeleccionado()) === -1) {
            habilitarValorCuenta();
        }
    }

    // --- UTILIDADES ---
    function aplicarFormatoOdoo(numero) {
        if (!numero && numero !== 0) return "0,00";
        return new Intl.NumberFormat('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(numero);
    }

    function limpiarNumero(texto) {
        if (!texto) return 0;
        var limpio = texto.toString().split('.').join('').replace(',', '.');
        return parseFloat(limpio) || 0;
    }

    function actualizarPorcentajePago() {
        if (!inputValorCuenta || !inputTotalContrato || !inputPorcentajePago) return;

        var numeroPago = inputNumeroPago ? parseInt(inputNumeroPago.value, 10) : 0;
        var cuota = pagosContractuales.find(item => parseInt(item.numero_de_pagos, 10) === numeroPago);
        var valorCuentaNum = limpiarNumero(inputValorCuenta.value);
        if (cuota) {
            var valorCuota = Number(cuota.cantidad_de_dinero || 0);
            if (Math.abs(valorCuentaNum - valorCuota) < 0.01) {
                inputPorcentajePago.value = Number(cuota.porcentaje_pago || 0).toFixed(2);
                if (inputPorcentajeAcumulado) inputPorcentajeAcumulado.value = Number(cuota.porcentaje_acumulado || 0).toFixed(2);
                return;
            }
        }
        var tipoActual = selectPrincipal ? selectPrincipal.value : '';
        if (esperandoPagosContractuales) {
            inputPorcentajePago.value = '';
            if (inputPorcentajeAcumulado) inputPorcentajeAcumulado.value = '';
            return;
        }

        var valorTotalNum = limpiarNumero(inputTotalContrato.value);

        if (valorCuentaNum > 0 && valorTotalNum > 0) {
            inputPorcentajePago.value = ((valorCuentaNum / valorTotalNum) * 100).toFixed(2);
            if (inputPorcentajeAcumulado) inputPorcentajeAcumulado.value = inputPorcentajePago.value;
        } else {
            inputPorcentajePago.value = '';
            if (inputPorcentajeAcumulado) inputPorcentajeAcumulado.value = '';
        }
    }

    /* IMPORTANTE:
    La dejo global porque más abajo otro script la llama */
    window.actualizarPorcentajePago = actualizarPorcentajePago;

    // --- VALIDACIÓN ---
    function cuotaSeleccionada() {
        var numeroPago = inputDesembolsoOrigen
            ? parseInt(inputDesembolsoOrigen.value, 10)
            : (inputNumeroPago ? parseInt(inputNumeroPago.value, 10) : 0);
        return pagosContractuales.find(item => parseInt(item.numero_de_pagos, 10) === numeroPago);
    }

    function llevarAValorCuentaParaCorregir() {
        if (!inputValorCuenta) return;
        inputValorCuenta.classList.add('is-invalid');
        setTimeout(function () {
            inputValorCuenta.scrollIntoView({behavior: 'smooth', block: 'center'});
            setTimeout(function () {
                inputValorCuenta.focus({preventScroll: true});
                inputValorCuenta.select();
            }, 400);
        }, 350);
    }

    function seleccionarDesembolso(item, fila) {
        if (!inputNumeroPago || !inputValorCuenta) return;
        if (item.bloqueado || Number(item.valor_disponible || 0) <= 0) {
            return;
        }
        pagoCargadoDesdeTabla = true;
        habilitarValorCuenta();
        inputNumeroPago.value = item.numero_de_pagos || '';
        if (inputDesembolsoOrigen) inputDesembolsoOrigen.value = item.numero_de_pagos || '';
        inputNumeroPago.dataset.desembolsoSeleccionado = String(item.numero_de_pagos || '');
        inputValorCuenta.value = aplicarFormatoOdoo(Number(item.valor_disponible || item.cantidad_de_dinero || 0));
        if (tbodyPagos) {
            tbodyPagos.querySelectorAll('tr').forEach(function(row) {
                row.classList.remove('table-primary');
                row.setAttribute('aria-selected', 'false');
            });
        }
        fila.classList.add('table-primary');
        fila.setAttribute('aria-selected', 'true');
        actualizarPorcentajePago();
        var modalFormaPago = document.getElementById('modalFormaPago');
        if (modalFormaPago) {
            var cerrarModal = modalFormaPago.querySelector('[data-bs-dismiss="modal"]');
            if (cerrarModal) cerrarModal.click();
        }
    }

    function validarMontos() {
        if (!inputValorCuenta || !inputTotalContrato) return true;
        if (alertaMontoActiva || (window.Swal && Swal.isVisible())) return false;
        var valorCuentaNum = limpiarNumero(inputValorCuenta.value);
        var valorTotalNum = limpiarNumero(inputTotalContrato.value);
        var desembolsoMarcado = false;
        if (inputNumeroPago) {
            if (inputNumeroPago.dataset.desembolsoSeleccionado) {
                desembolsoMarcado = cuotaSeleccionada();
            }
        }
        if (['contrato', 'otrosi'].indexOf(tipoActualSeleccionado()) !== -1) {
            if (!esOtroSiPagoManual() && (!(pagoCargadoDesdeTabla || desembolsoMarcado) || inputValorCuenta.readOnly)) {
                return false;
            }
        }

        if (valorTotalNum > 0 && valorCuentaNum > valorTotalNum) {
            var nombreTope = selectPrincipal && selectPrincipal.value === 'otrosi'
                ? 'otrosí'
                : 'contrato/orden';
            alertaMontoActiva = true;
            Swal.fire({
                icon: 'error',
                title: '¡Monto excedido!',
                text: 'El valor no puede superar el total del ' + nombreTope + '.',
                confirmButtonColor: '#043484'
            }).then(function(result) {
                alertaMontoActiva = false;
                if (result.isConfirmed) llevarAValorCuentaParaCorregir();
            });
            return false;
        }
        var cuota = cuotaSeleccionada();
        var valorCuota = cuota ? Number(cuota.valor_disponible || cuota.cantidad_de_dinero || 0) : 0;
        if (valorCuota > 0 && valorCuentaNum > valorCuota) {
            alertaMontoActiva = true;
            Swal.fire({
                icon: 'error',
                title: '¡Monto excedido!',
                text: 'El valor a cobrar no puede superar el saldo disponible del desembolso seleccionado ($' + aplicarFormatoOdoo(valorCuota) + ').',
                confirmButtonColor: '#043484'
            }).then(function(result) {
                alertaMontoActiva = false;
                if (result.isConfirmed) llevarAValorCuentaParaCorregir();
            });
            return false;
        }
        if (inputValorCuenta.value) inputValorCuenta.value = aplicarFormatoOdoo(valorCuentaNum);
        return true;
    }

    // --- BOTÓN VER TABLA ---
    var btnVerTabla = document.getElementById('btnVerTabla');
    function configurarBotonTabla(target, texto, icono) {
        if (!btnVerTabla) return;
        btnVerTabla.setAttribute('data-bs-target', target);
        btnVerTabla.innerHTML = '<i class="fa ' + icono + '" style="margin-right:6px;"></i>' + texto;
        btnVerTabla.style.display = 'inline-block';
    }

    function seleccionarValorOrden(valor, fila, tbody, modalId) {
        if (!inputValorCuenta) return;
        var valorSeleccionado = Number(valor || 0);
        if (valorSeleccionado <= 0) return;

        habilitarValorCuenta();
        inputValorCuenta.value = aplicarFormatoOdoo(valorSeleccionado);
        if (tbody) {
            tbody.querySelectorAll('tr').forEach(function(row) {
                row.classList.remove('table-primary');
                row.setAttribute('aria-selected', 'false');
            });
        }
        if (fila) {
            fila.classList.add('table-primary');
            fila.setAttribute('aria-selected', 'true');
        }
        actualizarPorcentajePago();
        inputValorCuenta.dispatchEvent(new Event('change', {bubbles: true}));

        var modalOrden = document.getElementById(modalId);
        if (modalOrden) {
            var cerrarModalOrden = modalOrden.querySelector('[data-bs-dismiss="modal"]');
            if (cerrarModalOrden) cerrarModalOrden.click();
        }
    }

    // --- CARGA DE BIENES (TU SOLICITUD) ---
    var tbodyBienes = document.getElementById('tbody_lineas_bienes');
    var tablaBienesContainer = document.getElementById('tabla_bienes_container');

    function cargarLineasBienes(ordenId) {
        if (!ordenId || ordenId === "") {
            if(tablaBienesContainer) tablaBienesContainer.style.display = 'none';
            return;
        }

        // Mostrar spinner mientras carga
        if(tbodyBienes) tbodyBienes.innerHTML = '<tr><td colspan="4" class="text-center py-2"><i class="fa fa-spinner fa-spin"></i> Cargando detalle...</td></tr>';
        if(tablaBienesContainer) tablaBienesContainer.style.display = 'block';

        // Llamada al controlador JSON de Odoo
        fetch('/public/obtener_lineas_bienes', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ params: { orden_id: ordenId } })
        })
        .then(response => response.json())
        .then(data => {
            var res = data.result; // Odoo envuelve la respuesta en 'result'
            if(!tbodyBienes) return;
            tbodyBienes.innerHTML = '';

            if (res.lineas && res.lineas.length > 0) {
                res.lineas.forEach(linea => {
                    var fila = document.createElement('tr');
                    var valorLinea = Number(linea.valor_total || 0);
                    fila.setAttribute('role', 'button');
                    fila.setAttribute('tabindex', '0');
                    fila.setAttribute('aria-selected', 'false');
                    fila.style.cursor = 'pointer';
                    fila.title = 'Seleccionar este valor para la cuenta';
                    fila.innerHTML = `
                        <td>${linea.descripcion}</td>
                        <td class="text-center">${linea.cantidad}</td>
                        <td class="text-end">$${aplicarFormatoOdoo(linea.valor_unitario)}</td>
                        <td class="text-end">$${aplicarFormatoOdoo(linea.valor_total)}</td>
                    `;
                    fila.addEventListener('click', function() {
                        seleccionarValorOrden(valorLinea, fila, tbodyBienes, 'modalFormaBienes');
                    });
                    fila.addEventListener('keydown', function(event) {
                        if (event.key === 'Enter' || event.key === ' ') {
                            event.preventDefault();
                            seleccionarValorOrden(valorLinea, fila, tbodyBienes, 'modalFormaBienes');
                        }
                    });
                    tbodyBienes.appendChild(fila);
                });
            } else {
                tbodyBienes.innerHTML = '<tr><td colspan="4" class="text-center">No hay líneas en esta orden.</td></tr>';
            }
        })
        .catch(error => {
            console.error("Error cargando bienes:", error);
            if(tbodyBienes) tbodyBienes.innerHTML = '<tr><td colspan="4" class="text-center text-danger">Error de conexión.</td></tr>';
        });
    }

    // --- CARGA DE PAGOS (HISTORIAL) ---
    var tbodyPagos = document.getElementById('tbody_pagos');
    var contenedorTablaPagos = document.getElementById('contenedor_tabla_pagos');

    function cargarTablaPagos(id, tipoRelacion) {
        if (!id) return;
        configurarBotonTabla('#modalFormaPago', 'Ver forma de pago', 'fa-table');
        esperandoPagosContractuales = true;
        pagosContractuales = [];
        pagoCargadoDesdeTabla = false;
        if (inputValorCuenta) delete inputValorCuenta.dataset.formaPagoManual;
        if(inputPorcentajePago) inputPorcentajePago.value = '';
        if(contenedorTablaPagos) contenedorTablaPagos.style.display = 'block';

        var url = '/public/cuentas_de_cobros/obtener_pagos' + (tipoRelacion === 'contrato' ? '?contrato_id=' : '?otrosi_id=') + id + '&_=' + Date.now();
        var documentoInput = document.querySelector('[name="documento_de_identificacion"]');
        var nombreInput = document.querySelector('[name="nombre_contratista"]');
        if (documentoInput && documentoInput.value) {
            url += '&identificacion=' + encodeURIComponent(documentoInput.value);
        }
        if (nombreInput && nombreInput.value) {
            url += '&nombre=' + encodeURIComponent(nombreInput.value);
        }

        fetch(url, {cache: 'no-store'}).then(r => r.json()).then(data => {
            if(!tbodyPagos) return;
            tbodyPagos.innerHTML = '';
            pagosContractuales = data.pagos || [];
            if (data.pagos && data.pagos.length > 0) {
                data.pagos.forEach(item => {
                    var fila = document.createElement('tr');
                    var disponible = Number(item.valor_disponible || 0);
                    var fisico = Number(item.valor_cobrado_fisico || 0);
                    var sgo = Number(item.valor_cobrado_sgo || 0);
                    fila.className = 'js-seleccionar-desembolso';
                    if (item.bloqueado || disponible <= 0) {
                        fila.classList.add('table-danger');
                    } else if (fisico > 0 || sgo > 0) {
                        fila.classList.add('table-warning');
                    }
                    fila.setAttribute('role', 'button');
                    fila.setAttribute('tabindex', '0');
                    fila.setAttribute('aria-selected', 'false');
                    fila.style.cursor = (item.bloqueado || disponible <= 0) ? 'not-allowed' : 'pointer';
                    fila.title = (item.bloqueado || disponible <= 0)
                        ? 'Este desembolso ya no tiene saldo disponible.'
                        : 'Disponible para cobrar: $' + aplicarFormatoOdoo(disponible || item.cantidad_de_dinero || 0);
                    fila.innerHTML = `
                        <td class="text-center">${item.numero_de_pagos || ''}</td>
                        <td class="text-end">$${aplicarFormatoOdoo(item.cantidad_de_dinero)}</td>
                        <td class="text-center">${aplicarFormatoOdoo(item.porcentaje_pago)}%</td>
                        <td class="text-center">${item.porcentaje_acumulado ? aplicarFormatoOdoo(item.porcentaje_acumulado) + '%' : ''}</td>
                    `;
                    fila.addEventListener('click', function() { seleccionarDesembolso(item, fila); });
                    fila.addEventListener('keydown', function(event) {
                        if (event.key === 'Enter' || event.key === ' ') {
                            event.preventDefault();
                            seleccionarDesembolso(item, fila);
                        }
                    });
                    tbodyPagos.appendChild(fila);
                });
            } else if (tipoRelacion === 'otrosi' && inputValorCuenta) {
                inputValorCuenta.dataset.formaPagoManual = '1';
                tbodyPagos.innerHTML = '<tr><td colspan="4" class="text-center text-muted py-3">Este otrosí no tiene registros en la tabla de Forma de pago. Puede ingresar el valor manualmente.</td></tr>';
                configurarBotonTabla('#modalFormaPago', 'Ver forma de pago', 'fa-table');
            }
            esperandoPagosContractuales = false;
            actualizarBloqueoValorCuenta();
            actualizarPorcentajePago();
            if (inputValorCuenta) {
                inputValorCuenta.dispatchEvent(new Event('change', {bubbles: true}));
            }
        }).catch(() => {
            esperandoPagosContractuales = false;
            configurarBotonTabla('#modalFormaPago', 'Ver forma de pago', 'fa-table');
            if (tbodyPagos) {
                tbodyPagos.innerHTML = '<tr><td colspan="4" class="text-center text-danger py-3">No fue posible cargar la Forma de pago. Intente nuevamente.</td></tr>';
            }
        });
    }

    // --- EVENTOS DE SELECTORES ---
    if (selectPrincipal) {
        selectPrincipal.addEventListener('change', function() {
            if (labelTotalRelacion) {
                labelTotalRelacion.textContent = this.value === 'otrosi'
                    ? 'Valor total del otrosí'
                    : 'Valor total del contrato';
            }
            if(tablaBienesContainer) tablaBienesContainer.style.display = 'none';
            if(contenedorTablaPagos) contenedorTablaPagos.style.display = 'none';
            if(btnVerTabla) btnVerTabla.style.display = 'none';
            actualizarBloqueoValorCuenta();
            activarDetalleRelacionActual();
        });
    }

    var selectIds = ['relacion_fuv_id', 'relacion_orden_compra_servicios_fuv_id', 'relacion_orden_compra_bienes_fuv_id', 'relacion_otrosi_fuv_id'];
    selectIds.forEach(id => {
        var el = document.getElementById(id);
        if (el) {
            el.addEventListener('change', function() {
                var opt = this.options[this.selectedIndex];
                var valorContrato = opt.getAttribute('data-valor') || 0;
                if (inputTotalContrato) inputTotalContrato.value = aplicarFormatoOdoo(valorContrato);

                if (!this.value) {
                    if(btnVerTabla) btnVerTabla.style.display = 'none';
                    actualizarBloqueoValorCuenta();
                } else if(id === 'relacion_fuv_id') {
                    bloquearValorCuenta('Primero selecciona el desembolso');
                    cargarTablaPagos(this.value, 'contrato');
                    configurarBotonTabla('#modalFormaPago', 'Ver forma de pago', 'fa-table');
                } else if(id === 'relacion_otrosi_fuv_id') {
                    bloquearValorCuenta('Primero selecciona el desembolso');
                    cargarTablaPagos(this.value, 'otrosi');
                    configurarBotonTabla('#modalFormaPago', 'Ver forma de pago', 'fa-table');
                } else if(id === 'relacion_orden_compra_bienes_fuv_id') {
                    habilitarValorCuenta();
                    cargarLineasBienes(this.value);
                    configurarBotonTabla('#modalFormaBienes', 'Ver líneas de bienes', 'fa-list');
                } else if(id === 'relacion_orden_compra_servicios_fuv_id') {
                    habilitarValorCuenta();
                    cargarLineasServicios(this.value);
                    configurarBotonTabla('#modalFormaServicios', 'Ver líneas de servicios', 'fa-concierge-bell');
                }
            });
        }
    });

    function activarDetalleRelacionActual() {
        var tipoActual = tipoActualSeleccionado();
        if (tipoActual === 'contrato') {
            var contratoActual = document.getElementById('relacion_fuv_id');
            if (contratoActual) {
                if (contratoActual.value) {
                    cargarTablaPagos(contratoActual.value, 'contrato');
                    configurarBotonTabla('#modalFormaPago', 'Ver forma de pago', 'fa-table');
                }
            }
        } else if (tipoActual === 'otrosi') {
            var otrosiActual = document.getElementById('relacion_otrosi_fuv_id');
            if (otrosiActual) {
                if (otrosiActual.value) {
                    cargarTablaPagos(otrosiActual.value, 'otrosi');
                    configurarBotonTabla('#modalFormaPago', 'Ver forma de pago', 'fa-table');
                }
            }
        } else if (tipoActual === 'bienes') {
            var bienesActual = document.getElementById('relacion_orden_compra_bienes_fuv_id');
            if (bienesActual) {
                if (bienesActual.value) {
                    habilitarValorCuenta();
                    cargarLineasBienes(bienesActual.value);
                    configurarBotonTabla('#modalFormaBienes', 'Ver líneas de bienes', 'fa-list');
                }
            }
        } else if (tipoActual === 'servicios') {
            var serviciosActual = document.getElementById('relacion_orden_compra_servicios_fuv_id');
            if (serviciosActual) {
                if (serviciosActual.value) {
                    habilitarValorCuenta();
                    cargarLineasServicios(serviciosActual.value);
                    configurarBotonTabla('#modalFormaServicios', 'Ver líneas de servicios', 'fa-concierge-bell');
                }
            }
        }
    }

    // Si el navegador/Odoo restaura una relación ya seleccionada,
    // muestra el detalle correcto sin esperar otro cambio.
    activarDetalleRelacionActual();

    // --- REFERENCIAS PARA SERVICIOS ---
    var tbodyServicios = document.getElementById('tbody_lineas_servicios');
    var tablaServiciosContainer = document.getElementById('tabla_servicios_container');

    function cargarLineasServicios(ordenId) {
        if (!ordenId || ordenId === "") {
            if(tablaServiciosContainer) tablaServiciosContainer.style.display = 'none';
            return;
        }

        if(tbodyServicios) tbodyServicios.innerHTML = '<tr><td colspan="2" class="text-center py-2"><i class="fa fa-spinner fa-spin"></i> Cargando servicios...</td></tr>';
        if(tablaServiciosContainer) tablaServiciosContainer.style.display = 'block';

        fetch('/public/obtener_lineas_servicios', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ params: { orden_id: ordenId } })
        })
        .then(response => response.json())
        .then(data => {
            var res = data.result;
            if(!tbodyServicios) return;
            tbodyServicios.innerHTML = '';

            if (res && res.lineas && res.lineas.length > 0) {
                res.lineas.forEach(linea => {
                    var fila = document.createElement('tr');
                    var valorLinea = Number(linea.valor_total || linea.valor_unitario || 0);
                    fila.setAttribute('role', 'button');
                    fila.setAttribute('tabindex', '0');
                    fila.setAttribute('aria-selected', 'false');
                    fila.style.cursor = 'pointer';
                    fila.title = 'Seleccionar este valor para la cuenta';
                    fila.innerHTML = `
                        <td class="align-middle">${linea.descripcion}</td>
                        <td class="text-end align-middle">$${aplicarFormatoOdoo(valorLinea)}</td>
                    `;
                    fila.addEventListener('click', function() {
                        seleccionarValorOrden(valorLinea, fila, tbodyServicios, 'modalFormaServicios');
                    });
                    fila.addEventListener('keydown', function(event) {
                        if (event.key === 'Enter' || event.key === ' ') {
                            event.preventDefault();
                            seleccionarValorOrden(valorLinea, fila, tbodyServicios, 'modalFormaServicios');
                        }
                    });
                    tbodyServicios.appendChild(fila);
                });
            } else {
                tbodyServicios.innerHTML = '<tr><td colspan="2" class="text-center">No hay líneas de servicio en esta orden.</td></tr>';
            }
        })
        .catch(error => {
            console.error("Error cargando servicios:", error);
            if(tbodyServicios) tbodyServicios.innerHTML = '<tr><td colspan="2" class="text-center text-danger">Error de conexión.</td></tr>';
        });
    }

    // --- ACTUALIZACIÓN DEL EVENTO DE SELECTORES ---
    // Busca donde tienes el forEach de 'selectIds' y asegúrate de añadir esta línea:

    selectIds.forEach(id => {
        var el = document.getElementById(id);
        if (el) {
            el.addEventListener('change', function() {
                // ... (tu lógica de montos actual) ...

                // Lógica de carga de tablas según el ID
                if(id === 'relacion_orden_compra_bienes_fuv_id') cargarLineasBienes(this.value);
                if(id === 'relacion_orden_compra_servicios_fuv_id') cargarLineasServicios(this.value); // <--- AGREGAR ESTO

                // Ocultar la otra tabla si cambias de tipo
                if(id === 'relacion_orden_compra_servicios_fuv_id') {
                    if(tablaBienesContainer) tablaBienesContainer.style.display = 'none';
                }
                if(id === 'relacion_orden_compra_bienes_fuv_id') {
                    if(tablaServiciosContainer) tablaServiciosContainer.style.display = 'none';
                }
            });
        }
    });

    // Formateo al escribir
    if (inputValorCuenta) {
        inputValorCuenta.addEventListener('input', actualizarPorcentajePago);
        inputValorCuenta.addEventListener('input', function() {
            this.classList.remove('is-invalid');
        });
        inputValorCuenta.addEventListener('blur', function() {
            validarMontos();
        });
        inputValorCuenta.addEventListener('focus', function() {
            var n = limpiarNumero(this.value);
            if (n > 0) this.value = n.toString().replace('.', ',');
        });
    }
    if (inputNumeroPago) {
        function sincronizarPagoEditado() {
            if (esCuentaRegalias()) {
                delete inputNumeroPago.dataset.desembolsoSeleccionado;
                habilitarValorCuenta();
                actualizarPorcentajePago();
                return;
            }
            var cuota = cuotaSeleccionada();
            var disponible = cuota ? Number(cuota.valor_disponible || cuota.cantidad_de_dinero || 0) : 0;
            pagoCargadoDesdeTabla = Boolean(cuota && !cuota.bloqueado && disponible > 0);

            if (pagoCargadoDesdeTabla) {
                inputNumeroPago.dataset.desembolsoSeleccionado = String(cuota.numero_de_pagos || '');
                habilitarValorCuenta();
            } else {
                delete inputNumeroPago.dataset.desembolsoSeleccionado;
                if (!esOtroSiPagoManual() && inputValorCuenta) {
                    // Se conserva el valor elegido mientras el usuario termina
                    // de escribir o selecciona un Pago N° válido.
                    inputValorCuenta.setAttribute('readonly', 'readonly');
                    inputValorCuenta.placeholder = 'Selecciona un Pago N° válido';
                }
            }

            if (tbodyPagos) {
                Array.prototype.forEach.call(tbodyPagos.querySelectorAll('tr'), function (fila, indice) {
                    var item = pagosContractuales[indice];
                    var seleccionada = Boolean(
                        item && parseInt(item.numero_de_pagos, 10) === parseInt(inputDesembolsoOrigen && inputDesembolsoOrigen.value, 10)
                    );
                    fila.classList.toggle('table-primary', seleccionada);
                    fila.setAttribute('aria-selected', seleccionada ? 'true' : 'false');
                });
            }
            actualizarPorcentajePago();
        }

        inputNumeroPago.addEventListener('input', sincronizarPagoEditado);
        inputNumeroPago.addEventListener('change', sincronizarPagoEditado);
    }

    // Limpieza final antes de enviar a Odoo
    if (form) {
        form.addEventListener('submit', function(e) {
            if (!validarMontos()) { e.preventDefault(); return; }
            inputValorCuenta.value = limpiarNumero(inputValorCuenta.value);
            if (inputTotalContrato) inputTotalContrato.value = limpiarNumero(inputTotalContrato.value);
        });
    }
});
//


document.addEventListener('DOMContentLoaded', function () {
    var inputTotalContrato = document.getElementById('valor_total_contrato');
    var inputValorCuenta = document.getElementById('valor_cuenta');
    var form = inputValorCuenta ? inputValorCuenta.closest('form') : null;

    // 1. FUNCIÓN PARA FORMATEAR: 1000000.50 -> 1.000.000,50
    function aplicarFormatoOdoo(numero) {
        if (!numero && numero !== 0) return "";
        return new Intl.NumberFormat('de-DE', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }).format(numero);
    }

    // 2. FUNCIÓN PARA LIMPIAR: 1.000.000,50 -> 1000000.50 (Lo que Odoo entiende)
    function limpiarNumero(texto) {
        if (!texto) return 0;
        // Quitamos puntos y cambiamos la coma decimal por punto
        var limpio = texto.toString().split('.').join('').replace(',', '.');
        return parseFloat(limpio) || 0;
    }

    // 3. VALIDACIÓN DE MONTOS
    function validarMontos() {
        var valorCuentaNum = limpiarNumero(inputValorCuenta.value);
        var valorTotalNum = limpiarNumero(inputTotalContrato.value);

        if (valorTotalNum > 0 && valorCuentaNum > valorTotalNum) {
            Swal.fire({
                icon: 'error',
                title: '¡Alto!',
                text: 'El valor de la cuenta ($' + aplicarFormatoOdoo(valorCuentaNum) + ') NO puede ser mayor al valor del contrato ($' + aplicarFormatoOdoo(valorTotalNum) + ').',
                confirmButtonText: 'Aceptar',
                confirmButtonColor: '#8d4b41'
            });
            inputValorCuenta.value = "";
            inputValorCuenta.style.borderColor = "red";
            return false;
        } else {
            inputValorCuenta.style.borderColor = "";
            if (inputValorCuenta.value) {
                inputValorCuenta.value = aplicarFormatoOdoo(valorCuentaNum);
            }
            return true;
        }
    }

    // 4. LÓGICA DE SELECTORES (Cargar valor del contrato)
    var selectIds = [
        'relacion_fuv_id',
        'relacion_orden_compra_servicios_fuv_id',
        'relacion_orden_compra_bienes_fuv_id',
        'relacion_otrosi_fuv_id'
    ];

    selectIds.forEach(function(id) {
        var selectElement = document.getElementById(id);
        if (selectElement) {
            selectElement.addEventListener('change', function () {
                var selectedOption = this.options[this.selectedIndex];
                var valor = selectedOption.getAttribute('data-valor') || 0;
                if (inputTotalContrato) {
                    inputTotalContrato.value = aplicarFormatoOdoo(valor);
                }
                if (inputValorCuenta && inputValorCuenta.value) {
                    validarMontos();
                }
                if (typeof window.actualizarPorcentajePago === 'function') {
                    window.actualizarPorcentajePago();
                }
            });
        }
    });

    // 5. EVENTOS DEL CAMPO VALOR CUENTA
    if (inputValorCuenta) {
        inputValorCuenta.addEventListener('input', function() {
            if (typeof window.actualizarPorcentajePago === 'function') {
                window.actualizarPorcentajePago();
            }
        });
        // Formatear al salir del campo
        inputValorCuenta.addEventListener('blur', function() {
            validarMontos();
            if (typeof window.actualizarPorcentajePago === 'function') {
                window.actualizarPorcentajePago();
            }
        });

        // Quitar puntos al entrar para editar fácil
        inputValorCuenta.addEventListener('focus', function() {
            var num = limpiarNumero(this.value);
            if (num > 0) {
                this.value = num.toString().replace('.', ',');
            }
        });
    }
    // La normalización al enviar se ejecuta en el controlador principal.
    // Repetirla aquí eliminaba el punto decimal del valor ya normalizado.
    if (typeof window.actualizarPorcentajePago === 'function') {
        window.actualizarPorcentajePago();
    }
});


document.addEventListener('DOMContentLoaded', function () {
    var formulario = document.querySelector(
        'form[action="/public/cuentas_de_cobros/create"]'
    );

    if (!formulario) {
        return;
    }

    var checkFactura = formulario.querySelector('#factura_si_o_no');
    var inputNumeroFactura = formulario.querySelector('#numero_factura');
    var inputTipoPersona = formulario.querySelector(
        'input[name="clase_persona"]'
    );

    /* Factura de Persona Natural */
    var filaFacturaNatural = formulario.querySelector('#row_factura_doc');
    var archivoFacturaNatural = formulario.querySelector('#factura_doc');

    if (!checkFactura || !inputNumeroFactura) {
        return;
    }

    function actualizarFactura() {
        var facturaActiva = checkFactura.checked;
        var tipoPersona = inputTipoPersona
            ? inputTipoPersona.value
            : '';

        /*
        * Habilitar o bloquear el número de factura.
        */
        if (facturaActiva) {
            inputNumeroFactura.removeAttribute('readonly');
            inputNumeroFactura.setAttribute('required', 'required');
            inputNumeroFactura.style.backgroundColor = '#ffffff';
            inputNumeroFactura.style.cursor = 'text';
        } else {
            inputNumeroFactura.setAttribute('readonly', 'readonly');
            inputNumeroFactura.removeAttribute('required');
            inputNumeroFactura.value = '';
            inputNumeroFactura.style.backgroundColor = '#f1f3f5';
            inputNumeroFactura.style.cursor = 'not-allowed';
        }

        /*
        * El archivo factura_doc pertenece solamente
        * a Persona Natural.
        */
        if (tipoPersona === 'persona_natural') {
            if (filaFacturaNatural) {
                filaFacturaNatural.style.display = facturaActiva
                    ? 'table-row'
                    : 'none';
            }

            if (archivoFacturaNatural) {
                if (facturaActiva) {
                    archivoFacturaNatural.setAttribute(
                        'required',
                        'required'
                    );
                } else {
                    archivoFacturaNatural.removeAttribute('required');
                    archivoFacturaNatural.value = '';
                }
            }
        } else {
            /*
            * Para Persona Jurídica nunca se debe exigir
            * el archivo oculto de Persona Natural.
            */
            if (filaFacturaNatural) {
                filaFacturaNatural.style.display = 'none';
            }

            if (archivoFacturaNatural) {
                archivoFacturaNatural.removeAttribute('required');
                archivoFacturaNatural.value = '';
            }
        }
    }

    checkFactura.addEventListener('change', actualizarFactura);
    actualizarFactura();
});


document.addEventListener('DOMContentLoaded', function () {
    var form = document.querySelector('form[action="/public/cuentas_de_cobros/create"]');
    if (!form) return;

    var inicio = form.querySelector('[name="inicio_actividad"]');
    var fin = form.querySelector('[name="finalizacion_actividad"]');
    var relacionSelects = [
        'proyecto_regalias_id',
        'relacion_fuv_id',
        'relacion_orden_compra_servicios_fuv_id',
        'relacion_orden_compra_bienes_fuv_id',
        'relacion_otrosi_fuv_id'
    ].map(function (name) {
        return form.querySelector('[name="' + name + '"]');
    }).filter(Boolean);

    function selectedRelationOption() {
        for (var i = 0; i < relacionSelects.length; i++) {
            var select = relacionSelects[i];
            if (select.offsetParent !== null && select.value) {
                return select.options[select.selectedIndex];
            }
        }
        return null;
    }

    function applyDateLimits() {
        if (inicio) {
            inicio.setAttribute('min', '1000-01-01');
            inicio.setAttribute('max', '9999-12-31');
        }
        if (fin) {
            fin.setAttribute('min', '1000-01-01');
            fin.setAttribute('max', '9999-12-31');
        }
    }

    function clearDateError(input) {
        if (!input) return;
        input.classList.remove('is-invalid');
        input.setCustomValidity('');
        var feedback = input.parentElement.querySelector('.sgo-activity-date-error');
        if (feedback) feedback.textContent = '';
    }
    function showDateError(input, message, move) {
        input.classList.add('is-invalid');
        input.setCustomValidity(message);
        var feedback = input.parentElement.querySelector('.sgo-activity-date-error');
        if (feedback) {
            feedback.textContent = message;
            feedback.style.display = 'block';
        }
        if (move) {
            input.scrollIntoView({behavior: 'smooth', block: 'center'});
            setTimeout(function () {
                try {
                    input.focus({preventScroll: true});
                    if (!input.readOnly &amp;&amp; input.showPicker) input.showPicker();
                } catch (e) {
                    input.focus();
                }
            }, 350);
        }
    }
    function invalidDateYear(input) {
        if (!input || !input.value) return false;
        var match = input.value.match(/^(\d{4,})-(\d{2})-(\d{2})$/);
        return !match || Number(match[1]) < 1000 || Number(match[1]) > 9999;
    }
    function validateActivityDates(move) {
        clearDateError(inicio);
        clearDateError(fin);
        if (invalidDateYear(inicio)) {
            inicio.value = '';
            showDateError(inicio, 'La fecha de inicio tenía un año inválido. Selecciónala nuevamente con el calendario.', move);
            return false;
        }
        if (invalidDateYear(fin)) {
            fin.value = '';
            showDateError(fin, 'La fecha de finalización tenía un año inválido. Selecciónala nuevamente con el calendario.', move);
            return false;
        }
        if (inicio && fin && inicio.value && fin.value && fin.value < inicio.value) {
            fin.value = '';
            showDateError(fin, 'La fecha de finalización no puede ser anterior a la fecha de inicio. Selecciónala nuevamente.', move);
            return false;
        }
        return true;
    }

    relacionSelects.forEach(function (select) {
        select.addEventListener('change', applyDateLimits);
    });
    [inicio, fin].forEach(function (input) {
        if (!input) return;
        input.addEventListener('input', function () { clearDateError(input); });
        input.addEventListener('change', function () { validateActivityDates(true); });
    });
    form.addEventListener('submit', function (event) {
        if (!validateActivityDates(true)) {
            event.preventDefault();
            event.stopImmediatePropagation();
        }
    }, true);
    applyDateLimits();
    setTimeout(function () {
        var forcedField = new URLSearchParams(window.location.search).get('fecha_error');
        var forcedInput = forcedField === 'inicio_actividad' ? inicio :
            (forcedField === 'finalizacion_actividad' ? fin : null);
        if (forcedInput) {
            var forcedMessage = forcedField === 'inicio_actividad'
                ? 'La fecha de inicio tenía un año inválido. Selecciónala nuevamente con el calendario.'
                : 'La fecha de finalización tenía un año inválido. Selecciónala nuevamente con el calendario.';
            forcedInput.value = '';
            showDateError(forcedInput, forcedMessage, true);
        } else {
            validateActivityDates(true);
        }
    }, 300);
});


document.addEventListener('DOMContentLoaded', function () {
    var switchBtn = document.getElementById('opcion_otro_documento');
    var filaOtro = document.getElementById('fila_otro_documento');
