document.addEventListener('change', function (event) {
    // Detecta cualquier input de tipo file que cambie en la página
    if (event.target.type === 'file') {
        var input = event.target;

        if (input.files && input.files.length > 0) {
            // Si seleccionó archivo: Verde (Success)
            input.style.setProperty('background-color', '#d1e7dd', 'important');
            input.style.setProperty('border-color', '#a3cfbb', 'important');
            input.style.setProperty('color', '#0f5132', 'important');
        } else {
            // Si está vacío: Vuelve al diseño original
            input.style.removeProperty('background-color');
            input.style.removeProperty('border-color');
            input.style.removeProperty('color');
        }
    }
});


