document.addEventListener('DOMContentLoaded', function () {
    function fileDescriptor(file) {
        var name = file && file.name ? file.name.toLowerCase() : '';
        var type = file && file.type ? file.type.toLowerCase() : '';
        var extension = name.indexOf('.') >= 0 ? name.split('.').pop() : '';
        if (type === 'application/pdf' || extension === 'pdf') {
            return {icon: 'fa-file-pdf-o', css: 'sgo-type-pdf', label: 'PDF'};
        }
        if (['doc', 'docx', 'odt'].indexOf(extension) >= 0) {
            return {icon: 'fa-file-word-o', css: 'sgo-type-word', label: 'Word'};
        }
        if (['xls', 'xlsx', 'csv', 'ods'].indexOf(extension) >= 0) {
            return {icon: 'fa-file-excel-o', css: 'sgo-type-excel', label: 'Excel'};
        }
        if (type.indexOf('image/') === 0 || ['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg'].indexOf(extension) >= 0) {
            return {icon: 'fa-file-image-o', css: 'sgo-type-image', label: 'Imagen'};
        }
        return {icon: 'fa-file-o', css: '', label: extension ? extension.toUpperCase() : 'Documento'};
    }

    function enhanceFileInput(input) {
        if (!input || input.dataset.sgoDropzoneReady === '1') return;
        input.dataset.sgoDropzoneReady = '1';

        var zone = document.createElement('div');
        zone.className = 'sgo-dropzone';
        zone.setAttribute('role', 'button');
        zone.setAttribute('aria-label', 'Arrastra tu archivo aquí o selecciónalo');

        var content = document.createElement('div');
        content.className = 'sgo-dropzone-content';

        var iconBox = document.createElement('span');
        iconBox.className = 'sgo-dropzone-file-icon';
        var icon = document.createElement('i');
        icon.className = 'fa fa-cloud-upload';
        iconBox.appendChild(icon);

        var copy = document.createElement('span');
        copy.className = 'sgo-dropzone-copy';
        var primary = document.createElement('strong');
        primary.className = 'sgo-dropzone-primary';
        var selectText = document.createElement('span');
        selectText.className = 'sgo-dropzone-select';
        var meta = document.createElement('small');
        meta.className = 'sgo-dropzone-meta';
        copy.appendChild(primary);
        copy.appendChild(selectText);
        copy.appendChild(meta);

        var changeText = document.createElement('span');
        changeText.className = 'sgo-dropzone-change';
        changeText.innerHTML = '<i class="fa fa-exchange mr-1"></i> Cambiar';

        content.appendChild(iconBox);
        content.appendChild(copy);
        zone.appendChild(content);
        zone.appendChild(changeText);
        input.parentNode.insertBefore(zone, input);
        zone.insertBefore(input, content);

        function refresh() {
            var files = input.files ? Array.prototype.slice.call(input.files) : [];
            var hasFiles = files.length > 0;
            zone.classList.toggle('has-file', hasFiles);
            iconBox.className = 'sgo-dropzone-file-icon';

            if (hasFiles) {
                var descriptor = fileDescriptor(files[0]);
                if (descriptor.css) iconBox.classList.add(descriptor.css);
                icon.className = 'fa ' + descriptor.icon;
                primary.textContent = files.length > 1
                    ? files[0].name + ' y ' + (files.length - 1) + ' más'
                    : files[0].name;
                selectText.textContent = '';
                meta.textContent = files.length > 1
                    ? files.length + ' archivos seleccionados'
                    : descriptor.label + ' seleccionado';
            } else {
                icon.className = 'fa fa-cloud-upload';
                primary.textContent = 'Arrastra tu archivo aquí';
                selectText.textContent = ' o selecciona el archivo';
                meta.textContent = '';
            }
        }

        input.sgoRefreshDropzone = refresh;
        input.addEventListener('change', refresh);

        ['dragenter', 'dragover'].forEach(function (eventName) {
            zone.addEventListener(eventName, function (event) {
                if (input.disabled) return;
                event.preventDefault();
                event.stopPropagation();
                zone.classList.add('is-dragover');
            });
        });

        ['dragleave', 'dragend'].forEach(function (eventName) {
            zone.addEventListener(eventName, function (event) {
                event.preventDefault();
                zone.classList.remove('is-dragover');
            });
        });

        zone.addEventListener('drop', function (event) {
            if (input.disabled) return;
            event.preventDefault();
            event.stopPropagation();
            zone.classList.remove('is-dragover');
            var dropped = event.dataTransfer && event.dataTransfer.files
                ? Array.prototype.slice.call(event.dataTransfer.files)
                : [];
            if (!dropped.length || typeof DataTransfer === 'undefined') return;
            var transfer = new DataTransfer();
            dropped.slice(0, input.multiple ? dropped.length : 1).forEach(function (file) {
                transfer.items.add(file);
            });
            input.files = transfer.files;
            input.dispatchEvent(new Event('change', {bubbles: true}));
        });

        refresh();
    }

    document.querySelectorAll('.sgo-upload-documents').forEach(function (block) {
        block.querySelectorAll('.doc-table-row').forEach(function (row) {
            var labelCell = row.querySelector('td:first-child');
            var label = labelCell ? labelCell.querySelector('label') : null;
            if (labelCell && label && !labelCell.querySelector('.sgo-upload-chip')) {
                var cleanLabel = label.textContent.replace(/\s+/g, ' ').trim();
                var required = cleanLabel.indexOf('*') === 0;
                var chip = document.createElement('span');
                chip.className = 'sgo-upload-chip' + (required ? '' : ' is-optional');
                chip.textContent = required
                    ? 'Requerido'
                    : (cleanLabel.toLowerCase().indexOf('si aplica') >= 0 ? 'Si aplica' : 'Opcional');
                labelCell.appendChild(chip);
            }
        });

        block.querySelectorAll('input[type="file"]').forEach(enhanceFileInput);
    });

    document.querySelectorAll('[data-sgo-cesion-upload="1"] input[type="file"]').forEach(enhanceFileInput);

    [
        {toggle: 'opcion_otro_documento', input: 'otro_documentos_de_inf_doc'},
        {toggle: 'opcion_otro_documento_juridica', input: 'otro_documentos_de_inf_doc_juridica'},
        {toggle: 'cesion_derechos_create', input: 'cesion_derechos_doc_create'}
    ].forEach(function (config) {
        var toggle = document.getElementById(config.toggle);
        var input = document.getElementById(config.input);
        if (toggle && input) {
            toggle.addEventListener('change', function () {
                window.setTimeout(function () {
                    if (input.sgoRefreshDropzone) input.sgoRefreshDropzone();
                }, 0);
            });
        }
    });
});


document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('[data-sgo-cesion-toggle="1"]').forEach(function (toggle) {
        var card = toggle.closest('.modern-card');
        if (!card) return;
        var uploadBox = card.querySelector('[data-sgo-cesion-upload="1"]');
        var fileInputs = uploadBox ? uploadBox.querySelectorAll('input[type="file"]') : [];

        function actualizarCesion() {
            var activo = toggle.checked;
            if (uploadBox) {
                uploadBox.style.display = activo ? '' : 'none';
            }
            fileInputs.forEach(function (input) {
                input.disabled = !activo;
                if (!activo) {
                    input.value = '';
                    input.style.removeProperty('background-color');
                    input.style.removeProperty('border-color');
                    input.style.removeProperty('color');
                }
            });
        }

        actualizarCesion();
        toggle.addEventListener('change', actualizarCesion);
    });
});

//
    // 1. Funciones del Loader (Pantalla de carga)
    function showLoadingOverlay() {
        var loader = document.getElementById('loading-overlay');
        if (loader) {
            document.body.appendChild(loader);
            loader.style.display = 'flex';
            document.body.style.overflow = 'hidden';
        }
    }

    function hideLoadingOverlay() {
        var loader = document.getElementById('loading-overlay');
        if (loader) {
            loader.style.display = 'none';
            document.body.style.overflow = 'auto';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        var formateadorMoneda = new Intl.NumberFormat('es-CO', {
            style: 'currency',
            currency: 'COP',
            minimumFractionDigits: 0
        });

        function enfocarValorCuentaParaCorregir(inputCuenta) {
            if (!inputCuenta) return;
            inputCuenta.classList.add('is-invalid');
            setTimeout(function () {
                inputCuenta.scrollIntoView({behavior: 'smooth', block: 'center'});
                setTimeout(function () {
                    inputCuenta.focus({preventScroll: true});
                    inputCuenta.select();
                }, 400);
            }, 350);
        }

        // =========================================================================
        // A) VALIDACIÓN 1: El error viene de la Base de Datos (Python detectó el tope)
        // =========================================================================
        var urlParams = new URLSearchParams(window.location.search);

        if (urlParams.get('alerta_elegante') === 'tope_excedido') {
            // Quitamos el loader por si acaso quedó pegado
            hideLoadingOverlay();

            Swal.fire({
                icon: 'error',
                title: '¡No se pudo guardar!',
                html: 'El valor de la cuenta, <strong>sumado a los cobros anteriores</strong>, supera el valor total del contrato.<br><br>Por favor, revisa tus facturas previas y corrige el valor.',
                confirmButtonText: 'Entendido',
                confirmButtonColor: '#d33'
            }).then((result) => {
                if (result.isConfirmed) {
                    var inputCuenta = document.getElementById('valor_cuenta');
                    if(inputCuenta) {
                        enfocarValorCuentaParaCorregir(inputCuenta);
                    }
                }
            });

            // Limpiamos la URL silenciosamente para que la alerta no vuelva a salir si el usuario recarga la página
            var urlLimpia = window.location.protocol + "//" + window.location.host + window.location.pathname;
            window.history.replaceState({path: urlLimpia}, '', urlLimpia);
        } else if (
            urlParams.get('alerta_elegante') === 'contrato_regalias_requerido'
            || urlParams.get('alerta_elegante') === 'proyecto_regalias_requerido'
        ) {
            hideLoadingOverlay();
            var faltaContratoRegalias = urlParams.get('alerta_elegante') === 'contrato_regalias_requerido';
            Swal.fire({
                icon: 'warning',
                title: faltaContratoRegalias
                    ? 'Falta seleccionar el contrato de Regalías'
                    : 'Falta seleccionar el proyecto de Regalías',
                text: 'Para crear la cuenta debes seleccionar el contrato y el proyecto de Regalías.',
                confirmButtonText: 'Entendido',
                confirmButtonColor: '#043484'
            });
            var urlRegaliasLimpia = window.location.protocol + "//" + window.location.host + window.location.pathname;
            window.history.replaceState({path: urlRegaliasLimpia}, '', urlRegaliasLimpia);
        } else if (urlParams.get('alerta_elegante') === 'saldo_regalias_agotado') {
            hideLoadingOverlay();
            Swal.fire({
                icon: 'warning',
                title: 'Contrato sin saldo disponible',
                text: 'Este contrato ya fue cobrado en su totalidad y no puede usarse para crear otra cuenta de Regalías.',
                confirmButtonText: 'Entendido',
                confirmButtonColor: '#043484'
            });
            var urlSaldoRegaliasLimpia = window.location.protocol + "//" + window.location.host + window.location.pathname;
            window.history.replaceState({path: urlSaldoRegaliasLimpia}, '', urlSaldoRegaliasLimpia);
        }

        // =========================================================================
        // B) VALIDACIÓN 2: En tiempo real al presionar el botón de Guardar (JS)
        // =========================================================================
        var formulario = document.querySelector('form');

        if (formulario) {
            formulario.addEventListener('submit', function(event) {
                // Si faltan campos requeridos, dejamos que el navegador haga su trabajo
                if (!formulario.checkValidity()) {
                    return;
                }

                function parsePortalMoney(value) {
                    var text = (value || '').toString().trim().replace(/\s/g, '');
                    if (!text) return 0;
                    if (text.indexOf(',') !== -1 && text.indexOf('.') !== -1) {
                        if (text.lastIndexOf(',') > text.lastIndexOf('.')) {
                            text = text.split('.').join('').replace(',', '.');
                        } else {
                            text = text.split(',').join('');
                        }
                    } else if (text.indexOf(',') !== -1) {
                        text = text.replace(',', '.');
                    }
                    return parseFloat(text) || 0;
                }

                var valorTotalInput = document.getElementById('valor_total_contrato').value;
                var valorCuentaInput = document.getElementById('valor_cuenta').value;

                var valorTotal = parsePortalMoney(valorTotalInput);
                var valorCuenta = parsePortalMoney(valorCuentaInput);
                var tipoContrato = document.getElementById('selecionar');
                var origenCuenta = document.getElementById('origen_cuenta');
                var esRegalias = origenCuenta && origenCuenta.value === 'regalias';
                var pagoInput = document.getElementById('pago_create');

                function relationForSelectedType() {
                    if (!tipoContrato) return null;
                    if (tipoContrato.value === 'contrato') return document.getElementById('relacion_fuv_id');
                    if (tipoContrato.value === 'servicios') return document.getElementById('relacion_orden_compra_servicios_fuv_id');
                    if (tipoContrato.value === 'bienes') return document.getElementById('relacion_orden_compra_bienes_fuv_id');
                    if (tipoContrato.value === 'otrosi') return document.getElementById('relacion_otrosi_fuv_id');
                    return null;
                }

                if (!esRegalias && tipoContrato && !tipoContrato.value) {
                    event.preventDefault();
                    hideLoadingOverlay();
                    tipoContrato.classList.add('is-invalid');
                    Swal.fire({
                        icon: 'warning',
                        title: 'Falta seleccionar el tipo de contrato',
                        text: 'Seleccione el tipo de contrato antes de crear la cuenta de cobro.',
                        confirmButtonText: 'Entendido',
                        confirmButtonColor: '#3085d6'
                    }).then(function () {
                        tipoContrato.focus();
                    });
                    return;
                }

                var relacionSeleccionada = esRegalias ? null : relationForSelectedType();
                if (!esRegalias && relacionSeleccionada && !relacionSeleccionada.value) {
                    event.preventDefault();
                    hideLoadingOverlay();
                    relacionSeleccionada.classList.add('is-invalid');
                    Swal.fire({
                        icon: 'warning',
                        title: 'Falta seleccionar la relación',
                        text: 'Seleccione el contrato, orden u otrosí antes de crear la cuenta de cobro.',
                        confirmButtonText: 'Entendido',
                        confirmButtonColor: '#3085d6'
                    }).then(function () {
                        relacionSeleccionada.focus();
                    });
                    return;
                }

                var pagoNumero = parseInt((pagoInput && pagoInput.value) || '0', 10) || 0;
                if (pagoNumero < 1) {
                    event.preventDefault();
                    hideLoadingOverlay();
                    if (pagoInput) pagoInput.classList.add('is-invalid');
                    Swal.fire({
                        icon: 'warning',
                        title: 'Pago N° inválido',
                        text: 'El Pago N° debe ser mayor a cero.',
                        confirmButtonText: 'Entendido',
                        confirmButtonColor: '#3085d6'
                    }).then(function () {
                        if (pagoInput) pagoInput.focus();
                    });
                    return;
                }

                if (esRegalias) {
                    var saldoRegaliasInput = document.getElementById('valor_cuenta');
                    var saldoRegaliasMaximo = saldoRegaliasInput ? Number(saldoRegaliasInput.dataset.saldoRegalias || 0) : 0;
                    if (saldoRegaliasMaximo > 0 && valorCuenta > saldoRegaliasMaximo) {
                        event.preventDefault();
                        hideLoadingOverlay();

                        Swal.fire({
                            icon: 'warning',
                            title: 'Saldo por utilizar excedido',
                            html: 'El valor de la cuenta no puede superar el saldo por utilizar (<strong>' + formateadorMoneda.format(saldoRegaliasMaximo) + '</strong>).',
                            confirmButtonText: 'Entendido',
                            confirmButtonColor: '#3085d6'
                        }).then(function () {
                            if (saldoRegaliasInput) {
                                enfocarValorCuentaParaCorregir(saldoRegaliasInput);
                            }
                        });

                        if (saldoRegaliasInput) saldoRegaliasInput.classList.add('is-invalid');
                        return;
                    }
                }

                // Si se pasa del tope en este mismo formulario
                if (valorCuenta > valorTotal) {
                    event.preventDefault(); // Detenemos el envío
                    hideLoadingOverlay();   // Apagamos el loader

                    var cuentaEnPesos = formateadorMoneda.format(valorCuenta);
                    var totalEnPesos = formateadorMoneda.format(valorTotal);

                    Swal.fire({
                        icon: 'warning',
                        title: '¡Atención!',
                        html: 'El valor de la cuenta (<strong>' + cuentaEnPesos + '</strong>) no puede superar el valor total del contrato (<strong>' + totalEnPesos + '</strong>).<br><br>Por favor, corrige el valor antes de enviar.',
                        confirmButtonText: 'Entendido',
                        confirmButtonColor: '#3085d6'
                    }).then((result) => {
                        if (result.isConfirmed) {
                            enfocarValorCuentaParaCorregir(
                                document.getElementById('valor_cuenta')
                            );
                        }
                    });

                    document.getElementById('valor_cuenta').classList.add('is-invalid');

                } else {
                    // ¡Todo está bien! Dejamos pasar los datos a Python y encendemos el loader
                    document.getElementById('valor_cuenta').classList.remove('is-invalid');
                    showLoadingOverlay();
                }
            });
        }
    });
//

t.script:
document.addEventListener('DOMContentLoaded', function () {
    var origen = document.getElementById('origen_cuenta');
    var origenRadios = document.querySelectorAll('input[name="origen_cuenta_radio"]');
    var detalle = document.getElementById('detalle_cuenta_cobro');
    var tipoContratoField = document.getElementById('tipo_contrato_field');
    var tipoContrato = document.getElementById('selecionar');
    var proyectoField = document.getElementById('proyecto_regalias_field');
    var proyecto = document.getElementById('proyecto_regalias_id');
    var contratoRegaliasField = document.getElementById('contrato_regalias_field');
    var contratoRegalias = document.getElementById('contrato_regalias_id');
    var totalField = document.getElementById('valor_total_relacion_field');
    var totalInput = document.getElementById('valor_total_contrato');
    var labelTotalRelacion = document.getElementById('label_valor_total_relacion');
    var saldoRegaliasField = document.getElementById('saldo_regalias_field');
    var saldoRegaliasDisplay = document.getElementById('saldo_regalias_display');
    var valorCuentaRegalias = document.getElementById('valor_cuenta');
    var porcentajeField = document.getElementById('porcentaje_pago_field');
    var porcentajeAcumuladoField = document.getElementById('porcentaje_acumulado_field');
    var porcentajeInput = document.getElementById('porcentaje_de_pago_create');
    var porcentajeAcumuladoInput = document.getElementById('porcentaje_acumulado_create');
    var pagoInput = document.getElementById('pago_create');
    var botonFormaPago = document.getElementById('btnVerTabla');
    var mensajeFormaPago = document.getElementById('mensaje_forma_pago');
    var modalFormaPago = document.getElementById('modalFormaPago');
    var camposSoloRegalias = document.querySelectorAll('.sgo-regalias-only');
    var alertaRegaliasActiva = false;

    function etiquetaIdentificacionRegalias() {
        var clasePersonaInput = document.querySelector('input[name="clase_persona"]');
        var clasePersona = clasePersonaInput ? clasePersonaInput.value : '';
        return clasePersona === 'persona_juridica' ? 'NIT' : 'documento de identidad';
    }

    function normalizarRegalias(valor) {
        return (valor || '')
            .toString()
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[^0-9a-zA-Z]+/g, '')
            .toLowerCase();
    }

    function numeroRegalias(valor) {
        var texto = (valor || '').toString().replace(/\$/g, '').replace(/\s/g, '');
        if (!texto) return 0;
        if (texto.indexOf(',') >= 0 && texto.indexOf('.') >= 0) {
            if (texto.lastIndexOf(',') > texto.lastIndexOf('.')) {
                texto = texto.replace(/\./g, '').replace(',', '.');
            } else {
                texto = texto.replace(/,/g, '');
            }
        } else if (texto.indexOf(',') >= 0) {
            texto = texto.replace(',', '.');
        }
        return Number(texto) || 0;
    }

    function formatoRegalias(numero) {
        return Number(numero || 0).toLocaleString('es-CO', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        });
    }

    function actualizarContratosRegalias() {
        if (!proyecto || !contratoRegalias) return;
        var esRegalias = origen && origen.value === 'regalias';
        var hayOpciones = false;
        var seleccionPrevia = contratoRegalias.value || contratoRegalias.dataset.ultimaSeleccion || '';

        Array.prototype.forEach.call(contratoRegalias.options, function (option) {
            if (!option.value) {
                option.textContent = 'Seleccione un contrato';
                option.style.display = '';
                return;
            }
            var visible = esRegalias;
            option.style.display = visible ? '' : 'none';
            option.disabled = !visible;
            if (visible) hayOpciones = true;
        });

        var opcionPrevia = Array.prototype.find.call(contratoRegalias.options, function (option) {
            return option.value === seleccionPrevia && !option.disabled && option.style.display !== 'none';
        });
        if (esRegalias && opcionPrevia) {
            contratoRegalias.value = seleccionPrevia;
            contratoRegalias.dataset.ultimaSeleccion = seleccionPrevia;
        } else if (!esRegalias) {
            contratoRegalias.value = '';
        }
        contratoRegalias.required = esRegalias;
        contratoRegalias.disabled = !esRegalias;
        contratoRegaliasField.style.display = esRegalias ? '' : 'none';
        if (esRegalias && !hayOpciones) {
            contratoRegalias.options[0].textContent = 'No hay contratos asociados a tu ' + etiquetaIdentificacionRegalias();
        }
    }

    function actualizarProyectosRegalias() {
        if (!proyecto || !contratoRegalias) return;
        var esRegalias = origen && origen.value === 'regalias';
        var opcionContrato = contratoRegalias.options[contratoRegalias.selectedIndex];
        var unidadContratoKey = normalizarRegalias(opcionContrato ? opcionContrato.getAttribute('data-un') : '');
        var opcionesVisibles = 0;
        var primerProyectoVisible = '';
        var seleccionPrevia = proyecto.value || proyecto.dataset.ultimaSeleccion || '';

        Array.prototype.forEach.call(proyecto.options, function (option) {
            if (!option.value) {
                option.textContent = unidadContratoKey ? 'Seleccione un proyecto' : 'Primero seleccione un contrato';
                option.style.display = '';
                return;
            }
            var unidadProyectoKey = normalizarRegalias(option.getAttribute('data-unidad-negocio'));
            var visible = esRegalias && unidadContratoKey && unidadProyectoKey === unidadContratoKey;
            option.style.display = visible ? '' : 'none';
            option.disabled = !visible;
            if (visible) {
                opcionesVisibles += 1;
                if (!primerProyectoVisible) primerProyectoVisible = option.value;
            }
        });

        var opcionPrevia = Array.prototype.find.call(proyecto.options, function (option) {
            return option.value === seleccionPrevia && !option.disabled && option.style.display !== 'none';
        });
        proyecto.value = opcionPrevia
            ? seleccionPrevia
            : (opcionesVisibles === 1 ? primerProyectoVisible : '');
        proyecto.dataset.ultimaSeleccion = proyecto.value || '';
        proyecto.disabled = !esRegalias || !unidadContratoKey;
        proyecto.required = esRegalias;
        if (esRegalias && unidadContratoKey && !opcionesVisibles) {
            proyecto.options[0].textContent = 'No hay proyectos compatibles con la unidad de negocio del contrato';
        }
    }

    function actualizarContratoRegalias() {
        if (!contratoRegalias || !totalInput) return;
        var opcion = contratoRegalias.options[contratoRegalias.selectedIndex];
        var valorContrato = opcion ? numeroRegalias(opcion.getAttribute('data-valor')) : 0;
        var saldoContrato = opcion ? numeroRegalias(opcion.getAttribute('data-saldo')) : 0;
        if (valorContrato || saldoContrato) {
            totalInput.value = valorContrato || saldoContrato;
        } else {
            totalInput.value = '';
            actualizarProyectoRegalias();
        }
        if (saldoRegaliasDisplay) {
            saldoRegaliasDisplay.value = saldoContrato
                ? saldoContrato.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2})
                : '';
        }
        if (valorCuentaRegalias) {
            if (saldoContrato) {
                valorCuentaRegalias.setAttribute('max', saldoContrato);
                valorCuentaRegalias.dataset.saldoRegalias = saldoContrato;
                valorCuentaRegalias.title = 'El valor de la cuenta/factura no puede superar el saldo por utilizar: $ ' + saldoContrato.toLocaleString('es-CO', {minimumFractionDigits: 2, maximumFractionDigits: 2});
            } else {
                valorCuentaRegalias.removeAttribute('max');
                delete valorCuentaRegalias.dataset.saldoRegalias;
                valorCuentaRegalias.title = 'El valor de la cuenta/factura debe ser mayor a cero.';
            }
            validarValorCuentaRegalias();
        }
        if (porcentajeInput) porcentajeInput.value = '';
        if (porcentajeAcumuladoInput) porcentajeAcumuladoInput.value = '';
        actualizarProyectosRegalias();
    }

    function validarValorCuentaRegalias(mostrarAlerta) {
        if (!origen || !valorCuentaRegalias || origen.value !== 'regalias') return true;
        var saldoContrato = Number(valorCuentaRegalias.dataset.saldoRegalias || 0);
        var valorCuenta = numeroRegalias(valorCuentaRegalias.value);
        if (saldoContrato && valorCuenta > saldoContrato) {
            valorCuentaRegalias.setCustomValidity(
                'El valor de la cuenta/factura no puede superar el saldo por utilizar del contrato de Regalías.'
            );
            valorCuentaRegalias.classList.add('is-invalid');
            if (mostrarAlerta && !alertaRegaliasActiva) {
                alertaRegaliasActiva = true;
                Swal.fire({
                    icon: 'warning',
                    title: 'Saldo por utilizar excedido',
                    html: 'El valor a cobrar no puede superar el saldo por utilizar ($ ' + formatoRegalias(saldoContrato) + ').',
                    confirmButtonText: 'Entendido',
                    confirmButtonColor: '#043484'
                }).then(function () {
                    alertaRegaliasActiva = false;
                    valorCuentaRegalias.value = formatoRegalias(saldoContrato);
                    valorCuentaRegalias.setCustomValidity('');
                    valorCuentaRegalias.classList.remove('is-invalid');
                    valorCuentaRegalias.focus();
                });
            }
            return false;
        }
        valorCuentaRegalias.setCustomValidity('');
        valorCuentaRegalias.classList.remove('is-invalid');
        return true;
    }

    function actualizarProyectoRegalias() {
        if (!proyecto || !totalInput) return;
        if (origen && origen.value === 'regalias') {
            if (porcentajeInput) porcentajeInput.value = '';
            if (porcentajeAcumuladoInput) porcentajeAcumuladoInput.value = '';
            return;
        }
        var opcion = proyecto.options[proyecto.selectedIndex];
        var costo = opcion ? Number(opcion.getAttribute('data-valor') || 0) : 0;
        totalInput.value = costo;
        if (porcentajeInput) porcentajeInput.value = '';
        if (porcentajeAcumuladoInput) porcentajeAcumuladoInput.value = '';
    }

    function adaptarOrigenCuenta() {
        if (!origen || !detalle) return;
        var esRegalias = origen.value === 'regalias';
        var seleccionado = !!origen.value;
        detalle.style.display = seleccionado ? '' : 'none';
        if (tipoContratoField) tipoContratoField.style.display = esRegalias ? 'none' : '';
        if (proyectoField) proyectoField.style.display = esRegalias ? '' : 'none';
        if (contratoRegaliasField) contratoRegaliasField.style.display = esRegalias ? '' : 'none';
        if (tipoContrato) {
            tipoContrato.required = !esRegalias;
            if (esRegalias) tipoContrato.value = 'regalias';
            else if (tipoContrato.value === 'regalias') tipoContrato.value = '';
            tipoContrato.dispatchEvent(new Event('change', {bubbles: true}));
        }
        if (proyecto) {
            proyecto.required = esRegalias;
            if (!esRegalias) proyecto.disabled = true;
        }
        if (contratoRegalias) {
            contratoRegalias.required = esRegalias;
            contratoRegalias.disabled = !esRegalias;
        }
        if (totalField) totalField.style.display = '';
        if (labelTotalRelacion) labelTotalRelacion.textContent = esRegalias ? 'Valor total del contrato' : 'Valor total del contrato';
        if (saldoRegaliasField) saldoRegaliasField.style.display = esRegalias ? '' : 'none';
        if (!esRegalias && saldoRegaliasDisplay) saldoRegaliasDisplay.value = '';
        if (!esRegalias && valorCuentaRegalias) {
            valorCuentaRegalias.removeAttribute('max');
            delete valorCuentaRegalias.dataset.saldoRegalias;
            valorCuentaRegalias.setCustomValidity('');
            valorCuentaRegalias.title = 'El valor de la cuenta/factura debe ser mayor a cero.';
        }
        if (porcentajeField) porcentajeField.style.display = esRegalias ? 'none' : '';
        if (porcentajeAcumuladoField) porcentajeAcumuladoField.style.display = esRegalias ? 'none' : '';
        if (pagoInput) pagoInput.placeholder = esRegalias
            ? 'Escriba el Pago N°'
            : 'Selecciona el desembolso o escribe el Pago N°';
        if (botonFormaPago && esRegalias) botonFormaPago.style.display = 'none';
        if (mensajeFormaPago) {
            if (esRegalias) {
                mensajeFormaPago.style.setProperty('display', 'none', 'important');
            } else {
                mensajeFormaPago.style.removeProperty('display');
            }
        }
        if (modalFormaPago) modalFormaPago.style.display = esRegalias ? 'none' : '';
        camposSoloRegalias.forEach(function (row) {
            row.style.display = esRegalias ? 'table-row' : 'none';
        });
        if (esRegalias) {
            actualizarContratosRegalias();
            actualizarContratoRegalias();
            actualizarProyectosRegalias();
        }
        else if (contratoRegalias) {
            contratoRegalias.value = '';
            delete contratoRegalias.dataset.ultimaSeleccion;
            if (proyecto) {
                proyecto.value = '';
                delete proyecto.dataset.ultimaSeleccion;
            }
        }
    }

    if (origen) origen.addEventListener('change', adaptarOrigenCuenta);
    Array.prototype.forEach.call(origenRadios, function (radio) {
        radio.addEventListener('change', function () {
            if (!this.checked || !origen) return;
            origen.value = this.value;
            origen.dispatchEvent(new Event('change', {bubbles: true}));
        });
    });
    if (proyecto) proyecto.addEventListener('change', function () {
        proyecto.dataset.ultimaSeleccion = proyecto.value || '';
        proyecto.classList.remove('is-invalid');
        actualizarProyectoRegalias();
    });
    if (contratoRegalias) contratoRegalias.addEventListener('change', function () {
        contratoRegalias.dataset.ultimaSeleccion = contratoRegalias.value || '';
        contratoRegalias.classList.remove('is-invalid');
        actualizarContratoRegalias();
    });
    if (valorCuentaRegalias) {
        valorCuentaRegalias.addEventListener('input', function () {
            validarValorCuentaRegalias(false);
        });
        valorCuentaRegalias.addEventListener('blur', function () {
            validarValorCuentaRegalias(true);
        });
    }
    adaptarOrigenCuenta();

    // Script para manejar el selector de tipo de contrato
    const contratoSelector = document.getElementById('selecionar');
    const contratoField = document.getElementById('contrato_field');
    const serviciosField = document.getElementById('servicios_field');
    const bienesField = document.getElementById('bienes_field');
    const otrosiField = document.getElementById('otrosi_field');

    function limpiarDatosAlCambiarContexto() {
        [
            'nombre_entrega',
            'pago_create',
            'pago_forma_pago_create',
            'inicio_actividad',
            'finalizacion_actividad'
        ].forEach(function (id) {
            var campo = document.getElementById(id);
            if (!campo) return;
            campo.value = '';
            campo.classList.remove('is-invalid');
            campo.setCustomValidity('');
            if (id === 'pago_create') {
                delete campo.dataset.desembolsoSeleccionado;
            }
            var feedbackFecha = campo.parentElement
                ? campo.parentElement.querySelector('.sgo-activity-date-error')
                : null;
            if (feedbackFecha) {
                feedbackFecha.textContent = '';
                feedbackFecha.style.display = 'none';
            }
            campo.dispatchEvent(new Event('input', {bubbles: true}));
            campo.dispatchEvent(new Event('change', {bubbles: true}));
        });

        document.querySelectorAll('#modalFormaPago tbody tr').forEach(function (fila) {
            fila.classList.remove('table-primary');
            fila.setAttribute('aria-selected', 'false');
        });
    }

    function toggleContratoFields() {
        const value = contratoSelector.value;
        const relacionContrato = document.getElementById('relacion_fuv_id');
        const relacionServicios = document.getElementById('relacion_orden_compra_servicios_fuv_id');
        const relacionBienes = document.getElementById('relacion_orden_compra_bienes_fuv_id');
        const relacionOtrosi = document.getElementById('relacion_otrosi_fuv_id');

        // Mostrar/Ocultar campos según la selección
        contratoField.style.display = value === 'contrato' ? 'block' : 'none';
        serviciosField.style.display = value === 'servicios' ? 'block' : 'none';
        bienesField.style.display = value === 'bienes' ? 'block' : 'none';
        otrosiField.style.display = value === 'otrosi' ? 'block' : 'none';

        // Solo el selector que corresponde al tipo elegido participa
        // en el envío y en la validación required. Los otros quedan
        // deshabilitados para que nunca interfieran.
        [
            ['contrato', relacionContrato],
            ['servicios', relacionServicios],
            ['bienes', relacionBienes],
            ['otrosi', relacionOtrosi]
        ].forEach(function (item) {
            const tipo = item[0];
            const select = item[1];
            if (!select) return;
            const activo = tipo === value;
            select.disabled = !activo;
            select.required = activo;
            select.setAttribute('aria-required', activo ? 'true' : 'false');
            if (!activo) {
                select.value = '';
                select.classList.remove('is-invalid');
                select.setCustomValidity('');
            }
        });

    }

    // Al cambiar el origen o el tipo, no se deben reutilizar datos
    // diligenciados para la relación anterior.
    contratoSelector.addEventListener('change', function () {
        limpiarDatosAlCambiarContexto();
        toggleContratoFields();
    });

    // Ejecutar al cargar la página para el selector de contrato
    toggleContratoFields();

    // Script para manejar el selector de clase de persona
    const personaSelector = document.getElementById('clase_persona_selector');
    const naturalBlock = document.getElementById('bloque_persona_natural');
    const juridicaBlock = document.getElementById('bloque_persona_juridica');

    // Campos obligatorios para persona natural
    const requiredDocsNatural = [
        "planilla_de_aportes_a_seguridad_social_doc",
        "declaracion_juramentada_y_soportes_doc",
        "rut_actualizado_doc",
        "certificacion_bancaria_doc"
    ];

    // Campos obligatorios para persona jurídica
    const requiredDocsJuridica = [
        "factura_electronica_juridica_documento_doc",
        "rut_actualizado_juridica_documento",
        "camara_comercio_juridica_documento",
        "certificado_pago_parafiscales_juridica_documento",
        "planilla_de_seguridad_social_ju_doc",
        "certificacion_bancaria_juridica_documento",
    ];

    // Función para activar/desactivar required
    function setRequired(docs, required) {
        docs.forEach(id => {
            const input = document.getElementById(id);
            if (input) {
                if (required) {
                    input.setAttribute("required", "required");
                } else {
                    input.removeAttribute("required");
                }
            }
        });
    }

    // Mostrar/Ocultar bloques y asignar required
    function togglePersonaBlocks() {
        const value = personaSelector.value;

        if (value === 'persona_natural') {
            naturalBlock.style.display = 'block';
            juridicaBlock.style.display = 'none';
            setRequired(requiredDocsNatural, true);
            setRequired(requiredDocsJuridica, false);
        }
        else if (value === 'persona_juridica') {
            naturalBlock.style.display = 'none';
            juridicaBlock.style.display = 'block';
            setRequired(requiredDocsNatural, false);
            setRequired(requiredDocsJuridica, true);
        }
        else {
            naturalBlock.style.display = 'none';
            juridicaBlock.style.display = 'none';
            setRequired(requiredDocsNatural, false);
            setRequired(requiredDocsJuridica, false);
        }
    }

    // Escuchar cambios en el selector de clase de persona
    personaSelector.addEventListener('change', togglePersonaBlocks);

    // Ejecutar al cargar la página para el selector de clase de persona
    togglePersonaBlocks();
});


document.addEventListener('DOMContentLoaded', function () {
    var form = document.querySelector('form[action="/public/cuentas_de_cobros/create"]');
    if (!form) return;

    var guide = form.querySelector('[data-sgo-portal-guide="1"]');
    if (!guide) return;

    var title = guide.querySelector('[data-sgo-guide-title="1"]');
    var detail = guide.querySelector('[data-sgo-guide-detail="1"]');
    var status = guide.querySelector('[data-sgo-guide-status="1"]');
    var missing = guide.querySelector('[data-sgo-guide-missing="1"]');
    var origenCuenta = form.querySelector('[name="origen_cuenta"]');

    function normalize(text) {
        return (text || '').toString().toLowerCase()
            .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    }

    function isVisible(el) {
        return !!(el && (el.offsetWidth || el.offsetHeight || el.getClientRects().length));
    }

    function labelFor(el) {
        var scope = el.closest('.doc-cell-container, .doc-table-row, tr, .col-md-12, .col-md-6, .col-md-4, .mb-3') || el.parentElement;
        var label = scope ? scope.querySelector('label') : null;
        return label ? label.textContent.replace(/[✔✘]/g, '').replace(/\s+/g, ' ').trim() : (el.name || 'este campo');
    }

    function esRegaliasActiva() {
        return !!(origenCuenta && origenCuenta.value === 'regalias');
    }

    function etiquetaIdentificacionRegalias() {
        var clasePersonaInput = form.querySelector('input[name="clase_persona"]');
        var clasePersona = clasePersonaInput ? clasePersonaInput.value : '';
        return clasePersona === 'persona_juridica' ? 'NIT' : 'documento de identidad';
    }

    function labelPaso(el, esRegalias) {
        if (!el) return 'este campo';
        var name = el.name || '';
        if (name === 'origen_cuenta_radio' || name === 'origen_cuenta') {
            return 'Sistema de origen';
        }
        if (esRegalias && name === 'contrato_regalias_id') {
            return 'Contrato de Regalías';
        }
        if (name === 'valor_cuenta') {
            return esRegalias
                ? 'Valor cuenta/factura (máximo saldo por utilizar)'
                : 'Valor cuenta/factura';
        }
        if (name === 'pago') {
            return 'Pago N°';
        }
        return labelFor(el).replace('Ver forma de pago', '').replace(/\s+/g, ' ').trim();
    }

    function isFactura(el) {
        if (!el) return false;

        var name = normalize(el.name || '');
        var id = normalize(el.id || '');
        var label = normalize(labelFor(el));

        // IMPORTANTE:
        // Valor cuenta/factura NO se debe saltar.
        if (name === 'valor_cuenta' || id === 'valor_cuenta' || id === 'valor_cuenta_web') {
            return false;
        }

        // Solo saltar campos reales de factura/documento factura.
        return (
            name.indexOf('factura') !== -1 ||
            id.indexOf('factura') !== -1 ||
            label === 'factura' ||
            label.indexOf('factura electronica') !== -1
        );
    }

    function facturaSwitchActive() {
        var switchFactura = form.querySelector('#factura_si_o_no');
        return !!(switchFactura && switchFactura.checked);
    }

    function isFilled(el) {
        if (!isVisible(el) || el.disabled) return true;
        if (el.type === 'radio') {
            return !!form.querySelector('input[name="' + el.name + '"]:checked');
        }
        if (isFactura(el) && labelFor(el).indexOf('*') === -1 && !facturaSwitchActive()) return true;
        if (el.type === 'file') return !!(el.files && el.files.length);
        return !!(el.value && el.value.toString().trim());
    }

    function relationSelector() {
        var names = [
            'relacion_fuv_id',
            'relacion_orden_compra_servicios_fuv_id',
            'relacion_orden_compra_bienes_fuv_id',
            'relacion_otrosi_fuv_id'
        ];
        for (var i = 0; i < names.length; i++) {
            var el = form.querySelector('[name="' + names[i] + '"]');
            if (isVisible(el)) return el;
        }
        return null;
    }

    function requiredDocumentInputs() {
        var requiredDocumentNames = [
            'planilla_de_aportes_a_seguridad_social_doc',
            'planilla_de_seguridad_social_ju_doc',
            'rut_actualizado_doc',
            'rut_actualizado_juridica_documento',
            'certificacion_bancaria_doc',
            'certificacion_bancaria_juridica_documento',
            'camara_comercio_juridica_documento',
            'certificado_pago_parafiscales_juridica_documento'
        ];
        return Array.prototype.slice.call(form.querySelectorAll('input[type="file"]')).filter(function (input) {
            if (!isVisible(input)) return false;
            var label = normalize(labelFor(input));
            if (isFactura(input) && label.indexOf('*') === -1 && !facturaSwitchActive()) return false;
            if (requiredDocumentNames.indexOf(input.name || input.id || '') !== -1) return true;
            return label.indexOf('*') !== -1 && label.indexOf('opcional') === -1 && label.indexOf('si aplica') === -1;
        });
    }

    function orderedSteps() {
        var steps = [];
        var esRegalias = esRegaliasActiva();
        var selectors = ['[name="origen_cuenta_radio"]'];
        if (esRegalias) {
            selectors.push('[name="contrato_regalias_id"]');
            selectors.push('[name="proyecto_regalias_id"]');
        } else {
            selectors.push('[name="selecionar"]');
        }
        selectors.push('[name="fecha_solicitud"]', '[name="nombre_entrega"]');
        selectors.forEach(function (selector) {
            var el = form.querySelector(selector);
            if (el) steps.push({el: el, label: labelPaso(el, esRegalias)});
        });

        var tipoContrato = form.querySelector('[name="selecionar"]');
        var pago = form.querySelector('[name="pago"]');
        var valorCuenta = form.querySelector('[name="valor_cuenta"]');
        var botonFormaPago = form.querySelector('#btnVerTabla');
        var otroSiManual = tipoContrato
            && tipoContrato.value === 'otrosi'
            && valorCuenta
            && valorCuenta.dataset.formaPagoManual === '1';
        if (
            !esRegalias &&
            tipoContrato &&
            (tipoContrato.value === 'contrato' || (tipoContrato.value === 'otrosi' && !otroSiManual)) &&
            botonFormaPago
        ) {
            steps.push({
                el: botonFormaPago,
                completionEl: valorCuenta,
                label: 'Seleccionar desembolso en Forma de pago',
                formaPago: true
            });
        }

        var camposDetalle = [
            '[name="valor_cuenta"]',
            '[name="pago"]',
            '[name="inicio_actividad"]'
        ];
        camposDetalle.push('[name="finalizacion_actividad"]');
        camposDetalle.forEach(function (selector) {
            var el = form.querySelector(selector);
            if (el) {
                steps.push({
                    el: el,
                    label: selector === '[name="valor_cuenta"]' && otroSiManual
                        ? 'Escribir el valor de la cuenta manualmente'
                        : labelPaso(el, esRegalias),
                    valorManualOtrosi: selector === '[name="valor_cuenta"]' && otroSiManual,
                    pagoNumero: selector === '[name="pago"]'
                });
            }
        });

        var relation = esRegalias ? null : relationSelector();
        if (relation) steps.splice(1, 0, {el: relation, label: labelPaso(relation, esRegalias)});

        if (facturaSwitchActive()) {
            var numeroFactura = form.querySelector('[name="numero_factura"]');
            var archivoFactura = form.querySelector('[name="factura_doc"]');
            if (numeroFactura) {
                steps.push({el: numeroFactura, label: 'Número de factura', facturaNumero: true});
            }
            if (archivoFactura) {
                steps.push({el: archivoFactura, label: 'Documento de factura', facturaArchivo: true});
            }
        }

        requiredDocumentInputs().forEach(function (input) {
            steps.push({el: input, label: labelFor(input)});
        });

        return steps.filter(function (step, index, arr) {
            return step.el && arr.findIndex(function (other) { return other.el === step.el; }) === index;
        });
    }

    function firstPending() {
        var steps = orderedSteps();
        for (var i = 0; i < steps.length; i++) {
            var completionEl = steps[i].completionEl || steps[i].el;
            if (
                steps[i].pagoNumero
                && (parseInt((completionEl.value || '0'), 10) || 0) < 1
            ) {
                return {step: steps[i], index: i + 1, total: steps.length - i};
            }
            if (!isFilled(completionEl)) return {step: steps[i], index: i + 1, total: steps.length - i};
        }
        return null;
    }

    function clearHighlights() {
        form.querySelectorAll('.sgo-pending-highlight').forEach(function (el) {
            el.classList.remove('sgo-pending-highlight');
        });
        form.querySelectorAll('.sgo-ready-submit-highlight').forEach(function (el) {
            el.classList.remove('sgo-ready-submit-highlight');
        });
    }

    function focusPending(pending) {
        if (window.Swal && Swal.isVisible()) return;
        clearHighlights();
        if (!pending) return;
        var el = pending.step.el;
        var target = el.closest('tr, .modern-card, .col-md-12, .col-md-6, .col-md-4') || el;
        el.classList.add('sgo-pending-highlight');
        target.scrollIntoView({behavior: 'smooth', block: 'center'});
        setTimeout(function () {
            try { el.focus({preventScroll: true}); } catch (err) {}
        }, 450);
    }

    function updateGuide() {
        var pending = firstPending();
        var esRegalias = esRegaliasActiva();
        clearHighlights();
        if (pending) {
            form.dataset.sgoCreateCuentaReadyShown = '';
            title.textContent = 'Paso ' + pending.index + ': completa ' + pending.step.label + '.';
            if (pending.step.facturaNumero) {
                detail.textContent = 'Activaste factura. Primero escribe el número de la factura en este campo.';
            } else if (pending.step.facturaArchivo) {
                detail.textContent = 'Ahora sube el documento de la factura para dejar el soporte completo.';
            } else if (pending.step.formaPago) {
                detail.textContent = 'Abre la tabla de Forma de pago y selecciona el desembolso que vas a cobrar.';
            } else if (pending.step.valorManualOtrosi) {
                detail.textContent = 'Este otrosí no tiene registros en la tabla de Forma de pago. Escribe manualmente el valor que vas a cobrar.';
            } else if (pending.step.pagoNumero) {
                var valorCuentaPaso = form.querySelector('[name="valor_cuenta"]');
                var pagoManualOtrosi = !esRegalias
                    && form.querySelector('[name="selecionar"]')
                    && form.querySelector('[name="selecionar"]').value === 'otrosi'
                    && valorCuentaPaso
                    && valorCuentaPaso.dataset.formaPagoManual === '1';
                detail.textContent = esRegalias
                    ? 'Escribe el número de pago correspondiente para este contrato de Regalías.'
                    : pagoManualOtrosi
                        ? 'Como este otrosí no tiene Forma de pago registrada, escribe manualmente el Pago N° que corresponde.'
                        : 'El Pago N° se toma del desembolso seleccionado en la tabla de Forma de pago.';
            } else if (esRegalias && pending.step.el && pending.step.el.name === 'contrato_regalias_id') {
                detail.textContent = 'Primero selecciona tu contrato de Regalías. Solo se muestran contratos asociados a tu ' + etiquetaIdentificacionRegalias() + '.';
            } else if (esRegalias && pending.step.el && pending.step.el.name === 'proyecto_regalias_id') {
                detail.textContent = 'Ahora selecciona el proyecto compatible con la unidad de negocio del contrato. Si solo hay uno, el sistema lo selecciona automáticamente.';
            } else if (esRegalias && pending.step.el && pending.step.el.name === 'valor_cuenta') {
                detail.textContent = 'Escribe el valor que vas a cobrar. No puede superar el saldo por utilizar del contrato seleccionado.';
            } else {
                detail.textContent = 'Apenas completes este punto, el sistema seguirá guiándote con el siguiente dato o documento pendiente.';
            }
            if (status) status.textContent = pending.total > 1 ? 'En proceso' : 'Último pendiente';
            if (missing) missing.textContent = pending.step.label;
        } else {
            title.textContent = 'Todo listo: puedes crear la cuenta de cobro.';
            detail.textContent = esRegalias
                ? 'Antes de crearla, revisa que el valor a cobrar no supere el saldo por utilizar. Luego presiona Crear cuenta de cobro.'
                : 'Antes de crearla, puedes adjuntar informes, documentos adicionales o certificado de expensas si aplica. Luego presiona Crear cuenta de cobro.';
            if (status) status.textContent = 'Completado';
            if (missing) missing.textContent = 'Crear cuenta de cobro';
            var createButton = form.querySelector('[data-sgo-create-cuenta-btn="1"]');
            if (createButton) createButton.classList.add('sgo-ready-submit-highlight');
        }
        return pending;
    }

    function advanceToNextPending() {
        if (window.Swal && Swal.isVisible()) return;
        var pending = updateGuide();
        if (pending) focusPending(pending);
        else {
            var createButton = form.querySelector('[data-sgo-create-cuenta-btn="1"]');
            if (createButton && form.dataset.sgoCreateCuentaReadyShown !== '1') {
                form.dataset.sgoCreateCuentaReadyShown = '1';
                createButton.scrollIntoView({behavior: 'smooth', block: 'center'});
                setTimeout(function () {
                    try { createButton.focus({preventScroll: true}); } catch (err) {}
                }, 450);
            }
        }
    }

    form.addEventListener('change', function () {
        setTimeout(advanceToNextPending, 120);
    });
    form.addEventListener('input', updateGuide);
    form.addEventListener('blur', function (event) {
        if (event.target && isFilled(event.target)) {
            setTimeout(advanceToNextPending, 120);
        }
    }, true);
    setTimeout(advanceToNextPending, 250);
});

document.addEventListener('DOMContentLoaded', function () {
    const passwordInput = document.getElementById('password');
    const togglePassword = document.getElementById('togglePassword');
    togglePassword.addEventListener('click', function () {
        const isPassword = passwordInput.type === 'password';
        passwordInput.type = isPassword ? 'text' : 'password';
        togglePassword.className = isPassword ? 'fa fa-eye-slash' : 'fa fa-eye';
    });
});

document.addEventListener('DOMContentLoaded', function () {
    const passwordInput = document.getElementById('password');
    const confirmInput = document.getElementById('confirm_password');
    const togglePassword = document.getElementById('togglePassword');
    const toggleConfirm = document.getElementById('toggleConfirmPassword');
    const form = document.querySelector('form[action="/public/reset_password/submit"]');

    // Toggle visibility for password fields
    togglePassword.addEventListener('click', function () {
        const isPassword = passwordInput.type === 'password';
        passwordInput.type = isPassword ? 'text' : 'password';
        togglePassword.className = isPassword ? 'fa fa-eye-slash' : 'fa fa-eye';
    });

    toggleConfirm.addEventListener('click', function () {
        const isPassword = confirmInput.type === 'password';
        confirmInput.type = isPassword ? 'text' : 'password';
        toggleConfirm.className = isPassword ? 'fa fa-eye-slash' : 'fa fa-eye';
    });

    // Validate passwords match before submitting
    form.addEventListener('submit', function (event) {
        const password = passwordInput.value;
        const confirmPassword = confirmInput.value;

        // Remove any previous error message
        const existingError = document.getElementById('password-error');
        if (existingError) {
            existingError.remove();
        }

        if (password !== confirmPassword) {
            event.preventDefault(); // Prevent form submission

            // Display error message
            const errorDiv = document.createElement('div');
            errorDiv.id = 'password-error';
            errorDiv.className = 'alert alert-danger mt-3';
            errorDiv.textContent = 'Las contraseñas no coinciden. Por favor, inténtelo de nuevo.';
            form.parentNode.insertBefore(errorDiv, form);

            // Optionally, clear the password fields
            passwordInput.value = '';
            confirmInput.value = '';
        }
    });
});

div.script:
//
    document.addEventListener('DOMContentLoaded', function() {
        var notificationButton = document.getElementById('notificationMenu');
        if (!notificationButton) return;

        notificationButton.addEventListener('click', function() {
            var badge = document.getElementById('portalNotificationCount');
            if (badge) {
                badge.style.display = 'none';
            }

            var loginId = notificationButton.getAttribute('data-login-id');
            var token = notificationButton.getAttribute('data-token');
            if (!loginId || !token) return;

            fetch('/public/notifications/read/' + loginId + '/' + token, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {}})
            }).catch(function() {});
        });

        document.querySelectorAll('.js-delete-notification').forEach(function(button) {
            button.addEventListener('click', function(event) {
                event.preventDefault();
                event.stopPropagation();

                var key = button.getAttribute('data-key');
                var loginId = notificationButton.getAttribute('data-login-id');
                var token = notificationButton.getAttribute('data-token');
                var item = button.closest('.js-portal-notification');
                if (!key || !loginId || !token) return;

                fetch('/public/notifications/delete/' + loginId + '/' + token, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        jsonrpc: '2.0',
                        method: 'call',
                        params: {key: key}
                    })
                }).then(function(response) {
                    return response.json();
                }).then(function(data) {
                    if (data && data.result && data.result.ok && item) {
                        item.remove();
                        var remaining = document.querySelectorAll('.js-portal-notification').length;
                        if (!remaining) {
                            var menu = document.querySelector('.portal-notification-menu');
                            if (menu) {
                                var empty = document.createElement('div');
                                empty.className = 'px-3 py-4 text-center text-muted small js-empty-notifications';
                                empty.textContent = 'No tienes notificaciones por ahora.';
                                menu.appendChild(empty);
                            }
                        }
                    }
                }).catch(function() {});
            });
        });
    });
//

//
    document.addEventListener('DOMContentLoaded', function() {
        var botonCuentas = document.querySelector('.js-cuentas-cobro');

        if (botonCuentas) {
            botonCuentas.addEventListener('click', function(event) {
                event.preventDefault();
                var userId = this.getAttribute('data-uid');
                var userToken = this.getAttribute('data-utk');

                if (userId && userToken) {
                    window.location.href = '/public/cuentas_de_cobros/listado/' + userId + '/' + userToken;
                }
            });
        }
    });
//

t.script:
function validatePasswordChange(event) {
    var newPass = document.getElementById('new_password').value;
    var confPass = document.getElementById('confirm_password').value;
    var matchAlert = document.getElementById('password_match_alert');
    var lengthAlert = document.getElementById('password_length_alert');

    matchAlert.classList.add('d-none');
    lengthAlert.classList.add('d-none');

    if (newPass || confPass) {
        if (!newPass && confPass || newPass && !confPass) {
            matchAlert.innerHTML = ' Debes llenar ambos campos de contraseña.';
            matchAlert.classList.remove('d-none');
            event.preventDefault();
            return false;
        }

        if (newPass !== confPass) {
            matchAlert.innerHTML = ' ¡Error! Las contraseñas no coinciden.';
            matchAlert.classList.remove('d-none');
            event.preventDefault();
            return false;
        }

        if (newPass.length > 0 && newPass.length < 6) {
            lengthAlert.classList.remove('d-none');
            event.preventDefault();
            return false;
        }
    }

    return true;
}

div.script:
// 
    document.addEventListener('DOMContentLoaded', function () {
        var elNumeros = document.getElementById("valor_numeros");
        var campoLetras = document.getElementById("valor_letras");

        if (!elNumeros) return;

        // --- 1. Formato visual (puntos de mil y coma decimal) ---
        function aplicarFormatoOdoo(numero) {
            if (isNaN(numero) || numero === null) return "";
            return new Intl.NumberFormat('de-DE', {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2
            }).format(numero);
        }

        // --- 2. Limpieza inteligente de números (EL ARREGLO ESTÁ AQUÍ) ---
        function limpiarNumero(texto) {
            if (!texto) return 0;
            let s = texto.toString().trim();

            // Si el texto tiene una COMA, es formato visual (ej: 1.000,50)
            if (s.includes(',')) {
                return parseFloat(s.replace(/\./g, '').replace(',', '.')) || 0;
            }
            // Si NO tiene coma pero tiene punto, es formato DB (ej: 2.0)
            // Simplemente lo pasamos a float directamente
            return parseFloat(s) || 0;
        }

        function procesarYConvertir() {
            var valorNumerico = limpiarNumero(elNumeros.value);

            if (valorNumerico >= 0) {
                // Actualizar valor visual con formato .000,00
                elNumeros.value = aplicarFormatoOdoo(valorNumerico);

                // Convertir a letras
                var entero = Math.floor(valorNumerico);
                var textoEntregado = NumeroALetras(entero);
                var resultado = textoEntregado + " PESOS";

                campoLetras.value = resultado.charAt(0).toUpperCase() + resultado.slice(1).toLowerCase();

                // Ajustar altura
                campoLetras.style.height = 'auto';
                campoLetras.style.height = (campoLetras.scrollHeight) + 'px';
            }
        }

        // Ejecutar al cargar la página
        setTimeout(procesarYConvertir, 200);

        // Eventos
        elNumeros.addEventListener('blur', procesarYConvertir);

        elNumeros.addEventListener('focus', function() {
            var val = limpiarNumero(this.value);
            if (val > 0) {
                // Al editar, mostramos el número con coma decimal sin puntos de mil
                this.value = val.toString().replace('.', ',');
            }
        });

        // --- LÓGICA DE CONVERSIÓN (Tus funciones originales) ---
        function Unidades(num) {
            switch(num) {
                case 1: return "UN"; case 2: return "DOS"; case 3: return "TRES";
                case 4: return "CUATRO"; case 5: return "CINCO"; case 6: return "SEIS";
                case 7: return "SIETE"; case 8: return "OCHO"; case 9: return "NUEVE";
                default: return "";
            }
        }

        function Decenas(num) {
            var decena = Math.floor(num / 10);
            var unidad = num % 10;
            switch(decena) {
                case 1:
                    var especiales = ["DIEZ", "ONCE", "DOCE", "TRECE", "CATORCE", "QUINCE"];
                    return unidad <= 5 ? especiales[unidad] : "DIECI" + Unidades(unidad);
                case 2: return unidad === 0 ? "VEINTE" : "VEINTI" + Unidades(unidad);
                case 3: return unidad === 0 ? "TREINTA" : "TREINTA Y " + Unidades(unidad);
                case 4: return unidad === 0 ? "CUARENTA" : "CUARENTA Y " + Unidades(unidad);
                case 5: return unidad === 0 ? "CINCUENTA" : "CINCUENTA Y " + Unidades(unidad);
                case 6: return unidad === 0 ? "SESENTA" : "SESENTA Y " + Unidades(unidad);
                case 7: return unidad === 0 ? "SETENTA" : "SETENTA Y " + Unidades(unidad);
                case 8: return unidad === 0 ? "OCHENTA" : "OCHENTA Y " + Unidades(unidad);
                case 9: return unidad === 0 ? "NOVENTA" : "NOVENTA Y " + Unidades(unidad);
                default: return Unidades(unidad);
            }
        }

        function Centenas(num) {
            var centena = Math.floor(num / 100);
            var resto = num % 100;
            switch(centena) {
                case 1: return resto > 0 ? "CIENTO " + Decenas(resto) : "CIEN";
                case 2: return "DOSCIENTOS " + Decenas(resto);
                case 3: return "TRESCIENTOS " + Decenas(resto);
                case 4: return "CUATROCIENTOS " + Decenas(resto);
                case 5: return "QUINIENTOS " + Decenas(resto);
                case 6: return "SEISCIENTOS " + Decenas(resto);
                case 7: return "SETECIENTOS " + Decenas(resto);
                case 8: return "OCHOCIENTOS " + Decenas(resto);
                case 9: return "NOVECIENTOS " + Decenas(resto);
                default: return Decenas(resto);
            }
        }

        function NumeroALetras(num) {
            if (num === 0) return "CERO";
            if (num === 1) return "UN";
            var milMillones = Math.floor(num / 1000000000);
            var restoMilMillon = num % 1000000000;
            var millones = Math.floor(restoMilMillon / 1000000);
            var restoMillon = restoMilMillon % 1000000;
            var miles = Math.floor(restoMillon / 1000);
            var restoCientos = restoMillon % 1000;
            var strMilMillones = milMillones > 0 ? (milMillones === 1 ? "UN MIL" : Centenas(milMillones) + " MIL") + " MILLONES" : "";
            var strMillones = millones > 0 ? (millones === 1 ? "UN MILLON" : Centenas(millones) + " MILLONES") : "";
            var strMiles = miles > 0 ? (miles === 1 ? "MIL" : Centenas(miles) + " MIL") : "";
            var strCientos = Centenas(restoCientos);
            return (strMilMillones + " " + strMillones + " " + strMiles + " " + strCientos).replace(/\s+/g, ' ').trim();
        }

        var form = elNumeros.closest('form');
        if (form) {
            form.addEventListener('submit', function() {
                // Antes de enviar a Odoo, volvemos al formato 2.0 (sin puntos de mil)
                elNumeros.value = limpiarNumero(elNumeros.value);
            });
        }
    });
//

document.addEventListener("DOMContentLoaded", function() {

    function setupSignature(config) {
        var fileInput    = document.getElementById(config.fileInputId);
        var preview      = document.getElementById(config.previewId);
        var hiddenInput  = document.getElementById(config.hiddenId);
        var btnQuitar    = document.getElementById(config.btnQuitarId);
        var uploadLabel  = document.getElementById(config.labelId);
        var boolCheck    = document.getElementById(config.checkId);
        var sealLabel    = document.getElementById(config.sealId);

        // Esta línea salva el código de dar error.
        // Como ocultamos fileInput, se detiene aquí y no rompe nada.
        if (!fileInput) return;

        fileInput.addEventListener('change', function(e) {
            var file = e.target.files[0];
            if (file) {
                var reader = new FileReader();
                reader.onload = function(event) {
                    if (preview) {
                        preview.src = event.target.result;
                        preview.style.display = 'block';
                    }
                    if (hiddenInput) {
                        hiddenInput.value = event.target.result.split(',')[1];
                    }
                    if (btnQuitar)   btnQuitar.style.display = 'block';
                    if (uploadLabel) uploadLabel.style.display = 'none';
                    if (boolCheck)   boolCheck.checked = true;
                    if (sealLabel)   sealLabel.style.display = 'block';
                };
                reader.readAsDataURL(file);
            }
        });

        if (btnQuitar) {
            btnQuitar.addEventListener('click', function() {
                fileInput.value = "";
                if (hiddenInput) hiddenInput.value = "";
                if (preview) {
                    preview.src = "#";
                    preview.style.display = 'none';
                }
                btnQuitar.style.display = 'none';
                if (uploadLabel) uploadLabel.style.display = 'block';
                if (boolCheck)   boolCheck.checked = false;
                if (sealLabel)   sealLabel.style.display = 'none';
            });
        }
    }

    // FIRMA 1: CONTRATISTA
    setupSignature({
        fileInputId: 'file_input_firma',
        previewId:   'preview_nueva_firma',
        hiddenId:    'firma_base64',
        btnQuitarId: 'btn_quitar_seleccion',
        labelId:     'label_subir_firma',
        checkId:     'firmado_contratista_check',
        sealId:      'check_digital_label_contratista'
    });

    // FIRMA 2: DECLARANTE
    setupSignature({
        fileInputId: 'file_input_firma_declarante',
        previewId:   'preview_nueva_firma_declarante',
        hiddenId:    'firma_base64_declarante',
        btnQuitarId: 'btn_quitar_declarante',
        labelId:     'label_subir_firma_declarante',
        checkId:     'check_declarante',
        sealId:      'label_chulito_declarante_box' // Usamos el contenedor del check como sello
    });

    (function activarRefirmaAlEditar() {
        var requiereRefirmaDeclaracion = ;
        if (!requiereRefirmaDeclaracion) return;

        var form = document.querySelector('.declaracion-monthly-form');
        if (!form) return;

        var camposFirma = {
            firmado_contratista: true,
            firmado_declarante: true,
            firma_base64: true,
            firma_base64_declarante: true,
            csrf_token: true,
            cuenta_id: true,
            return_url: true
        };
        var avisoId = 'declaracion_refirma_aviso';

        function mostrarAviso() {
            if (document.getElementById(avisoId)) return;
            var aviso = document.createElement('div');
            aviso.id = avisoId;
            aviso.className = 'alert alert-warning mt-3';
            aviso.style.fontWeight = '600';
            aviso.textContent = 'Se modificó información del formulario. Debe marcar nuevamente las firmas electrónicas antes de enviar.';
            form.insertBefore(aviso, form.firstChild.nextSibling);
        }

        function marcarRefirma() {
            ['firmado_contratista_check', 'check_declarante'].forEach(function(id) {
                var check = document.getElementById(id);
                if (check) {
                    check.checked = false;
                    check.disabled = false;
                }
            });
            mostrarAviso();
        }

        window.marcarRefirmaDeclaracion = marcarRefirma;

        function cambioContenido(ev) {
            var target = ev.target;
            if (!target || !target.name || camposFirma[target.name] || target.type === 'hidden') return;
            marcarRefirma();
        }

        form.addEventListener('input', cambioContenido, true);
        form.addEventListener('change', cambioContenido, true);
    })();
});

