function agregarFila() {
    var tbody = document.getElementById("tbl_dependientes").getElementsByTagName('tbody')[0];
    var tr = document.createElement('tr');
    tr.innerHTML = `
        <td><input type="text" name="parentesco[]" class="form-control form-control-sm"/></td>
        <td><input type="number" name="edad[]" class="form-control form-control-sm"/></td>
        <td><input type="text" name="identificacion[]" class="form-control form-control-sm"/></td>
        <td><input type="text" name="nombre[]" class="form-control form-control-sm"/></td>
        <td style="text-align:center; vertical-align: middle;"><input type="checkbox" value="1"/></td>
        <td><input type="text" name="estudios[]" class="form-control form-control-sm"/></td>
        <td><input type="text" name="factor_fisico[]" class="form-control form-control-sm"/></td>
        <td style="text-align: center; vertical-align: middle;">
            <button type="button" onclick="eliminarFila(this)" class="btn btn-danger btn-sm" style="font-weight: bold;">X</button>
        </td>
    `;
    tbody.appendChild(tr);
    renumerarCheckboxes();
    if (window.marcarRefirmaDeclaracion) window.marcarRefirmaDeclaracion();
}

function eliminarFila(btn) {
    var row = btn.closest('tr');
    row.parentNode.removeChild(row);
    renumerarCheckboxes();
    if (window.marcarRefirmaDeclaracion) window.marcarRefirmaDeclaracion();
}

function renumerarCheckboxes() {
    var tbody = document.getElementById("tbl_dependientes").getElementsByTagName('tbody')[0];
    var rows = tbody.rows;
    for (var i = 0; i < rows.length; i++) {
        var checkbox = rows[i].querySelector('input[type="checkbox"]');
        if (checkbox) checkbox.name = "ausencia_ingreso_row" + i;
    }
}
