div.script:
//
document.addEventListener('DOMContentLoaded', function () {
    var form = document.querySelector('.declaracion-monthly-form');
    if (!form) return;
    var confirmacionEnCurso = false;
    var modalConfirmacionDeclaracion = document.getElementById('modal_confirmacion_declaracion');
    var loadingDeclaracion = document.getElementById('loading_overlay_declaracion');

    function mostrarCargaDeclaracion() {
        if (modalConfirmacionDeclaracion) {
            modalConfirmacionDeclaracion.style.display = 'none';
        }
        if (loadingDeclaracion) {
            loadingDeclaracion.style.display = 'flex';
        }
        form.querySelectorAll('button[type="submit"], #btn_enviar_declaracion_juramentada, .sgo-declaracion-confirm-submit').forEach(function(btn) {
            btn.disabled = true;
        });
    }

    function enviarDeclaracionConfirmada() {
        if (form.dataset.enviandoDeclaracion === '1') {
            return;
        }
        form.dataset.enviandoDeclaracion = '1';
        form.dataset.confirmacionVeracidad = '1';
        mostrarCargaDeclaracion();
        window.setTimeout(function () {
            if (form.requestSubmit) {
                form.requestSubmit();
            } else {
                form.submit();
            }
        }, 80);
    }

    var botonConfirmarDeclaracion = form.querySelector('.sgo-declaracion-confirm-submit');
    if (botonConfirmarDeclaracion) {
        botonConfirmarDeclaracion.addEventListener('click', function (evento) {
            evento.preventDefault();
            enviarDeclaracionConfirmada();
        });
    }

    function actualizarAmarilloPendiente(el) {
        if (!el || !el.hasAttribute('data-guide-step')) return;
        var completo = el.type === 'checkbox' || el.type === 'radio'
            ? el.checked
            : Boolean(el.value && el.value.toString().trim());
        el.classList.toggle('sgo-field-pending', !completo);
    }

    var camposContratista = form.querySelectorAll('[data-guide-step]');
    camposContratista.forEach(function(el) {
        actualizarAmarilloPendiente(el);
        el.addEventListener('input', function() {
            actualizarAmarilloPendiente(el);
            actualizarAmarilloPares();
        });
        el.addEventListener('change', function() {
            actualizarAmarilloPendiente(el);
            actualizarAmarilloPares();
        });
    });

    var BORDE_ERROR  = '2px solid #dc3545';
    var BORDE_NORMAL = '1px solid black';
    var ID_HINT      = 'val-hint-';
    var hintCount    = 0;

    // Pares condicionales: al menos uno del par debe tener valor
    var pares = [
        ['servicio_check',        'bien_check'           ],
        ['profesional_check',     'tecnico_check'        ],
        ['pensionado_si',         'pensionado_no'        ],
        ['declarante_si',         'declarante_no'        ],
        ['salud_prepagada_si',    'salud_prepagada_no'   ],
        ['seguros_salud_si',      'seguros_salud_no'     ],
        ['intereses_vivienda_si', 'intereses_vivienda_no'],
    ];
    var gruposExcluyentes = [
        ['sel_cc_nit', 'sel_ce', 'sel_pa'],
        ['check_cop', 'check_usd', 'check_eur'],
    ];

    function actualizarAmarilloPares() {
        pares.forEach(function(par) {
            var elA = form.querySelector('[name="' + par[0] + '"]');
            var elB = form.querySelector('[name="' + par[1] + '"]');
            var completo = valorMarcado(elA) || valorMarcado(elB);
            if (elA) elA.classList.toggle('sgo-field-pending', !completo);
            if (elB) elB.classList.toggle('sgo-field-pending', !completo);
        });
    }
    actualizarAmarilloPares();

    function valorMarcado(el) {
        if (!el) return false;
        if (el.type === 'checkbox' || el.type === 'radio') return el.checked;
        return Boolean(el.value && el.value.trim());
    }

    function camposPorNombre(nombre) {
        return Array.prototype.slice.call(form.querySelectorAll('[name="' + nombre + '"]'));
    }

    function nombresExcluyentesDe(nombre) {
        var excluyentes = [];
        pares.forEach(function(par) {
            if (par[0] === nombre) excluyentes.push(par[1]);
            if (par[1] === nombre) excluyentes.push(par[0]);
        });
        gruposExcluyentes.forEach(function(grupo) {
            if (grupo.indexOf(nombre) !== -1) {
                grupo.forEach(function(nombreGrupo) {
                    if (nombreGrupo !== nombre) excluyentes.push(nombreGrupo);
                });
            }
        });
        return excluyentes;
    }

    function limpiarExcluyentesDesde(campoActual) {
        if (!campoActual || !campoActual.name || !valorMarcado(campoActual)) return;
        nombresExcluyentesDe(campoActual.name).forEach(function(nombreContrario) {
            camposPorNombre(nombreContrario).forEach(function(contrario) {
                if (valorMarcado(contrario)) {
                    if (contrario.type === 'checkbox' || contrario.type === 'radio') {
                        contrario.checked = false;
                    } else {
                        contrario.value = '';
                    }
                    actualizarAmarilloPendiente(contrario);
                    quitarHint(contrario);
                }
            });
        });
        actualizarAmarilloPares();
    }

    function instalarExclusionPares() {
        form.addEventListener('input', function(evento) {
            limpiarExcluyentesDesde(evento.target);
        }, true);
        form.addEventListener('change', function(evento) {
            limpiarExcluyentesDesde(evento.target);
        }, true);
        form.addEventListener('keyup', function(evento) {
            limpiarExcluyentesDesde(evento.target);
        }, true);
        form.addEventListener('paste', function(evento) {
            setTimeout(function() {
                limpiarExcluyentesDesde(evento.target);
            }, 0);
        }, true);

        pares.forEach(function(par) {
            var elA = form.querySelector('[name="' + par[0] + '"]');
            var elB = form.querySelector('[name="' + par[1] + '"]');
            if (!elA || !elB) return;

            function limpiarContrario(origen, contrario) {
                if (valorMarcado(origen) && valorMarcado(contrario)) {
                    if (contrario.type === 'checkbox' || contrario.type === 'radio') {
                        contrario.checked = false;
                    } else {
                        contrario.value = '';
                    }
                    actualizarAmarilloPendiente(contrario);
                }
                actualizarAmarilloPares();
            }

            // Si existen datos antiguos con ambas marcas, al abrir
            // el formulario se conserva solo la primera opción.
            limpiarContrario(elA, elB);

            elA.addEventListener('input', function() { limpiarContrario(elA, elB); });
            elA.addEventListener('change', function() { limpiarContrario(elA, elB); });
            elB.addEventListener('input', function() { limpiarContrario(elB, elA); });
            elB.addEventListener('change', function() { limpiarContrario(elB, elA); });
        });
        gruposExcluyentes.forEach(function(grupo) {
            grupo.forEach(function(nombreActual) {
                var actual = form.querySelector('[name="' + nombreActual + '"]');
                if (!actual) return;

                function limpiarGrupo() {
                    if (!valorMarcado(actual)) return;
                    grupo.forEach(function(nombreOtro) {
                        if (nombreOtro === nombreActual) return;
                        var otro = form.querySelector('[name="' + nombreOtro + '"]');
                        if (otro && valorMarcado(otro)) {
                            if (otro.type === 'checkbox' || otro.type === 'radio') {
                                otro.checked = false;
                            } else {
                                otro.value = '';
                            }
                            actualizarAmarilloPendiente(otro);
                        }
                    });
                    actualizarAmarilloPares();
                }

                actual.addEventListener('input', limpiarGrupo);
                actual.addEventListener('change', limpiarGrupo);
            });
        });
    }
    instalarExclusionPares();

    // Campos individuales obligatorios
    var individuales = [
        'desde_dia', 'desde_mes', 'hasta_dia', 'hasta_mes',
        'arl',
        'valor_numeros', 'detalle_actividad'
    ];
    var requiereRefirmaDeclaracion = <t t-esc="'true' if requiere_refirma_declaracion else 'false'"/>;
    var firmasObligatorias = [
        'firmado_contratista',
        'firmado_declarante'
    ];

    function quitarHint(el) {
        if (el.type === 'checkbox' || el.type === 'radio') {
            el.style.border = '';
        } else {
            el.style.border = BORDE_NORMAL;
        }
        el.style.outline = '';
        el.style.boxShadow = '';
        el.removeAttribute('title');
    }

    function ponerHint(el) {
        quitarHint(el);
        if (el.type === 'radio') {
            el.style.borderRadius = '50%';
            el.style.boxShadow = '0 0 0 3px #dc3545';
        } else if (el.type === 'checkbox') {
            el.style.outline = BORDE_ERROR;
        } else {
            el.style.border = BORDE_ERROR;
        }
        el.title = 'Campo requerido';
        el.addEventListener('input', function () { quitarHint(el); }, { once: true });
        el.addEventListener('change', function () { quitarHint(el); }, { once: true });
    }

    function limpiarTodo() {
        pares.forEach(function(p) {
            [p[0], p[1]].forEach(function(n) {
                var el = form.querySelector('[name="' + n + '"]');
                if (el) quitarHint(el);
            });
        });
        individuales.forEach(function(n) {
            var el = form.querySelector('[name="' + n + '"]');
            if (el) quitarHint(el);
        });
        firmasObligatorias.forEach(function(n) {
            var el = form.querySelector('[name="' + n + '"]');
            if (el) quitarHint(el);
        });
    }

    function validarYConfirmarEnvio(e) {
        if (form.dataset.confirmacionVeracidad === '1') {
            delete form.dataset.confirmacionVeracidad;
            mostrarCargaDeclaracion();
            return;
        }
        e.preventDefault();
        if (confirmacionEnCurso) return;

        limpiarTodo();
        var primero = null;

        // Validar pares
        pares.forEach(function(p) {
            var camposA = camposPorNombre(p[0]);
            var camposB = camposPorNombre(p[1]);
            var elA = camposA[0];
            var elB = camposB[0];
            var marcadosA = camposA.filter(function(el) { return valorMarcado(el); });
            var marcadosB = camposB.filter(function(el) { return valorMarcado(el); });
            var vA = marcadosA.length > 0;
            var vB = marcadosB.length > 0;
            if (vA && vB) {
                marcadosA.concat(marcadosB).forEach(function(el) {
                    ponerHint(el, 'Solo puede marcar una opción');
                });
                if (!primero) primero = marcadosA[0] || marcadosB[0] || elA || elB;
            } else if (!vA && !vB) {
                if (elA) { ponerHint(elA, 'Marque al menos uno'); if (!primero) primero = elA; }
                if (elB) { ponerHint(elB, 'Marque al menos uno'); }
            }
        });

        gruposExcluyentes.forEach(function(grupo) {
            var marcados = grupo.map(function(nombre) {
                return form.querySelector('[name="' + nombre + '"]');
            }).filter(function(el) {
                return valorMarcado(el);
            });
            if (marcados.length > 1) {
                marcados.forEach(function(el) {
                    ponerHint(el, 'Solo puede marcar una opción');
                });
                if (!primero) primero = marcados[0];
            }
        });

        // Validar individuales
        individuales.forEach(function(n) {
            var el = form.querySelector('[name="' + n + '"]');
            if (el && !el.value.trim()) {
                ponerHint(el, 'Campo requerido');
                if (!primero) primero = el;
            }
        });

        if (requiereRefirmaDeclaracion) {
            firmasObligatorias.forEach(function(n) {
                var el = form.querySelector('[name="' + n + '"]');
                if (el && !el.checked) {
                    ponerHint(el, 'Firma requerida');
                    if (!primero) primero = el;
                }
            });
        }

        if (primero) {
            primero.scrollIntoView({ behavior: 'smooth', block: 'center' });
            return;
        }

        var textoDeclaracion = 'Antes de enviar, confirma que revisaste toda la información del Documento equivalente y la Declaración Juramentada y que los datos diligenciados son correctos.';
        confirmacionEnCurso = true;
        if (!window.Swal) {
            if (window.confirm(textoDeclaracion)) {
                form.dataset.confirmacionVeracidad = '1';
                form.requestSubmit();
            }
            confirmacionEnCurso = false;
            return;
        }
        Swal.fire({
            icon: 'warning',
            title: '¿Todo está correcto?',
            text: textoDeclaracion,
            showCancelButton: true,
            confirmButtonText: 'Sí, todo está bien y enviar',
            cancelButtonText: 'Revisar nuevamente',
            confirmButtonColor: '#043484',
            cancelButtonColor: '#6c757d',
            allowOutsideClick: false,
            allowEscapeKey: false
        }).then(function(resultado) {
            confirmacionEnCurso = false;
            if (resultado.isConfirmed) {
                form.dataset.confirmacionVeracidad = '1';
                form.requestSubmit();
            }
        });
    }

    form.addEventListener('submit', validarYConfirmarEnvio, true);
});
