document.addEventListener('DOMContentLoaded', function () {
    var form = document.querySelector('.declaracion-monthly-form');
    if (!form) return;

    var guide = document.querySelector('[data-sgo-declaracion-guide="1"]');
    if (!guide) return;

    var titleEl = guide.querySelector('[data-sgo-declaracion-step-title="1"]');
    var textEl = guide.querySelector('[data-sgo-declaracion-step-text="1"]');
    var statusEl = guide.querySelector('[data-sgo-declaracion-status="1"]');
    var missingEl = guide.querySelector('[data-sgo-declaracion-missing="1"]');
    var soloDeclaracionJuramentada = guide.getAttribute('data-sgo-solo-declaracion') === '1';

    function getField(name) {
        return form.querySelector('[name="' + name + '"]');
    }

    function hasValue(name) {
        var field = getField(name);
        if (!field) return false;
        if (field.type === 'checkbox' || field.type === 'radio') {
            return !!field.checked;
        }
        return !!String(field.value || '').trim();
    }

    function pairDone(a, b) {
        return hasValue(a) || hasValue(b);
    }

    function clearPendingStyles() {
        form.querySelectorAll('.sgo-declaracion-pending-highlight').forEach(function (el) {
            el.classList.remove('sgo-declaracion-pending-highlight');
        });
        form.querySelectorAll('.sgo-declaracion-pending-outline').forEach(function (el) {
            el.classList.remove('sgo-declaracion-pending-outline');
        });
    }

    function markStep(step) {
        var names = step && step.fields ? step.fields : [];

        names.forEach(function (name) {
            var field = getField(name);

            if (!field || field.offsetParent === null) return;

            var target = field.type === 'checkbox' || field.type === 'radio'
                ? (field.closest('label') || field)
                : field;

            if (field.type === 'checkbox' || field.type === 'radio') {
                target.classList.add('sgo-declaracion-pending-outline');
            } else {
                target.classList.add('sgo-declaracion-pending-highlight');
            }
        });
    }
    function getStepTarget(step) {
        var names = step && step.fields ? step.fields : [];
        for (var i = 0; i < names.length; i++) {
            var field = getField(names[i]);
            if (!field || field.offsetParent === null) continue;
            return field.type === 'checkbox' || field.type === 'radio'
                ? (field.closest('label') || field)
                : field;
        }
        return null;
    }

    var scrollTimer = null;
    function scrollToStep(step) {
        var target = getStepTarget(step);
        if (!target) return;
        window.clearTimeout(scrollTimer);
        scrollTimer = window.setTimeout(function () {
            target.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 120);
    }

    function scrollToSubmit() {
        var submitButton = form.querySelector('button[type="submit"]');
        if (!submitButton) return;
        window.clearTimeout(scrollTimer);
        scrollTimer = window.setTimeout(function () {
            submitButton.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 120);
    }

    var steps = [
        {
            title: 'Paso 1: ingresa el consecutivo.',
            text: soloDeclaracionJuramentada ? 'Escribe el consecutivo de la declaración juramentada antes de continuar.' : 'Escribe el consecutivo del documento equivalente antes de continuar.',
            missing: 'Consecutivo',
            fields: ['consecutivo'],
            done: function () { return hasValue('consecutivo'); }
        },
        {
            title: 'Paso 2: completa ARL.',
            text: 'Ingresa la ARL para seguir con la información del formulario.',
            missing: 'ARL',
            fields: ['arl'],
            done: function () { return hasValue('arl'); }
        },
        {
            title: 'Paso 3: marca Servicio o Bien.',
            text: 'Debes completar uno de estos dos campos para definir el tipo principal.',
            missing: 'Servicio o Bien',
            fields: ['servicio_check', 'bien_check'],
            done: function () { return pairDone('servicio_check', 'bien_check'); }
        },
        {
            title: 'Paso 4: define el tipo de servicio prestado.',
            text: 'Completa Profesional o Técnico según corresponda.',
            missing: 'Profesional o Técnico',
            fields: ['profesional_check', 'tecnico_check'],
            done: function () { return pairDone('profesional_check', 'tecnico_check'); }
        },
        {
            title: 'Paso 5: indica si es Pensionado.',
            text: 'Marca SI o NO para continuar.',
            missing: 'Pensionado',
            fields: ['pensionado_si', 'pensionado_no'],
            done: function () { return pairDone('pensionado_si', 'pensionado_no'); }
        },
        {
            title: 'Paso 6: indica si es Declarante de renta.',
            text: 'Marca SI o NO para seguir con el siguiente bloque.',
            missing: 'Declarante de renta',
            fields: ['declarante_si', 'declarante_no'],
            done: function () { return pairDone('declarante_si', 'declarante_no'); }
        },
        {
            title: 'Paso 7: describe la actividad realizada.',
            text: 'Especifica el detalle de la actividad en el recuadro.',
            missing: 'Detalle de la actividad',
            fields: ['detalle_actividad'],
            done: function () { return hasValue('detalle_actividad'); }
        },
        {
            title: 'Paso 10: firma del contratista / proveedor.',
            text: 'Activa la firma electrónica del contratista para continuar.',
            missing: 'Firma del contratista',
            fields: ['firmado_contratista'],
            done: function () { return hasValue('firmado_contratista'); }
        },
        {
            title: 'Paso 7: indica la deducción por salud o medicina prepagada.',
            text: 'Marca SI o NO para continuar con la siguiente deducción.',
            missing: 'Salud o medicina prepagada',
            fields: ['salud_prepagada_si', 'salud_prepagada_no'],
            done: function () { return pairDone('salud_prepagada_si', 'salud_prepagada_no'); }
        },
        {
            title: 'Paso 8: indica la deducción por seguros de salud.',
            text: 'Marca SI o NO para continuar con la siguiente deducción.',
            missing: 'Seguros de salud',
            fields: ['seguros_salud_si', 'seguros_salud_no'],
            done: function () { return pairDone('seguros_salud_si', 'seguros_salud_no'); }
        },
        {
            title: 'Paso 9: indica la deducción por intereses de vivienda.',
            text: 'Marca SI o NO para continuar con las firmas.',
            missing: 'Intereses o corrección monetaria de vivienda',
            fields: ['intereses_vivienda_si', 'intereses_vivienda_no'],
            done: function () { return pairDone('intereses_vivienda_si', 'intereses_vivienda_no'); }
        },
        {
            title: 'Paso 11: firma del declarante.',
            text: 'Finaliza activando la firma electrónica del declarante.',
            missing: 'Firma del declarante',
            fields: ['firmado_declarante'],
            done: function () { return hasValue('firmado_declarante'); }
        }
    ];
    if (soloDeclaracionJuramentada) {
        steps = steps.filter(function (step) {
            return [
                'salud_prepagada_si',
                'seguros_salud_si',
                'intereses_vivienda_si',
                'firmado_declarante'
            ].indexOf((step.fields || [])[0]) !== -1;
        });
    }

    function updateGuide(navigateToPending) {
        clearPendingStyles();
        var pending = steps.find(function (step) { return !step.done(); });
        if (!pending) {
            titleEl.textContent = 'Formulario completo: ya puedes enviarlo.';
            textEl.textContent = 'Ya completaste los campos guiados de la declaración juramentada.';
            statusEl.textContent = 'Completado';
            missingEl.textContent = 'Sin pendientes';
            if (navigateToPending) scrollToSubmit();
            return;
        }

        titleEl.textContent = pending.title;
        textEl.textContent = pending.text;
        statusEl.textContent = 'En proceso';
        missingEl.textContent = pending.missing;
        markStep(pending);
        if (navigateToPending) scrollToStep(pending);
    }

    form.addEventListener('input', function (event) {
        if (event.target && event.target.matches('[data-guide-step]')) {
            updateGuide(false);
        }
    }, true);
    form.addEventListener('change', function (event) {
        if (event.target && event.target.matches('[data-guide-step]')) {
            updateGuide(true);
        }
    }, true);
    updateGuide(false);
});
