form.script:
//
    document.addEventListener('DOMContentLoaded', function () {
        var form = document.querySelector('.informe-monthly-form');
        if (!form) return;
        var informeGuide = document.querySelector('[data-sgo-informe-guide="1"]');
        if (informeGuide) {
            var titleEl = informeGuide.querySelector('[data-sgo-informe-step-title="1"]');
            var textEl = informeGuide.querySelector('[data-sgo-informe-step-text="1"]');
            var statusEl = informeGuide.querySelector('[data-sgo-informe-status="1"]');
            var missingEl = informeGuide.querySelector('[data-sgo-informe-missing="1"]');
            var helpButton = informeGuide.querySelector('[data-sgo-explain-step="1"]');
            var helpText = informeGuide.querySelector('[data-sgo-smart-help-text="1"]');
            var beginnerMode = informeGuide.querySelector('[data-sgo-beginner-mode="1"]');
            var firmaCheck = document.getElementById('check_c') || form.querySelector('[name="firma_contratista_check"]');
            var firmaInlineTarget = document.querySelector('[data-informe-guide-firma="1"]') || form.querySelector('[data-informe-guide-firma="1"]');
            var firmaCellTarget = document.querySelector('[data-informe-guide-firma-cell="1"]') || form.querySelector('[data-informe-guide-firma-cell="1"]');
            var firmaControlTarget = firmaInlineTarget || firmaCellTarget;
            var firmaTarget = firmaControlTarget || firmaCheck;
            var submitTarget = document.querySelector('[data-informe-guide-submit="1"]') || form.querySelector('[data-informe-guide-submit="1"]') || form.querySelector('button[type="submit"]');
            var informeRequiredSteps = [
                {name: 'actividad_anio', label: 'Año de actividad', text: 'Escribe el año del periodo reportado.'},
                {name: 'actividad_mes', label: 'Mes de actividad', text: 'Escribe el mes del periodo reportado.'},
                {name: 'actividad_dia', label: 'Día de actividad', text: 'Escribe el último día de las actividades reportadas.'},
                {name: 'consecutivo', label: 'Consecutivo', text: 'Escribe el número consecutivo del informe.'},
                {name: 'no_contrato2', label: 'No. contrato', text: 'Completa el número de contrato u orden relacionado con el informe.'},
                {name: 'objeto_contrato', label: 'Objeto del contrato', text: 'Revisa o completa el objeto del contrato.'},
                {name: 'descripcion_actividades', label: 'Descripción de las actividades', text: 'Describe las actividades realizadas durante el periodo.'}
            ];

            function clearInformeGuide() {
                document.querySelectorAll('.sgo-informe-pending-highlight').forEach(function (el) {
                    el.classList.remove('sgo-informe-pending-highlight');
                    el.style.outline = '';
                    el.style.outlineOffset = '';
                    el.style.boxShadow = '';
                    el.style.backgroundColor = '';
                });
                document.querySelectorAll('.sgo-informe-firma-highlight').forEach(function (el) {
                    el.classList.remove('sgo-informe-firma-highlight');
                    el.style.outline = '';
                    el.style.outlineOffset = '';
                    el.style.boxShadow = '';
                    el.style.backgroundColor = '';
                });
                if (firmaControlTarget) {
                    firmaControlTarget.style.outline = '';
                    firmaControlTarget.style.outlineOffset = '';
                    firmaControlTarget.style.boxShadow = '';
                    firmaControlTarget.style.backgroundColor = '';
                }
                if (firmaCheck) {
                    firmaCheck.style.outline = '';
                    firmaCheck.style.outlineOffset = '';
                    firmaCheck.style.boxShadow = '';
                    firmaCheck.style.backgroundColor = '';
                }
            }

            function markInformeStep(target) {
                if (!target) return;
                target.classList.add('sgo-informe-pending-highlight');
                if (target === firmaControlTarget) return;
                if (target.querySelector) {
                    var input = target.querySelector('input:not([type="checkbox"]), textarea, select');
                    if (input) input.classList.add('sgo-informe-pending-highlight');
                }
            }

            function markInformeFirma() {
                var target = firmaControlTarget || firmaCheck;
                if (!target) return;
                target.classList.add('sgo-informe-firma-highlight');
                target.style.outline = '2px solid #0d6efd';
                target.style.outlineOffset = '3px';
                target.style.boxShadow = '0 0 0 4px rgba(13, 110, 253, 0.14)';
                target.style.backgroundColor = '#eef6ff';
            }

            function scrollToInformeTarget(target) {
                if (!target) return;
                window.setTimeout(function () {
                    var scrollParent = target.parentElement;
                    while (scrollParent && scrollParent !== document.body) {
                        var style = window.getComputedStyle(scrollParent);
                        var canScroll = /(auto|scroll)/.test(style.overflowY + style.overflow) && scrollParent.scrollHeight > scrollParent.clientHeight;
                        if (canScroll) break;
                        scrollParent = scrollParent.parentElement;
                    }
                    if (scrollParent && scrollParent !== document.body) {
                        var parentRect = scrollParent.getBoundingClientRect();
                        var targetRect = target.getBoundingClientRect();
                        scrollParent.scrollTo({
                            top: scrollParent.scrollTop + targetRect.top - parentRect.top - (scrollParent.clientHeight / 2) + (targetRect.height / 2),
                            behavior: 'smooth'
                        });
                    } else {
                        var rect = target.getBoundingClientRect();
                        var targetTop = window.pageYOffset + rect.top - Math.max(80, (window.innerHeight - rect.height) / 2);
                        window.scrollTo({ top: Math.max(0, targetTop), behavior: 'smooth' });
                    }
                    var focusable = target.matches && target.matches('input, textarea, select, button, a[href]')
                        ? target
                        : (target.querySelector ? target.querySelector('input, textarea, select, button, a[href]') : null);
                    if (focusable && focusable.focus) {
                        try { focusable.focus({ preventScroll: true }); } catch (error) {}
                    }
                }, 160);
            }

            function cleanInformeValue(value) {
                return (value || '').toString().replace(/\s+/g, ' ').trim();
            }

            function isInformeFieldEmpty(field) {
                if (!field) return false;
                if (field.type === 'checkbox' || field.type === 'radio') {
                    return !field.checked;
                }
                return cleanInformeValue(field.value) === '';
            }

            function firstInformePendingField() {
                for (var i = 0; i < informeRequiredSteps.length; i++) {
                    var step = informeRequiredSteps[i];
                    var field = form.querySelector('[name="' + step.name + '"]');
                    if (field && isInformeFieldEmpty(field)) {
                        return {
                            label: step.label,
                            text: step.text,
                            target: field,
                            field: field
                        };
                    }
                }

                return null;
            }

            function setInformeHelp(missing, text) {
                if (!helpText) return;
                if (missing === 'Firma electrónica') {
                    helpText.innerHTML = 'Marca la casilla <strong>Firma electrónica Ley 527 de 1999</strong> para aceptar y firmar el informe.';
                } else if (missing === 'Enviar Informe') {
                    helpText.innerHTML = 'Presiona <strong>Enviar Informe</strong> para continuar.';
                } else {
                    helpText.innerHTML = text || ('Completa el campo <strong>' + missing + '</strong> para continuar.');
                }
            }

            function setInformeGuide(title, text, status, missing, target, helpMessage) {
                if (titleEl) titleEl.textContent = title;
                if (textEl) textEl.textContent = text;
                if (statusEl) statusEl.textContent = status;
                if (missingEl) missingEl.textContent = missing;
                setInformeHelp(missing, helpMessage);
                clearInformeGuide();
                markInformeStep(target);
            }

            function updateInformeGuide(scrollToTarget) {
                var target = null;
                var pendingField = firstInformePendingField();
                if (pendingField) {
                    target = pendingField.target;
                    setInformeGuide(
                        'Paso: completa ' + pendingField.label + '.',
                        pendingField.text,
                        'En proceso',
                        pendingField.label,
                        target,
                        'Completa <strong>' + pendingField.label + '</strong> para poder firmar el informe.'
                    );
                } else if (firmaCheck && !firmaCheck.checked) {
                    target = firmaControlTarget || firmaCheck;
                    setInformeGuide(
                        'Paso: firma el informe.',
                        'Marca la firma electrónica Ley 527 de 1999 solo cuando hayas revisado la información.',
                        'En proceso',
                        'Firma electrónica',
                        firmaControlTarget || firmaCheck
                    );
                    markInformeFirma();
                } else {
                    target = submitTarget;
                    setInformeGuide(
                        'Todo listo: puedes enviar el informe.',
                        'El informe ya tiene la firma requerida. Presiona Enviar Informe para continuar.',
                        'Completado',
                        'Enviar Informe',
                        target
                    );
                }
                if (scrollToTarget) {
                    scrollToInformeTarget(target);
                }
            }

            if (firmaCheck) {
                ['click', 'input', 'change'].forEach(function (eventName) {
                    firmaCheck.addEventListener(eventName, function () {
                        window.setTimeout(function () {
                            updateInformeGuide(true);
                        }, 0);
                    }, true);
                });
            }
            document.addEventListener('change', function (event) {
                if (event.target && event.target === firmaCheck) {
                    window.setTimeout(function () {
                        updateInformeGuide(true);
                    }, 0);
                }
            }, true);
            informeRequiredSteps.forEach(function (step) {
                var field = form.querySelector('[name="' + step.name + '"]');
                if (field) {
                    field.addEventListener('input', function () {
                        updateInformeGuide(false);
                    });
                    field.addEventListener('change', function () {
                        updateInformeGuide(true);
                    });
                }
            });
            if (helpButton) {
                helpButton.addEventListener('click', function () {
                    if (helpText) {
                        helpText.classList.toggle('is-visible');
                    }
                    updateInformeGuide(true);
                });
            }
            if (beginnerMode) {
                beginnerMode.addEventListener('change', function () {
                    updateInformeGuide(true);
                });
            }
            // Esta es la guía principal: primero recorre fecha,
            // consecutivo y actividades; después solicita la firma.
            window.sgoInformeActividadesGuide = updateInformeGuide;
            updateInformeGuide(false);
            window.setTimeout(function () {
                updateInformeGuide(true);
            }, 500);
            window.setTimeout(function () {
                updateInformeGuide(true);
            }, 1200);
            window.addEventListener('load', function () {
                updateInformeGuide(true);
            }, { once: true });
        }
        var requiereRefirmaInforme = <t t-esc="'true' if requiere_refirma_informe else 'false'"/>;
        if (!requiereRefirmaInforme) return;

        var camposFirma = {
        firma_contratista_check: true,
        firma_contratista_img: true,
        csrf_token: true,
        cuenta_id: true,
        informe_id: true,
        relacion_id: true
    };
    var avisoId = 'informe_refirma_aviso';

    function mostrarAviso() {
        if (document.getElementById(avisoId)) return;
        var aviso = document.createElement('div');
        aviso.id = avisoId;
        aviso.className = 'alert alert-warning mt-3';
        aviso.style.fontWeight = '600';
        aviso.textContent = 'Se modificó información del informe. Debe marcar nuevamente la firma electrónica antes de enviar.';
        form.insertBefore(aviso, form.firstChild.nextSibling);
    }

    function marcarRefirma() {
        var check = document.getElementById('check_c');
        if (check) {
            check.checked = false;
            check.disabled = false;
        }
        mostrarAviso();
    }

    function cambioContenido(ev) {
        var target = ev.target;
        if (!target || !target.name || camposFirma[target.name] || target.type === 'hidden') return;
        marcarRefirma();
    }

    form.addEventListener('input', cambioContenido, true);
    form.addEventListener('change', cambioContenido, true);

    form.addEventListener('submit', function (e) {
        var check = document.getElementById('check_c');
        if (check && !check.checked) {
            e.preventDefault();
            check.style.outline = '2px solid #dc3545';
            check.title = 'Firma requerida';
            check.scrollIntoView({ behavior: 'smooth', block: 'center' });
            check.addEventListener('change', function () {
                check.style.outline = '';
                check.removeAttribute('title');
            }, { once: true });
        }
    });
});
//

//
    (function () {
        function initInformeGuideDirect() {
            // La guía completa se inicializa en el bloque principal del
            // informe. Este bloque antiguo no debe sobrescribirla.
            if (document.querySelector('[data-sgo-informe-guide="1"]')) return;
            var form = document.querySelector('.informe-monthly-form');
            var guide = document.querySelector('[data-sgo-informe-guide="1"]');
            var check = document.getElementById('check_c') || document.querySelector('[name="firma_contratista_check"]');
            var firmaCell = document.querySelector('[data-informe-guide-firma-cell="1"]');
            var firmaBox = document.querySelector('[data-informe-guide-firma="1"]');
            var firmaTarget = firmaBox || firmaCell || check;
            var submitBtn = document.querySelector('[data-informe-guide-submit="1"]') || (form ? form.querySelector('button[type="submit"]') : null);
            if (!form || !guide || !check) return;

            var titleEl = guide.querySelector('[data-sgo-informe-step-title="1"]');
            var textEl = guide.querySelector('[data-sgo-informe-step-text="1"]');
            var statusEl = guide.querySelector('[data-sgo-informe-status="1"]');
            var missingEl = guide.querySelector('[data-sgo-informe-missing="1"]');
            var helpText = guide.querySelector('[data-sgo-smart-help-text="1"]');
            var beginnerMode = guide.querySelector('[data-sgo-beginner-mode="1"]');
            var helpButton = guide.querySelector('[data-sgo-explain-step="1"]');

            function setText(el, text) {
                if (el) el.textContent = text;
            }

            function clearTarget(el) {
                if (!el) return;
                el.classList.remove('sgo-informe-guide-direct-highlight');
                el.classList.remove('sgo-informe-active-target');
                el.style.outline = '';
                el.style.outlineOffset = '';
                el.style.boxShadow = '';
                el.style.backgroundColor = '';
            }

            function clearMarks() {
                document.querySelectorAll('.sgo-informe-guide-direct-highlight, .sgo-informe-active-target').forEach(clearTarget);
                clearTarget(firmaCell);
                clearTarget(firmaBox);
                clearTarget(submitBtn);
            }

            function markTarget(el) {
                if (!el) return;
                el.classList.add('sgo-informe-guide-direct-highlight');
                el.classList.add('sgo-informe-active-target');
                el.style.outline = '2px solid #0d6efd';
                el.style.outlineOffset = '3px';
                el.style.boxShadow = '0 0 0 4px rgba(13, 110, 253, 0.14)';
                el.style.backgroundColor = '#eef6ff';
            }

            function scrollToTarget(el) {
                if (!el) return;
                window.setTimeout(function () {
                    try {
                        el.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
                    } catch (error) {
                        el.scrollIntoView();
                    }

                    var parent = el.parentElement;
                    while (parent && parent !== document.body) {
                        var style = window.getComputedStyle(parent);
                        var scrollable = /(auto|scroll)/.test(style.overflowY + style.overflow) && parent.scrollHeight > parent.clientHeight;
                        if (scrollable) {
                            var parentRect = parent.getBoundingClientRect();
                            var elRect = el.getBoundingClientRect();
                            parent.scrollTo({
                                top: parent.scrollTop + elRect.top - parentRect.top - (parent.clientHeight / 2) + (elRect.height / 2),
                                behavior: 'smooth'
                            });
                        }
                        parent = parent.parentElement;
                    }
                }, 150);
            }

            function refreshGuide(moveToTarget) {
                clearMarks();
                if (check.checked) {
                    setText(titleEl, 'Todo listo: envía el informe.');
                    setText(textEl, 'La firma electrónica ya está marcada. Presiona Enviar Informe para continuar.');
                    setText(statusEl, 'Completado');
                    setText(missingEl, 'Enviar Informe');
                    if (helpText) {
                        helpText.innerHTML = 'Presiona <strong>Enviar Informe</strong> para terminar el proceso.';
                    }
                    markTarget(submitBtn);
                    if (moveToTarget) scrollToTarget(submitBtn);
                } else {
                    setText(titleEl, 'Paso 1: firma el informe.');
                    setText(textEl, 'Marca la firma electrónica Ley 527 de 1999 solo cuando hayas revisado la información.');
                    setText(statusEl, 'En proceso');
                    setText(missingEl, 'Firma electrónica');
                    if (helpText) {
                        helpText.innerHTML = 'Activa la firma electrónica solo cuando hayas revisado que la información está completa y correcta.';
                    }
                    markTarget(firmaTarget);
                    if (moveToTarget) scrollToTarget(firmaTarget);
                }
            }

            window.sgoInformeActividadesGuide = refreshGuide;

            ['click', 'change', 'input'].forEach(function (eventName) {
                check.addEventListener(eventName, function () {
                    window.setTimeout(function () {
                        refreshGuide(true);
                    }, 60);
                }, true);
            });
            if (beginnerMode) {
                beginnerMode.addEventListener('change', function () {
                    refreshGuide(true);
                }, true);
            }
            if (helpButton) {
                helpButton.addEventListener('click', function () {
                    if (helpText) helpText.classList.add('is-visible');
                    refreshGuide(true);
                }, true);
            }

            refreshGuide(false);
            window.setTimeout(function () {
                refreshGuide(true);
            }, 650);
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initInformeGuideDirect);
        } else {
            initInformeGuideDirect();
        }
    })();
