template.script:
//
document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.js-sgo-profile-bell').forEach(function (bell) {
        bell.addEventListener('click', function () {
            var badge = bell.querySelector('.js-sgo-profile-count');
            if (badge) badge.style.display = 'none';
            var loginId = bell.dataset.loginId;
            var token = bell.dataset.token;
            if (!loginId || !token) return;
            fetch('/public/notifications/read/' + loginId + '/' + token, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({jsonrpc:'2.0', method:'call', params:{}})}).catch(function () {});
        });
    });
    document.querySelectorAll('.js-sgo-profile-delete').forEach(function (button) {
        button.addEventListener('click', function (event) {
            event.preventDefault(); event.stopPropagation();
            var wrap = button.closest('.sgo-global-profile-wrap');
            var bell = wrap && wrap.querySelector('.js-sgo-profile-bell');
            var item = button.closest('.js-sgo-profile-notification');
            if (!bell || !button.dataset.key) return;
            fetch('/public/notifications/delete/' + bell.dataset.loginId + '/' + bell.dataset.token, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({jsonrpc:'2.0', method:'call', params:{key:button.dataset.key}})})
                .then(function (response) { return response.json(); })
                .then(function (data) { if (data && data.result && data.result.ok && item) item.remove(); })
                .catch(function () {});
        });
    });
});
