xpath.script:
//
document.addEventListener('DOMContentLoaded', function () {
    function normalize(text) {
        return (text || '').toString().toLowerCase()
            .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    }

    function clean(text) {
        return (text || '').toString()
            .replace(/[✔✘*?]/g, '')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function initInformeActivitiesGuideFallback() {
        var form = document.querySelector('.informe-monthly-form');
        if (!form) return;
        var guide = document.querySelector('[data-sgo-informe-guide="1"]');
        var check = form.querySelector('[name="firma_contratista_check"]');
        var firmaTarget = form.querySelector('[data-informe-guide-firma="1"]') || form.querySelector('[data-informe-guide-firma-cell="1"]') || check;
        var submitTarget = form.querySelector('[data-informe-guide-submit="1"]') || form.querySelector('button[type="submit"]');
        if (!guide || !check) return;

        var titleEl = guide.querySelector('[data-sgo-informe-step-title="1"]');
        var textEl = guide.querySelector('[data-sgo-informe-step-text="1"]');
        var statusEl = guide.querySelector('[data-sgo-informe-status="1"]');
        var missingEl = guide.querySelector('[data-sgo-informe-missing="1"]');
        var helpText = guide.querySelector('[data-sgo-smart-help-text="1"]');
        var requiredSteps = [
            {name: 'actividad_anio', label: 'Año de actividad', text: 'Revisa o escribe el año del periodo reportado.'},
            {name: 'actividad_mes', label: 'Mes de actividad', text: 'Revisa o escribe el mes del periodo reportado.'},
            {name: 'actividad_dia', label: 'Día de actividad', text: 'Revisa o escribe el último día de las actividades reportadas.'},
            {name: 'consecutivo', label: 'Consecutivo', text: 'Escribe el número consecutivo del informe.'},
            {name: 'no_contrato2', label: 'No. contrato', text: 'Completa el número de contrato u orden relacionado con el informe.'},
            {name: 'objeto_contrato', label: 'Objeto del contrato', text: 'Revisa o completa el objeto del contrato.'},
            {name: 'descripcion_actividades', label: 'Descripción de las actividades', text: 'Escribe las actividades realizadas durante el periodo.'}
        ];

        function setText(el, text) {
            if (el) el.textContent = text;
        }

        function clearInformeMarks() {
            document.querySelectorAll('.sgo-informe-active-target, .sgo-informe-guide-direct-highlight, .sgo-informe-firma-highlight, .sgo-informe-pending-highlight').forEach(function (el) {
                el.classList.remove('sgo-informe-active-target', 'sgo-informe-guide-direct-highlight', 'sgo-informe-firma-highlight', 'sgo-informe-pending-highlight');
                el.style.outline = '';
                el.style.outlineOffset = '';
                el.style.boxShadow = '';
                el.style.backgroundColor = '';
            });
        }

        function markInformeTarget(target) {
            if (!target) return;
            target.classList.add('sgo-informe-active-target');
            target.style.outline = '2px solid #0d6efd';
            target.style.outlineOffset = '3px';
            target.style.boxShadow = '0 0 0 4px rgba(13, 110, 253, 0.16)';
        }

        function scrollInformeTarget(target) {
            if (!target) return;
            window.setTimeout(function () {
                try {
                    target.scrollIntoView({behavior: 'smooth', block: 'center', inline: 'nearest'});
                } catch (error) {
                    target.scrollIntoView();
                }
                var parent = target.parentElement;
                while (parent && parent !== document.body) {
                    var style = window.getComputedStyle(parent);
                    var isScrollable = /(auto|scroll)/.test(style.overflowY + style.overflow) && parent.scrollHeight > parent.clientHeight;
                    if (isScrollable) {
                        var parentRect = parent.getBoundingClientRect();
                        var targetRect = target.getBoundingClientRect();
                        parent.scrollTo({
                            top: parent.scrollTop + targetRect.top - parentRect.top - (parent.clientHeight / 2) + (targetRect.height / 2),
                            behavior: 'smooth'
                        });
                    }
                    parent = parent.parentElement;
                }
            }, 120);
        }

        function updateInformeGuide(moveToTarget) {
            var target;
            clearInformeMarks();
            var pending = null;
            for (var index = 0; index < requiredSteps.length; index++) {
                var step = requiredSteps[index];
                var field = form.querySelector('[name="' + step.name + '"]');
                if (field && !(field.value || '').toString().trim()) {
                    pending = {step: step, field: field};
                    break;
                }
            }

            if (pending) {
                target = pending.field;
                setText(titleEl, 'Paso: completa ' + pending.step.label + '.');
                setText(textEl, pending.step.text);
                setText(statusEl, 'En proceso');
                setText(missingEl, pending.step.label);
                if (helpText) {
                    helpText.innerHTML = 'Completa <strong>' + pending.step.label + '</strong> antes de firmar el informe.';
                }
            } else if (check.checked) {
                target = submitTarget;
                setText(titleEl, 'Todo listo: envía el informe.');
                setText(textEl, 'La firma electrónica ya está marcada. Presiona Enviar Informe para continuar.');
                setText(statusEl, 'Completado');
                setText(missingEl, 'Enviar Informe');
                if (helpText) {
                    helpText.innerHTML = 'Presiona <strong>Enviar Informe</strong> para terminar el proceso.';
                }
            } else {
                target = firmaTarget;
                setText(titleEl, 'Paso 1: firma el informe.');
                setText(textEl, 'Marca la firma electrónica Ley 527 de 1999 solo cuando hayas revisado la información.');
                setText(statusEl, 'En proceso');
                setText(missingEl, 'Firma electrónica');
                if (helpText) {
                    helpText.innerHTML = 'Activa la firma electrónica solo cuando hayas revisado que la información está completa y correcta.';
                }
            }
            markInformeTarget(target);
            if (moveToTarget) scrollInformeTarget(target);
        }

        window.sgoInformeActividadesGuide = updateInformeGuide;
        check.addEventListener('change', function () {
            updateInformeGuide(true);
        }, true);
        check.addEventListener('click', function () {
            window.setTimeout(function () {
                updateInformeGuide(true);
            }, 80);
        }, true);
        requiredSteps.forEach(function (step) {
            var field = form.querySelector('[name="' + step.name + '"]');
            if (!field) return;
            field.addEventListener('input', function () {
                updateInformeGuide(false);
            }, true);
            field.addEventListener('change', function () {
                updateInformeGuide(true);
            }, true);
        });

        updateInformeGuide(false);
        window.setTimeout(function () {
            updateInformeGuide(true);
        }, 700);
    }

    initInformeActivitiesGuideFallback();

    function labelForField(field) {
        if (!field) return '';
        var id = field.getAttribute('id');
        var label = id ? document.querySelector('label[for="' + id + '"]') : null;
        if (!label) {
            var scope = field.closest('.doc-cell-container, .doc-table-row, tr, .col-md-12, .col-md-6, .col-md-4, .mb-3, td, div') || field.parentElement;
            label = scope ? scope.querySelector('label') : null;
        }
        return clean(label ? label.textContent : (field.getAttribute('name') || field.getAttribute('placeholder') || 'este campo'));
    }

    function helpFor(label, field) {
        var key = normalize([label, field && field.name, field && field.id, field && field.placeholder].join(' '));
        var compactKey = key.replace(/[\s_-]+/g, '');

        if (key.indexOf('consecutivo') !== -1) {
            return 'Escribe el número consecutivo de esta cuenta o documento. Si ya lo diligenciaste en la declaración juramentada, puedes usar ese mismo número y ajustarlo si corresponde.';
        }
        if (key.indexOf('ayuda del dia') !== -1 || key.indexOf('ayuda del día') !== -1 || key.indexOf('ultimo dia') !== -1 || key.indexOf('último día') !== -1) {
            return 'El ícono informativo te recuerda que el día del informe corresponde al último día de las actividades reportadas.';
        }
        if (key.indexOf('selecionar') !== -1 || key.indexOf('seleccionar tipo') !== -1 || key.indexOf('tipo de contrato') !== -1) {
            return 'Selecciona el tipo de contrato: contrato, orden de compra u otrosí. Con esa opción se cargan las relaciones disponibles.';
        }
        if (key.indexOf('relacion') !== -1 || key.indexOf('seleccionar contrato') !== -1 || key.indexOf('seleccionar orden') !== -1 || key.indexOf('seleccionar otrosi') !== -1) {
            return 'Escoge la relación que corresponde a esta cuenta de cobro. Si aparecen varias, elige la que coincida con el contrato, orden u otrosí que estás cobrando.';
        }
        if (key.indexOf('fecha radicacion') !== -1 || key.indexOf('fecha de radicacion') !== -1) {
            return 'Selecciona la fecha en la que estás radicando esta cuenta de cobro.';
        }
        if (key.indexOf('quien entrega') !== -1 || key.indexOf('nombre de quien entrega') !== -1 || key.indexOf('escriba el nombre') !== -1) {
            return 'Escribe el nombre completo de la persona que entrega o radica la cuenta de cobro.';
        }
        if (key.indexOf('correo electronico') !== -1 || key.indexOf('correo') !== -1 || key.indexOf('email') !== -1) {
            return 'Revisa que el correo electrónico esté correcto. Allí pueden llegarte notificaciones sobre esta cuenta.';
        }
        if (key.indexOf('valor cuenta') !== -1 || key.indexOf('valor factura') !== -1) {
            return 'Primero señala tu desembolso en Forma de pago. El sistema cargará el valor definido y podrás editarlo hacia abajo si solo cobras los días efectivamente trabajados; nunca puede superar el desembolso seleccionado.';
        }
        if (key.indexOf('porcentaje') !== -1 || key.indexOf('%') !== -1) {
            return 'Indica el porcentaje que representa este cobro dentro del contrato o forma de pago. Si el sistema lo calcula, solo revisa que sea coherente.';
        }
        if (key.indexOf('pago') !== -1 && key.indexOf('forma') === -1) {
            return 'Escribe el número de pago que corresponde a esta cuenta de cobro.';
        }
        if (key.indexOf('inicio actividad') !== -1 || key.indexOf('inicio de actividad') !== -1 || key.indexOf('inicio_actividad') !== -1 || compactKey.indexOf('inicioactividad') !== -1 || compactKey.indexOf('iniciodeactividad') !== -1) {
            return 'Selecciona la fecha de inicio de actividades.';
        }
        if (key.indexOf('finalizacion actividad') !== -1 || key.indexOf('finalizacion de actividad') !== -1 || key.indexOf('finalización actividad') !== -1 || key.indexOf('finalización de actividad') !== -1 || key.indexOf('finalizacion_actividad') !== -1 || compactKey.indexOf('finalizacionactividad') !== -1 || compactKey.indexOf('finalizaciondeactividad') !== -1) {
            return 'Selecciona la fecha de finalización de actividades.';
        }
        if (key.indexOf('planilla') !== -1 || key.indexOf('seguridad social') !== -1 || key.indexOf('pila') !== -1) {
            return 'Sube la planilla de seguridad social.';
        }
        if (key.indexOf('rut') !== -1) {
            return 'Sube el RUT actualizado. Revisa que el documento corresponda al contratista o proveedor y que sea legible.';
        }
        if (key.indexOf('camara') !== -1 || key.indexOf('cámara') !== -1 || key.indexOf('comercio') !== -1) {
            return 'Sube la Cámara de Comercio actualizada. Úsala para persona jurídica cuando aplique.';
        }
        if (key.indexOf('factura') !== -1) {
            return 'Sube la factura electrónica correspondiente a esta cuenta de cobro. Verifica que el número y el valor coincidan.';
        }
        if (key.indexOf('parafiscal') !== -1) {
            return 'Sube el certificado o soporte de pago de parafiscales del periodo correspondiente.';
        }
        if (key.indexOf('expensa') !== -1) {
            return 'Sube el certificado de expensas solo si aplica para tu caso. Si no aplica, puedes continuar con los documentos requeridos.';
        }
        if (key.indexOf('informe') !== -1 && key.indexOf('actividad') !== -1) {
            return 'El informe de actividades describe lo realizado durante el periodo cobrado. Si el sistema lo genera, usa el botón de crear informe; si traes informes externos, súbelos en Informes.';
        }
        if (key.indexOf('informes') !== -1) {
            return 'Este campo es opcional. Puedes subir uno o varios informes externos que sirvan como soporte adicional de la cuenta.';
        }
        if (key.indexOf('documento adicional') !== -1 || key.indexOf('adicional') !== -1) {
            return 'Este campo es opcional. Actívalo solo si necesitas adjuntar uno o varios soportes extra para la revisión de la cuenta.';
        }
        if (key.indexOf('documento equivalente') !== -1 || key.indexOf('declaracion juramentada') !== -1 || key.indexOf('declaración juramentada') !== -1) {
            return 'Crea o completa el documento equivalente y declaración juramentada. Allí debes revisar el consecutivo, datos del periodo, actividad, valor y firmas.';
        }
        if (key.indexOf('id rep') !== -1 || key.indexOf('representante legal') !== -1) {
            return 'Sube el documento de identidad del representante legal cuando la cuenta sea de persona jurídica.';
        }
        if (key.indexOf('contador') !== -1 || key.indexOf('revisor fiscal') !== -1 || key.indexOf('junta') !== -1) {
            return 'Adjunta el soporte del contador o revisor fiscal según corresponda: documento de identidad, tarjeta profesional o certificado de junta.';
        }
        if (key.indexOf('arl') !== -1) {
            return 'Escribe la ARL registrada para el contratista o proveedor.';
        }
        if (key.indexOf('servicio') !== -1 || key.indexOf('bien') !== -1) {
            return 'Marca o escribe si corresponde a servicio o bien. Completa solo la opción que aplique.';
        }
        if (key.indexOf('profesional') !== -1 || key.indexOf('tecnico') !== -1 || key.indexOf('técnico') !== -1) {
            return 'Indica si el servicio prestado corresponde a perfil profesional o técnico.';
        }
        if (key.indexOf('firma') !== -1 || key.indexOf('firmado') !== -1) {
            return 'Activa la firma electrónica solo cuando hayas revisado que la información está completa y correcta.';
        }
        if (key.indexOf('pensionado') !== -1 || key.indexOf('declarante') !== -1) {
            return 'Marca SI o NO según la condición del contratista. No dejes las dos opciones vacías.';
        }
        if (key.indexOf('detalle') !== -1 || key.indexOf('actividad realizada') !== -1 || key.indexOf('descripcion') !== -1 || key.indexOf('descripción') !== -1) {
            return 'Describe de forma clara la actividad realizada durante el periodo. Ejemplo: apoyo técnico, gestión administrativa, revisión de documentos o actividades propias del contrato.';
        }
        if (key.indexOf('crear cuenta') !== -1) {
            return 'Cuando todo esté listo, presiona Crear cuenta de cobro para enviar la información a revisión.';
        }

        return 'Completa este campo con el dato que pide su etiqueta. Si no aplica para tu caso, continúa con el siguiente campo requerido.';
    }

    function guideMissingLabel(guide) {
        var missing = guide.querySelector('[data-sgo-guide-missing="1"], [data-sgo-declaracion-missing="1"], [data-sgo-informe-missing="1"]');
        if (missing && clean(missing.textContent)) return clean(missing.textContent);
        var title = guide.querySelector('[data-sgo-guide-title="1"], [data-sgo-declaracion-step-title="1"], [data-sgo-informe-step-title="1"]');
        return title ? clean(title.textContent) : 'este paso';
    }

    function showHelp(guide, label, field) {
        var helpBox = guide.querySelector('[data-sgo-smart-help-text="1"]');
        if (!helpBox) return;
        var helpText = helpFor(label || guideMissingLabel(guide), field);
        if (helpBox.textContent !== helpText) {
            helpBox.textContent = helpText;
        }
        helpBox.classList.add('is-visible');
    }

    function pendingCaptionFor(label, guide) {
        var text = clean(label).toLowerCase();
        var title = guide ? clean((guide.querySelector('[data-sgo-guide-title="1"], [data-sgo-declaracion-step-title="1"], [data-sgo-informe-step-title="1"], #portalGuideStep') || {}).textContent).toLowerCase() : "";
        var combined = (title + " " + text).trim();

        if (!combined || combined.indexOf('no hay') !== -1 || combined.indexOf('todo listo') !== -1 || combined.indexOf('listo') === 0) {
            return 'Estado';
        }

        if (/^(crear|finalizar|enviar|generar|firmar|ver|guardar)\b/.test(text) || combined.indexOf('presiona el botón') !== -1 || combined.indexOf('botón') !== -1) {
            return 'Botón a presionar';
        }

        if (combined.indexOf('documento') !== -1 || combined.indexOf('archivo') !== -1 || combined.indexOf('carga') !== -1 || combined.indexOf('sube') !== -1 || combined.indexOf('seleccionar archivo') !== -1) {
            return 'Documento pendiente';
        }

        return 'Campo pendiente';
    }

    function updatePendingCaption(guide) {
        if (!guide) return;
        var missing = guide.querySelector('[data-sgo-guide-missing="1"], [data-sgo-declaracion-missing="1"], [data-sgo-informe-missing="1"], #portalGuideMissing');
        if (!missing) return;
        var box = missing.closest('.sgo-portal-guide-pill, .sgo-declaracion-guide-pill, .sgo-informe-guide-pill, .portal-form-guide-box');
        var caption = box ? box.querySelector('span, .portal-form-guide-label') : null;
        if (!caption) return;
        var nextCaption = pendingCaptionFor(missing.textContent, guide);
        if (clean(caption.textContent) !== nextCaption) {
            caption.textContent = nextCaption;
        }
    }

    document.querySelectorAll('#portalFormGuide, [data-sgo-portal-guide="1"], [data-sgo-declaracion-guide="1"], [data-sgo-informe-guide="1"]').forEach(function (guide) {
        updatePendingCaption(guide);
        var captionObserver = new MutationObserver(function () {
            updatePendingCaption(guide);
        });
        captionObserver.observe(guide, {childList: true, subtree: true, characterData: true});
    });

    document.querySelectorAll('[data-sgo-portal-guide="1"], [data-sgo-declaracion-guide="1"], [data-sgo-informe-guide="1"]').forEach(function (guide) {
        var button = guide.querySelector('[data-sgo-explain-step="1"]');
        var beginner = guide.querySelector('[data-sgo-beginner-mode="1"]');
        var form = guide.closest('form');
        var lastField = null;

        if (button) {
            button.addEventListener('click', function () {
                if (beginner && !beginner.checked) beginner.checked = true;
                var field = lastField && document.body.contains(lastField) ? lastField : null;
                showHelp(guide, field ? labelForField(field) : guideMissingLabel(guide), field);
            });
        }

        if (beginner) {
            beginner.addEventListener('change', function () {
                var helpBox = guide.querySelector('[data-sgo-smart-help-text="1"]');
                if (beginner.checked) {
                    showHelp(guide, guideMissingLabel(guide), null);
                } else if (helpBox) {
                    helpBox.classList.remove('is-visible');
                }
            });

            var observer = new MutationObserver(function () {
                if (beginner.checked) showHelp(guide, guideMissingLabel(guide), null);
            });
            observer.observe(guide, {childList: true, subtree: true, characterData: true});
        }

        if (form) {
            form.addEventListener('focusin', function (event) {
                if (beginner && !beginner.checked) return;
                var field = event.target;
                if (!field || !field.matches || !field.matches('input, select, textarea')) return;
                lastField = field;
                showHelp(guide, labelForField(field), field);
            }, true);

            form.addEventListener('click', function (event) {
                if (beginner && !beginner.checked) return;
                var field = event.target;
                if (!field || !field.matches || !field.matches('input, select, textarea')) return;
                lastField = field;
                showHelp(guide, labelForField(field), field);
            }, true);
        }
    });
});
